    { en = "Cowering in fear.", ua = "Тремтить від страху." },
    { en = "Damage taken reduced by $s1%. Healing for $<heal>% of maximum health.\n\nCannot attack or cast spells.\n\nMovement speed increased by $s4% and immune to all movement impairing effects.", ua = "Отримувана шкода зменшена на $s1%. Зцілює на $<heal>% максимального здоров'я.\n\nНеможливо атакувати чи творити закляття.\n\nШвидкість пересування збільшена на $s4%, імунітет до всіх ефектів, що сповільнюють пересування." },
    { en = "Increased healing received by $w1%$?$w1<100[ and will prevent 1 killing blow][].", ua = "Отримуване зцілення збільшено на $w1%$?$w1<100[, а також відвертає 1 смертельний удар][]." },
    { en = "You have a Demonic Circle active, allowing you to cast Demonic Circle: Teleport to teleport to its location.", ua = "У тебе активне «Демонічне коло», що дозволяє створити «Демонічне коло: Телепортація» й телепортуватися до нього." },
    { en = "$s2 Physical damage every $t2 sec.", ua = "$s2 фізичної шкоди кожні $t2 с." },
    { en = "Taking $s2% increased damage from the Warlock. $?e4[Suffering ${$1262710s1*($48181d/$48181t5)} Shadow damage.][] Haunt's cooldown will be reset on death.", ua = "Отримує на $s2% більше шкоди від чорнокнижника. $?e4[Зазнає ${$1262710s1*($48181d/$48181t5)} тіньової шкоди.][] У разі смерті перезарядження «Наслання» скидається." },
    { en = "Your movement speed is increased by $w1%, you cannot be slowed below $s2% of normal speed, and you are immune to forced movement effects and knockbacks.", ua = "Твою швидкість пересування збільшено на $w1%, тебе не можна сповільнити нижче $s2% звичайної швидкості, і ти несприйнятливий до ефектів примусового переміщення та відкидання." },
    { en = "Nature spells deal $w1% additional damage$?<$w4>0>[, Wrath Astral Power generation increased $w4%,][] and Wrath's damage is increased by $w3%.", ua = "Закляття природи завдають на $w1% більше шкоди$?<$w4>0>[, «Гнів» генерує на $w4% більше Астральної сили,][], а шкода «Гніву» збільшена на $w3%." },
    { en = "Arcane spells deal $w1% additional damage$?<$w4>0>[, Starfire Astral Power generation increased by $w4%,][] and Starfire's damage is increased by $w3%.", ua = "Арканні закляття завдають на $w1% більше шкоди$?<$w4>0>[, генерація Астральної сили від «Зоряного вогню» збільшена на $w4%,][] а шкода «Зоряного вогню» збільшена на $w3%." },
    { en = "Absorbing up to $w1 magic damage.\nImmune to harmful magic effects.", ua = "Поглинає до $w1 магічної шкоди.\nІмунітет до шкідливих магічних ефектів." },
    { en = "The next $w2 healing received will be absorbed. $?$W4>0[Healing received increased by $w4%.][]", ua = "Наступні $w2 отриманого зцілення буде поглинуто. $?$W4>0[Отримуване зцілення збільшено на $w4%.][]" },
    { en = "Damage taken reduced by $w3%.\nImmune to Stun effects.", ua = "Отримувана шкода зменшена на $w3%.\nІмунітет до ефектів приголомшення." },
    { en = "Leech increased by $s1%$?a389682[, damage taken reduced by $s8%][] and immune to Charm, Fear and Sleep. Undead.", ua = "Висмоктування збільшене на $s1%$?a389682[, отримувана шкода зменшена на $s8%][], несприйнятливість до зачарування, страху та сну. Нежить." },
    { en = "Inflicts $s1 Fire damage every $t1 sec.", ua = "Завдає $s1 вогняної шкоди кожні $t1 сек." },
    { en = "Increases Fire damage taken by $s2%.", ua = "Збільшує отримувану шкоду від вогню на $s2%." },
    { en = "$s1 Nature damage every $t1 sec.", ua = "$s1 шкоди від сил природи кожні $t1 с." },
    { en = "Increases armor by $s1 for $d.", ua = "Підвищує броню на $s1 на $d." },
