    { en = "Healed whenever the Paladin heals a nearby ally.$?e3[\n\nDamage taken reduced by $w4%.][]$?e4[\n\nHealed for $w5 every $t5 sec.][]", ua = "Зцілюєшся щоразу, коли паладин зцілює союзника поблизу.$?e3[\n\nОтримувана шкода зменшена на $w4%.][]$?e4[\n\nЗцілює $w5 здоров'я кожні $t5 с.][]" },
    { en = "The paladin's healing spells cast on you also heal the Beacon of Light.", ua = "Зцілювальні закляття паладина, створені на тобі, також зцілюють ціль «Маяка Світла»." },
    { en = "Something is with you....", ua = "Щось є поруч із тобою...." },
    { en = "Throw one of the many weapons in the Monster Slayer's Kit at the target.", ua = "Кидає в ціль одну з багатьох зброй із Набору вбивці монстрів." },
    { en = "Summons an Argent Knight to your side.", ua = "Прикликає до вас Срібного Лицаря." },
