    { en = "Cannot be stunned or interrupted.", ua = "Не можна приголомшити чи перервати." },
    { en = "Deals $61886s1 Nature damage per second to nearby enemies.\nCannot be stunned or interrupted.", ua = "Завдає $61886s1 природної шкоди щосекунди ворогам поблизу.\nНеможливо приголомшити чи перервати." },
    { en = "Damage increased by $s1%.\nGrants new abilities.", ua = "Шкода збільшена на $s1%.\nНадає нові здібності." },
    { en = "Trapped in a block of ice.", ua = "Ув'язнено в брилі льоду." },
    { en = "Absorbs $s1 damage.\nIncreases damage done by $62277s1% when broken by damage.", ua = "Поглинає $s1 шкоди.\nЯкщо зруйновано шкодою, збільшує завдавану шкоду на $62277s1%." },
    { en = "Melee damage and attack speed increased by $s1%.\nNature damage increased by $s3%.", ua = "Шкода ближнього бою та швидкість атаки збільшені на $s1%.\nШкода від сил природи збільшена на $s3%." },
    { en = "Inflicts $s2 Nature damage every $t2 sec.\nImmobilized.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с.\nЗнерухомлено." },
    { en = "$s2 healing every $t2 sec.", ua = "Зцілює $s2 здоров'я кожні $t2 с." },
    { en = "Healing for $s1 every $t1 sec.", ua = "Зцілює на $s1 кожні $t1 с." },
    { en = "Haste increased by $s3%.\nDeals $62530s1 Fire damage to nearby enemies every $t2 sec.", ua = "Поспіх збільшено на $s3%.\nЗавдає $62530s1 вогняної шкоди ворогам поблизу кожні $t2 с." },
    { en = "Damage taken increased by $s3%.", ua = "Отримувана шкода збільшена на $s3%." },
    { en = "Inflicts Nature damage.", ua = "Завдає шкоди від сил природи." },
    { en = "Stunned.\nChance to receive critical hits increased by $s2%.\nShatters if dealt $w3 damage or more in a single attack.", ua = "Приголомшено.\nШанс отримати критичний удар збільшений на $s2%.\nРозбивається, якщо одна атака завдасть $w3 шкоди чи більше." },
    { en = "Deals $s1 Fire damage every sec.", ua = "Завдає $s1 вогняної шкоди щосекунди." },
    { en = "Stunned. \nDamage taken increased by $s1%.", ua = "Приголомшено. \nОтримувана шкода збільшена на $s1%." },
    { en = "Physical damage reduced by $s3%, but attacks deal $62867s1 additional Frost damage and all enemies suffer $64544s1 Frost damage every $t2 sec.", ua = "Фізична шкода зменшена на $s3%, але атаки завдають додатково $62867s1 морозної шкоди, а всі вороги зазнають $64544s1 морозної шкоди кожні $t2 с." },
    { en = "Increases healing received by $s1%.", ua = "Збільшує отримуване зцілення на $s1%." },
    { en = "Silenced.\nPacified.", ua = "Змушено замовкнути.\nУтихомирено." },
    { en = "You may now safely kiss Lake Frogs without fear of getting warts.", ua = "Тепер ти можеш безпечно цілувати Озерних Жаб, не боячись підхопити бородавки." },
    { en = "Eonar's Gift heals Freya and all of her minions for $s2% of their health.", ua = "«Дар Еонар» зцілює Фрею та всіх її поплічників на $s2% їхнього здоров'я." },
    { en = "Physical damage increased by $s2%.\nMovement speed reduced by $s1%.", ua = "Фізична шкода збільшена на $s2%.\nШвидкість пересування знижена на $s1%." },
    { en = "Summons allies of Freya to assist in the battle to protect Ulduar.", ua = "Прикликає союзників Фреї на поміч у битві за захист Ульдуара." },
    { en = "Deals $s2 Fire damage per second.", ua = "Завдає $s2 шкоди вогнем щосекунди." },
    { en = "Unable to regenerate or gain mana from most natural sources.\nMelee attack speed reduced by $s2%.", ua = "Не може відновлювати чи отримувати ману з більшості природних джерел.\nШвидкість атаки ближнього бою знижена на $s2%." },
    { en = "Increases Physical damage dealt by $s1%.", ua = "Збільшує завдавану фізичну шкоду на $s1%." },
    { en = "Dealing damage to nearby enemies.", ua = "Завдає шкоди ворогам поблизу." },
    { en = "Deals $63009s1 Fire damage to all enemies within $63009A1 yards.", ua = "Завдає $63009s1 вогняної шкоди всім ворогам у радіусі $63009A1 м." },
    { en = "Damage taken every $t2 sec.\nDealing damage to nearby allies.", ua = "Шкода кожні $t2 с.\nЗавдає шкоди союзникам поблизу." },
    { en = "Will explode, causing damage to nearby allies, pulling them to you after $t1 sec.", ua = "Через $t1 с вибухне, завдавши шкоди союзникам поблизу й притягнувши їх до тебе." },
    { en = "$s1% Sane. If all Sanity is lost Yogg-Saron will control your mind.", ua = "Глузд: $s1%. Якщо втратиш увесь глузд, Йоґґ-Сарон заволодіє твоїм розумом." },
    { en = "Suffering $w1 Shadow damage every $t1 sec and siphoning life to the casting Warlock.", ua = "Зазнає $w1 тіньової шкоди кожні $t1 с, а життя перетікає до чорнокнижника-заклинача." },
    { en = "Inflicts $s3 Nature damage every $t3 sec.", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с." },
    { en = "Siphoning $s1 health from nearby allies every $t1 sec., healing General Vezax.", ua = "Висмоктує $s1 здоров'я з союзників поблизу кожні $t1 с, зцілюючи Генерала Везакса." },
