    { en = "Surrounded with swirling essences of Bane.", ua = "Оточено вируючими есенціями «Згуби»." },
    { en = "Range increased by $w1%.\nFocus spending abilites deal $s2% increased damage.", ua = "Дальність збільшена на $w1%.\nЗдібності, що витрачають Зосередження, завдають на $s2% більше шкоди." },
    { en = "$?$w3=0[Taking][Movement speed slowed by $w3% and taking] $s1 Shadow damage every $t1 sec.", ua = "$?$w3=0[Отримуєш][Швидкість пересування знижена на $w3%, отримуєш] $s1 шкоди від тіні кожні $t1 с." },
