    { en = "Encased in a thin layer of brittle ice. Damage taken increased by 300%.", ua = "Вкрито тонким шаром крихкої криги. Отримувана шкода збільшена на 300%." },
    { en = "Dealing $202891s1 Nature damage to nearby enemies every $202889t1 sec.", ua = "Завдає $202891s1 природної шкоди ворогам поблизу кожні $202889t1 с." },
    { en = "Inflicts $203057s1 Shadow damage every $t1 seconds.", ua = "Завдає $203057s1 шкоди від тіні кожні $t1 с." },
