    { en = "Immune to magical damage and harmful effects.", ua = "Несприйнятливість до магічної шкоди та шкідливих ефектів." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nMovement speed reduced by $s2%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Mastery increased by ${$w2*$mas}%.", ua = "Майстерність збільшена на ${$w2*$mas}%." },
    { en = "Suffering $211659s1 Arcane damage every second while in range of an Arcane Tether.", ua = "Зазнає $211659s1 арканної шкоди щосекунди, перебуваючи в межах досяжності «Арканної Прив'язі»." },
    { en = "Sigil of Flame is active.", ua = "«Сигіл полум'я» активний." },
