    { en = "Arcane Blast is instant cast.", ua = "«Арканний вибух» твориться миттєво." },
    { en = "Dealing $s1 Shadow damage to the target every $t sec.\n\nInsanity drain temporarily stopped.", ua = "Завдає $s1 тіньової шкоди цілі кожні $t с.\n\nВитік божевілля тимчасово зупинено." },
    { en = "Dealing damage to all nearby targets every $t1 sec and healing the casting Warlock.", ua = "Завдає шкоди всім цілям поблизу кожні $t1 с і зцілює чорнокнижника, що її створив." },
    { en = "Summons a Darkglare from the Twisting Nether that blasts its target for Shadow damage, dealing increased damage for every damage over time effect you have active on their current target.", ua = "Прикликає з Викривленого Нижнього Світу темнозора, що вражає свою ціль тіньовою шкодою, завдаючи більше шкоди за кожен твій активний ефект поступової шкоди на його поточній цілі." },
    { en = "Movement speed reduced by $s2%.\n$?$w3!=0[Suffering $s3 Radiant damage every $t3 sec.][]", ua = "Швидкість пересування знижена на $s2%.\n$?$w3!=0[Зазнає $s3 променистої шкоди кожні $t3 с.][]" },
    { en = "Under the control of $@auracaster.", ua = "Під контролем: $@auracaster." },
    { en = "$w1 |4Icicle:Icicles; stored. Upon reaching 5 Icicles, your $?s431044[Frostfire Bolt][Frostbolt] is replaced with Glacial Spike.", ua = "Збережено бурульок: $w1. Коли їх стане 5, твоя $?s431044[«Морозовогняна стріла»][«Крижана стріла»] замінюється на «Льодовиковий Шпиль»." },
    { en = "Your next Lightning Bolt or Chain Lightning will be instant and deal $w1% additional damage.", ua = "Твоя наступна «Блискавка» або «Ланцюгова блискавка» буде миттєвою й завдасть на $w1% більше шкоди." },
    { en = "Healing $m1% health every $T1 sec.", ua = "Зцілює $m1% здоров'я кожні $T1 с." },
    { en = "Suffering $o3 Fire damage over $d.", ua = "Зазнає $o3 вогняної шкоди протягом $d." },
    { en = "$s2 Fire damage inflicted every $t2 sec.\nCreates a pool of Felflame every $t2 sec.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с.\nСтворює калюжу Сквернополум'я кожні $t2 с." },
    { en = "Lustrous.", ua = "Блискучий." },
    { en = "You are merely a dream of yourself. \nCorruption and damage you have taken will be removed when you wake.", ua = "Ти лише сон про самого себе. \nЗіпсуття й шкода, яких ти зазнав, зникнуть, коли ти прокинешся." },
    { en = "Health increased by $w1%.\nDamage increased by $w2%.$?$w3!=0[\nEnrages when injured.][]$?$w4!=0[\nBolsters nearby allies upon death.][]$?$w5!=0[\nEspecially dangerous boss enemy.][]$?$w8!=0[\nCauses flames to erupt beneath distant foes.][]$?$w9!=0[\nSuccessful melee attacks inflict necrotic rot.][]$?$w10!=0[\nFortified non-boss enemy with additional health and damage.][]$?$w11!=0[\nLeaves behind a pool of ichor upon death.][]$?$w13!=0[\nSummons an Explosive Orb that will detonate if not destroyed.][]$?$w14!=0[\nBursts violently upon death.][]\n$?$w15!=0[\nWill seek vengeance from beyond the grave.][]$?$w17!=0[\nSummons malevolent fiends upon death.][]$?$w18!=0[\nCausing storms to appear nearby.][]", ua = "Здоров'я збільшено на $w1%.\nШкоду збільшено на $w2%.$?$w3!=0[\nЛютує, коли поранений.][]$?$w4!=0[\nПісля смерті підсилює союзників поблизу.][]$?$w5!=0[\nОсобливо небезпечний ворог-бос.][]$?$w8!=0[\nЗмушує полум'я вириватися з-під ніг віддалених ворогів.][]$?$w9!=0[\nУспішні атаки ближнього бою накладають некротичну гниль.][]$?$w10!=0[\nПідсилений ворог (не бос) з додатковим здоров'ям і шкодою.][]$?$w11!=0[\nПісля смерті лишає калюжу іхору.][]$?$w13!=0[\nПрикликає Вибухову сферу, що детонує, якщо її не знищити.][]$?$w14!=0[\nПісля смерті бурхливо вибухає.][]\n$?$w15!=0[\nШукатиме помсти з того світу.][]$?$w17!=0[\nПісля смерті прикликає злісну нечисть.][]$?$w18!=0[\nСпричиняє появу бур поблизу.][]" },
    { en = "Explodes for $206340s1 Fire damage when broken.\nSuffering increasing Fire damage every half-second.\nMovement speed decreased by $209011s2%.", ua = "Під час розриву вибухає, завдаючи $206340s1 вогняної шкоди.\nДедалі більша вогняна шкода кожні пів секунди.\nШвидкість пересування знижена на $209011s2%." },
    { en = "Trapped within an illusion.", ua = "Ув'язнено в ілюзії." },
    { en = "Physical damage done increased by $s1%.\nSize increased.", ua = "Завдана фізична шкода збільшена на $s1%.\nРозмір збільшений." },
    { en = "All damage and healing increased by $s1%.\nMana regeneration increased by $s3%.", ua = "Уся шкода та зцілення збільшені на $s1%.\nВідновлення мани збільшене на $s3%." },
    { en = "Inflicts $s2 Shadow damage every second.\n\nTargeted by Seeker Swarm.", ua = "Завдає $s2 шкоди від тіні щосекунди.\n\nЦіль «Рою шукачів»." },
    { en = "Incoming damage creates arcane pools.", ua = "Отримувана шкода створює арканні калюжі." },
    { en = "Inflicts $s2 Frost damage every $t2 sec.\nStand near 3 other players to remove this effect.", ua = "Завдає $s2 шкоди від морозу кожні $t2 с.\nСтань поруч із 3 іншими гравцями, щоб зняти цей ефект." },
    { en = "Standing near players with Absolute Zero will cause Frozen Solid.", ua = "Перебування поруч із гравцями під дією «Абсолютного нуля» спричинить «Скуто кригою»." },
    { en = "$w1 Arcane damage per $t1 sec.", ua = "$w1 арканної шкоди кожні $t1 с." },
    { en = "Absorbs $w1 healing.\nOn expiration, deals $w1 Arcane damage to all players.", ua = "Поглинає $w1 зцілення.\nПісля завершення завдає $w1 арканної шкоди всім гравцям." },
    { en = "Increases all incoming damage by $s2%.", ua = "Збільшує всю отримувану шкоду на $s2%." },
    { en = "$206749s1 Arcane damage inflicted to random enemies every $t1 sec.", ua = "Завдає $206749s1 арканної шкоди випадковим ворогам кожні $t1 с." },
    { en = "$s1 Shadow damaged inflicted every $t1 sec.\nDispelling inflicts $207859s1 Shadow damage to all enemies in a $207859A1 yd radius.\nThe dispeller suffers Shadow damage and gains 25 Corruption.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nРозвіювання завдає $207859s1 шкоди від тіні всім ворогам у радіусі $207859A1 м.\nТой, хто розвіює, зазнає шкоди від тіні й отримує 25 Псування." },
    { en = "Movement speed slowed by $w1%.", ua = "Швидкість пересування сповільнена на $w1%." },
