    { en = "|cFF00AA99Bonus Event: World Quests|r\n\nReputation gains from World Quests increased by $s1%.", ua = "|cFF00AA99Бонусна подія: Світові завдання|r\n\nПриріст репутації від світових завдань збільшено на $s1%." },
    { en = "Mounted movement speed in the Broken Isles increased by $s1%.", ua = "Швидкість пересування верхи на Розбитих Островах збільшена на $s1%." },
    { en = "Eternal Darkness damage increased by $s2%.", ua = "Шкода «Вічної темряви» збільшена на $s2%." },
    { en = "Taking 100% increased damage.\nRegenerating mana.", ua = "Отримувана шкода збільшена на 100%.\nВідновлює ману." },
