    { en = "Inflicting Arcane damage.\nProtected from all damage.", ua = "Завдає арканної шкоди.\nЗахищено від будь-якої шкоди." },
    { en = "$227415s1 Shadow damage every 2 sec.\nCleanse the player with the specter to cancel this effect.\nCleansing a player without the specter will result in $227419s1 Shadow damage to all players instead.", ua = "$227415s1 шкоди від тіні кожні 2 с.\nОчисть гравця з привидом, щоб скасувати цей ефект.\nОчищення гравця без привида натомість завдасть $227419s1 шкоди від тіні всім гравцям." },
    { en = "Reduces falling damage.", ua = "Зменшує шкоду від падіння." },
    { en = "Suffering $s1 Arcane damage every $T sec.", ua = "Зазнає $s1 арканної шкоди кожні $T с." },
    { en = "Maximum health reduced to 50% of normal.", ua = "Максимальне здоров'я зменшене до 50% звичайного." },
    { en = "$s4 Arcane damage inflicted every $t4 sec.\nAll damage dealt is increased by $s2%.", ua = "Завдає $s4 арканної шкоди кожні $t4 с.\nУся завдана шкода збільшена на $s2%." },
    { en = "All attacks made by Guarm also strike the next closest target.", ua = "Усі атаки Гуарма також вражають наступну найближчу ціль." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nConsumes a stack of $@spellname227502 every $t1 sec, otherwise it drains $227528s1% of  mana every $t1 sec.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПоглинає один заряд $@spellname227502 кожні $t1 с, а якщо його немає — висмоктує $227528s1% мани кожні $t1 с." },
    { en = "Deadly when combined with Dark Discharge or Salty Spittle.", ua = "Смертельно в поєднанні з «Темним Розрядом» або «Солоною Слиною»." },
    { en = "$s1% mana drained every $t1 sec.\n$s2 Arcane damage inflicted every $t2 sec.\nStunned.", ua = "Висмоктує $s1% мани кожні $t1 с.\nЗавдає $s2 арканної шкоди кожні $t2 с.\nПриголомшено." },
    { en = "Deadly when combined with Dark Discharge or Fiery Phlegm.", ua = "Смертельно в поєднанні з «Темним Розрядом» або «Вогняним Слизом»." },
    { en = "Deadly when combined with Salty Spittle or Fiery Phlegm.", ua = "Смертельно в поєднанні з «Солоною Слиною» або «Вогняним Слизом»." },
    { en = "Healing $s1% every $t1sec.", ua = "Зцілює $s1% здоров'я кожні $t1 с." },
    { en = "Tracking Ancient Mana.", ua = "Вистежування прадавньої мани." },
    { en = "Upon expiration, inflicts $s1 Nature damage to all players within $A1 yds.", ua = "Після завершення завдає $s1 шкоди від сил природи всім гравцям у межах $A1 м." },
    { en = "Absorbs $w1 damage.\nImmune to interrupts.", ua = "Поглинає $w1 шкоди.\nНесприйнятливий до переривань." },
    { en = "$s1 Holy damage inflicted every $t1 sec.", ua = "Завдає $s1 священної шкоди кожні $t1 с." },
    { en = "Immune to stuns and bonds.", ua = "Несприйнятливість до приголомшення та пут." },
    { en = "Inflicts $227808s1 Nature damage upon expiring.", ua = "Після завершення дії завдає $227808s1 шкоди від сил природи." },
    { en = "Armor reduced by $227982s1%.", ua = "Броня знижена на $227982s1%." },
    { en = "Movement speed reduced by $s1%.\nCan move through a $@spellname228200 to extinguish the flames.", ua = "Швидкість пересування знижена на $s1%.\nМожна пройти крізь $@spellname228200, щоб загасити полум'я." },
    { en = "Suffering $228055s1 Frost damage every half-second.", ua = "Зазнає $228055s1 морозної шкоди кожні пів секунди." },
    { en = "Explodes for $228053s1 Frost damage to all players when removed.\nSuffering $s1 Frost damage every second.", ua = "Під час зняття вибухає, завдаючи $228053s1 морозної шкоди всім гравцям.\n$s1 морозної шкоди щосекунди." },
    { en = "Pulsing Frost damage at several locations every second.", ua = "Щосекунди пульсує морозною шкодою в кількох місцях." },
    { en = "$228127s1 Nature damage every $228127T1 sec.", ua = "$228127s1 шкоди від сил природи кожні $228127T1 с." },
    { en = "Blinded by dust!", ua = "Засліплено пилом!" },
    { en = "Movement speed increased by $s1%... hot!", ua = "Швидкість пересування збільшена на $s1%... гаряче!" },
    { en = "Increases your haste by $s1%.", ua = "Збільшує твій поспіх на $s1%." },
    { en = "Damage taken increased by $228519s3%.", ua = "Отримувана шкода збільшена на $228519s3%." },
    { en = "Damage taken from Shimmer increased by $s2%.", ua = "Шкода від «Мерехтіння» збільшена на $s2%." },
    { en = "Increases Lantern of Darkness damage by $228621s2%.", ua = "Збільшує шкоду «Ліхтаря темряви» на $228621s2%." },
    { en = "Inflicting $s1 Holy damage every $t1 sec.", ua = "Завдає $s1 священної шкоди кожні $t1 с." },
    { en = "Ravager is currently active.", ua = "«Спустошувач» зараз активний." },
    { en = "Inflicts $s1 Fire damage to all enemies in front of the caster, knocking the target back.", ua = "Завдає $s1 шкоди вогнем усім ворогам перед заклинателем, відкидаючи ціль назад." },
    { en = "Summons Chaotic Shadows around the target when the aura is removed.\nInflicts $s1 Shadow damage every $t1 sec.", ua = "Коли аура знімається, прикликає навколо цілі «Хаотичні Тіні».\nЗавдає $s1 тіньової шкоди кожні $t1 с." },
    { en = "Inflicts $s1 Shadow damage to enemies within $A1 yards of the triggered Chaotic Shadows orb.", ua = "Завдає $s1 шкоди від тіні ворогам у межах $A1 м від спрацьованої кулі Хаотичних тіней." },
    { en = "Viz'aduum the Watcher opens a Demonic Portal to reatreat to a Legion Command Ship!", ua = "Віз'адуум Спостерігач відкриває Демонічний портал, щоб відступити на Командний корабель Легіону!" },
    { en = "The Legion Soul Harvester inflicts $229905s1 Fire damage every 1 sec to enemies within 15 yards of it.", ua = "Збирач душ Легіону завдає $229905s1 шкоди вогнем щосекунди ворогам у межах 15 м від себе." },
    { en = "Inflicts $s2 Fire damage every $t2 sec.\nReduces movement speed by $s3%.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с.\nЗнижує швидкість пересування на $s3%." },
    { en = "Bleeding for $s1 Physical damage every $t1 sec.", ua = "Кровотеча завдає $s1 фізичної шкоди кожні $t1 с." },
    { en = "Healing an injured ally within $r yds for $230017s1 health every $t1 sec.", ua = "Зцілює пораненого союзника в межах $r м на $230017s1 здоров'я кожні $t1 с." },
    { en = "Haste increased by $s2%.\nMovement speed increased by $s1%.", ua = "Поспіх збільшено на $s2%.\nШвидкість пересування збільшено на $s1%." },
    { en = "Fires Shadowy Phlegm at the target which inflicts $230067s1 Shadow damage to enemies within $230067A1 yards of the target.", ua = "Випускає в ціль Тіньовий слиз, що завдає $230067s1 шкоди від тіні ворогам у межах $230067A1 м від цілі." },
    { en = "Upon reaching the Command Ship Viz'aduum the Watcher will attempt to stabilize the Rift that is connected to distant Legion worlds! If he succeeds the Legion forces will pour through the portal!", ua = "Діставшись Командного корабля, Віз'адуум Спостерігач спробує стабілізувати Розлом, що веде до далеких світів Легіону! Якщо йому це вдасться, сили Легіону ринуть крізь портал!" },
    { en = "$s3% of damage you take is prevented and transferred to the caster of this effect. Prevents $w1 damage.", ua = "$s3% шкоди, якої ти зазнаєш, відвертається й передається заклиначу цього ефекту. Відвертає $w1 шкоди." },
    { en = "Physical damage taken is additionally shared to all other players.\n$s3 Shadow damage inflicted every $t3 sec.", ua = "Отримувана фізична шкода додатково розподіляється між усіма іншими гравцями.\nЗавдає $s3 тіньової шкоди кожні $t3 с." },
    { en = "Upon expiration, inflicts $230224s1 Nature damage to you and may stun for $230228d.", ua = "Після завершення завдає тобі $230224s1 шкоди від сил природи й може приголомшити на $230228d." },
    { en = "Chance to deal or take a Critical Strike increased by $s1%.", ua = "Шанс завдати або отримати критичний удар збільшений на $s1%." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nChance to hit reduced by $s2%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nШанс влучити знижено на $s2%." },
    { en = "$s2 Fire damage inflicted every $t2 sec.\nTriggers $@spellname231395, upon expiration.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с.\nПісля завершення спричиняє $@spellname231395." },
    { en = "Inflicting $s1 Frost damage every $t1 sec.\nIncreasing stacks of $@spellname231770.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\nЗбільшує кількість зарядів $@spellname231770." },
    { en = "Inflicting $241511s1 Frost damage every $t2 sec.\n\nFrost damage taken is increased by $s1%.", ua = "Завдає $241511s1 морозної шкоди кожні $t2 с.\n\nОтримувана морозна шкода збільшена на $s1%." },
    { en = "Damage, Healing and critical strike chance increased by $w1%.  \n\nHaste increased by $w3%.", ua = "Шкода, зцілення та шанс критичного удару збільшені на $w1%.  \n\nПоспіх збільшений на $w3%." },
    { en = "Increasing Agility by $231965s1 ever $t1 sec.", ua = "Збільшує Спритність на $231965s1 кожні $t1 с." },
    { en = "Drawing in all pools of $@spellname231768.", ua = "Притягує всі калюжі «$@spellname231768»." },
    { en = "Absorbs $232450w2 healing.", ua = "Поглинає $232450w2 зцілення." },
    { en = "Decreases all healing received by $232488s1%.", ua = "Зменшує все отримуване зцілення на $232488s1%." },
    { en = "Spell damage dealt increased by $s1%.", ua = "Завдана шкода від заклять збільшена на $s1%." },
    { en = "Inflicts Fire damage to an enemy.", ua = "Завдає ворогові шкоди від вогню." },
    { en = "$s1 healing absorbed\nInflicts $s1 Shadow damage upon expiration.", ua = "Поглинає $s1 зцілення\nПісля завершення завдає $s1 шкоди від тіні." },
    { en = "All damage done reduced by $s1%.\nChance to hit reduced by $s2%.\nHealing done reduced by $s3%.\nAll damage taken increased by $s4%.", ua = "Уся завдавана шкода знижена на $s1%.\nШанс влучити знижений на $s2%.\nЗавдаване зцілення знижене на $s3%.\nУся отримувана шкода збільшена на $s4%." },
    { en = "Inflicting $233444s1 Physical damage and $233444s2 Torment to nearby enemies, and $233444s3 Physical damage to all enemies, every $t1 sec.\n\nMovement speed slowed by $s2%.\nAttacking Atrigan causes the attacker to gain Torment.", ua = "Завдає $233444s1 фізичної шкоди та $233444s2 «Муки» ворогам поблизу, а також $233444s3 фізичної шкоди всім ворогам кожні $t1 с.\n\nШвидкість пересування знижена на $s2%.\nАтака на Атригана дає нападникові «Муку»." },
    { en = "$s2 Fire damage inflicted every second.\nConfused.", ua = "Завдає $s2 шкоди вогнем щосекунди.\nДезорієнтовано." },
    { en = "Increases the damage and attack speed of nearby dinner guests.", ua = "Підвищує шкоду та швидкість атаки гостей вечері поблизу." },
    { en = "$s1 Shadow damage inflicted every $T1 sec.", ua = "Завдає $s1 шкоди від тіні кожні $T1 с." },
    { en = "Inflicting $s2 Shadow damage and $s3 Torment every $t2 sec.  Casts Anguished Outburst when this effect is removed.", ua = "Завдає $s2 шкоди від тіні та $s3 од. Муки кожні $t2 с.  Творить «Страдницький Спалах», коли цей ефект знято." },
    { en = "Inflicts $240213s1 Chaos damage every $t1 sec.\nChaotic energy explodes at your location every $t1 sec.", ua = "Завдає $240213s1 шкоди від хаосу кожні $t1 с.\nХаотична енергія вибухає там, де ти стоїш, кожні $t1 с." },
    { en = "Suffering $s1 Shadow damage every $t1 seconds.\nRestoring health to the Warlock.", ua = "Зазнає $s1 тіньової шкоди кожні $t1 с.\nВідновлює здоров'я чорнокнижнику." },
    { en = "Stunned.\nFrost damage inflicted every $T2 sec.", ua = "Приголомшено.\nЗавдає морозної шкоди кожні $T2 с." },
    { en = "$s1 Shadow inflicted every $t1 sec.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с." },
    { en = "Arcane Damage taken increased  by $s1%.", ua = "Отримувана арканна шкода збільшена на $s1%." },
    { en = "Shadow Damage taken increased  by $s1%.", ua = "Отримувана тіньова шкода збільшена на $s1%." },
    { en = "$235125s1  Fire damage inflicted every $T1.\n\nExplodes after $D, inflicting $235138s1 Fire damage to all allies and knocking back allies within $235133A1 yds. Damage to allies can be prevented by Aegwynn's Ward.", ua = "Завдає $235125s1  шкоди вогнем кожні $T1.\n\nЧерез $D вибухає, завдаючи $235138s1 шкоди вогнем усім союзникам і відкидаючи союзників у радіусі $235133A1 м. Шкоді союзникам можна запобігти за допомогою «Оберегу Еґвінн»." },
    { en = "Inflicting $233444s1 Fire damage and $233444s2 Torment to nearby enemies, and $233444s3 Fire damage to all enemies, every $t2 sec.\nAttacking Belac causes the attacker to gain Torment.", ua = "Завдає $233444s1 вогняної шкоди та $233444s2 «Муки» ворогам поблизу, а також $233444s3 вогняної шкоди всім ворогам кожні $t2 с.\nАтака на Белака дає нападникові «Муку»." },
    { en = "Absorbs $w1 damage.\nMelee attackers take $235314s1 Fire damage.$?a321708[\nHeals you for $321708s1% of the damage absorbed.][]", ua = "Поглинає $w1 шкоди.\nНападники ближнього бою отримують $235314s1 шкоди вогнем.$?a321708[\nЗцілює тебе на $321708s1% поглинутої шкоди.][]" },
    { en = "Absorbs $w1 damage.\nMagic damage taken reduced by $s3%.\nDuration of all harmful Magic effects reduced by $w4%.", ua = "Поглинає $w1 шкоди.\nОтримувана магічна шкода знижена на $s3%.\nТривалість усіх шкідливих магічних ефектів скорочена на $w4%." },
    { en = "Damage done increased by $w1%.\nHealing increased by $w2%.", ua = "Завдавана шкода збільшена на $w1%.\nЗцілення збільшено на $w2%." },
    { en = "Healing done increased by $s2%.\nOverhealing is redistributed to nearby injured allies.", ua = "Здійснюване зцілення збільшено на $s2%.\nНадлишкове зцілення перерозподіляється між пораненими союзниками поблизу." },
    { en = "$236464s1 Shadow damage inflicted to all players within $236464A1 yds every $236464s2 sec.\n\nRemoved upon being within $236465A2 yds of another bound player in an opposing realm.", ua = "Завдає $236464s1 шкоди від тіні всім гравцям у радіусі $236464A1 м кожні $236464s2 с.\n\nЗнімається, коли ти опиняєшся в радіусі $236465A2 м від іншого зв'язаного гравця в протилежному світі." },
    { en = "Damage taken from Desolate increased by $s2%.", ua = "Шкода від «Спустошення» збільшена на $s2%." },
    { en = "Damage taken reduced by $s1%.\n\nBeing struck with $@spellname236515 removes this effect.", ua = "Отримувана шкода зменшена на $s1%.\n\nВлучання «$@spellname236515» знімає цей ефект." },
    { en = "Movement speed reduced by $s2%.\n\nUpon reaching 5 stacks, $@spellname236515 explodes for $236772s3 Shadow damage and removes $@spellname236513 from all targets within $236772A1 yds.", ua = "Швидкість пересування знижена на $s2%.\n\nЗа 5 зарядів $@spellname236515 вибухає, завдаючи $236772s3 тіньової шкоди та знімаючи $@spellname236513 з усіх цілей у радіусі $236772A1 м." },
    { en = "$s1 Arcane damage inflicted every $t1 sec.\nTriggering $@spellname234998 will remove Moon Burn.", ua = "Завдає $s1 арканної шкоди кожні $t1 с.\nСпрацювання $@spellname234998 зніме «Місячний опік»." },
    { en = "Inflicts $w1 Nature damage every $t sec.", ua = "Завдає $w1 шкоди від сил природи кожні $t с." },
    { en = "Deathly Screech damage increased by $s2%.", ua = "Шкода «Смертоносного вереску» збільшена на $s2%." },
    { en = "$?j1g[Increases ground speed by $j1g%. \n][]$?j1f[Increases flight speed by $j1f%. ][]$?j1s[Increases swim speed by $j1s%. ][]", ua = "$?j1g[Збільшує швидкість руху по землі на $j1g%. \n][]$?j1f[Збільшує швидкість польоту на $j1f%. ][]$?j1s[Збільшує швидкість плавання на $j1s%. ][]" },
    { en = "Movement Speed reduced by $s1%.", ua = "Швидкість пересування знижена на $s1%." },
    { en = "Mana costs increased by $s1%.", ua = "Витрати мани збільшені на $s1%." },
