    { en = "Raptor Strike damage increased by $s1%.$?a385737[\n\nStrike as One damage increased by $s2%.][]$?a1296636[\n\nWildfire Bomb damage increased by $1296636s1%.][]", ua = "Шкода «Удару раптора» збільшена на $s1%.$?a385737[\n\nШкода «Удару в унісон» збільшена на $s2%.][]$?a1296636[\n\nШкода «Бомби дикого вогню» збільшена на $1296636s1%.][]" },
    { en = "Targeted by $@spellname259940.", ua = "Обрано ціллю: $@spellname259940." },
    { en = "Absorbs $w1 damage.\nUnable to be interrupted.", ua = "Поглинає $w1 шкоди.\nНе можна перервати." },
    { en = "Stunned.\n$s3 Physical damage inflicted every $t3 sec.", ua = "Приголомшено.\nЗавдає $s3 фізичної шкоди кожні $t3 с." },
    { en = "Raining arrows down in the target area.", ua = "Обрушує дощ стріл на обрану ділянку." },
    { en = "Bleeding for $M1 Physical damage every $t sec.", ua = "Кровотеча: $M1 фізичної шкоди кожні $t с." },
    { en = "Burning.\nInflicting $260547s1 Fire damage to all enemies every $t3 sec.", ua = "Горить.\nЗавдає $260547s1 шкоди вогнем усім ворогам кожні $t3 с." },
    { en = "Absorbs up to $w1 of all healing received.\nSuffering $s2 Shadow damage every second.", ua = "Поглинає до $w1 усього отримуваного зцілення.\nЩосекунди завдає $s2 шкоди від тіні." },
    { en = "Inflicting $s1 Shadow damage every $t1 sec.\nUpon expiration, the rune explodes, inflicting $260702s1 Shadow damage to all allies within $260702a1 yards.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля завершення дії руна вибухає, завдаючи $260702s1 шкоди від тіні всім союзникам у радіусі $260702a1 м." },
    { en = "Your single-target damaging abilities hit $s1 additional $Ltarget:targets; within 8 yds for $s2% damage.", ua = "Твої одноцільові здібності шкоди вражають додаткові цілі ($s1) у межах 8 м, завдаючи $s2% шкоди." },
    { en = "Inflicting $s2 Physical damage every $t2 sec.\nRemoved if healed above $s3% health.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с.\nЗнімається, якщо зцілити понад $s3% здоров'я." },
    { en = "Increasing the caster's energy by $s1 every $t1 sec.", ua = "Збільшує енергію заклинача на $s1 кожні $t1 с." },
    { en = "Targeted by $@spellname260811!", ua = "Обрано ціллю: $@spellname260811!" },
    { en = "Being pulled towards the enemy. Run away!", ua = "Тебе тягне до ворога. Тікай!" },
    { en = "Being pulled towards the enemy. Run away!\nUnable to use spells or abilities.\nInflicts $s3 Physical damage every $t3 sec.", ua = "Тебе тягне до ворога. Тікай!\nНе можна використовувати закляття чи здібності.\nЗавдає $s3 фізичної шкоди кожні $t3 с." },
    { en = "Inflicting $s1 Nature damage every $t1 sec.\nMovement speed reduced by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Damage done increased by $s1%.\nHaste increased by $s2%.", ua = "Завдавана шкода збільшена на $s1%.\nПоспіх збільшено на $s2%." },
    { en = "Gathered from iron deposits throughout the warfront. Used in the construction of buildings and troops.", ua = "Збирається із залізних покладів по всьому воєнному фронту. Використовується для зведення споруд і формування військ." },
    { en = "Gathered from piles of wood throughout the warfront. Used in the construction of buildings and troops.", ua = "Збирається з куп деревини по всьому воєнному фронту. Використовується для зведення споруд і формування військ." },
    { en = "Gathered from enemy troops and vehicles throughout the warfront. Used in the training of troops and advancing research.", ua = "Збирається з ворожих військ і техніки по всьому воєнному фронту. Використовується для навчання військ та просування досліджень." },
    { en = "Thank you. Your head is warmer than the ground.", ua = "Дякую. Твоя голова тепліша за землю." },
    { en = "Inflicts $s2 Nature damage every $t2 sec.\nMutates into Putrid Paroxysm upon expiring.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с.\nПісля завершення дії мутує в «Гнильний пароксизм»." },
    { en = "$?$w2=0[Luring the Fetid Devourer.][Healing $w2% every $t2 sec.]", ua = "$?$w2=0[Приваблює Смердючого пожирача.][Зцілює $w2% здоров'я кожні $t2 с.]" },
    { en = "Damage taken reduced by 99%.", ua = "Отримувана шкода зменшена на 99%." },
    { en = "Dealing $s1 Shadow damage to the target every $t1 sec.", ua = "Завдає цілі $s1 шкоди від тіні кожні $t1 с." },
    { en = "Attacks reflect $268851s1 Nature damage.", ua = "Нападники отримують у відповідь $268851s1 шкоди від сил природи." },
    { en = "Allies within $263374A1 yards will take $263374s1 Nature damage after $d.", ua = "Союзники в радіусі $263374A1 м через $d отримають $263374s1 шкоди від сил природи." },
    { en = "Being repelled.", ua = "Тебе відштовхує." },
    { en = "Stunned.\n\nInflicts $s1 Physical damage every $t1 sec.", ua = "Приголомшено.\n\nЗавдає $s1 фізичної шкоди кожні $t1 с." },
    { en = "$s1 Frost damage inflicted every $t1 sec.\nBeing pushed away!", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\nТебе відштовхує!" },
    { en = "Eye Beam primary target protection.", ua = "Захист основної цілі «Променя з очей»." },
    { en = "Killing Alliance players grants you $m1 bonus Honor. Killing Alliance Assassins grants $m2 bonus Honor.\n\nAfter $m3 Alliance kills without dying, you will graduate to a Horde Assassin, increasing your damage and healing by $264314m1%.", ua = "Убивство гравців Альянсу дає тобі $m1 бонусної честі. Убивство Вбивць Альянсу дає $m2 бонусної честі.\n\nПісля $m3 убивств бійців Альянсу без власної смерті ти станеш Вбивцею Орди, що збільшить твою шкоду та зцілення на $264314m1%." },
    { en = "Rooted.\n$s2 Shadowfrost damage inflicted every $t2 sec.", ua = "Знерухомлено.\nЗавдає $s2 тіньоморозної шкоди кожні $t2 с." },
    { en = "$s1 Frost damage inflicted every $t1 sec.\nMovement speed reduced by $s2%.\n\nUpon being dispelled, Choking Brine travels towards another player.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\nШвидкість пересування знижена на $s2%.\n\nПісля розвіювання «Задушливий розсіл» переходить до іншого гравця." },
    { en = "Movement speed increased by $w2%.", ua = "Швидкість пересування збільшена на $w2%." },
    { en = "Maximum health increased by $w2%.", ua = "Максимальне здоров'я збільшене на $w2%." },
    { en = "Leech increased by $w2%.", ua = "Висмоктування збільшене на $w2%." },
    { en = "Damage done reduced by $s2%.\nContains a portion of the essence of Aqu'sirr.", ua = "Завдавана шкода зменшена на $s2%.\nМістить частку есенції Акв'сірра." },
    { en = "Healing received reduced by $s3%.", ua = "Отримуване зцілення зменшено на $s3%." },
    { en = "$265143s1 Shadow damage inflicted every $t1 sec.\n\nOn expiration, jumps to the closest player.", ua = "Завдає $265143s1 шкоди від тіні кожні $t1 с.\n\nПісля завершення перестрибує до найближчого гравця." },
    { en = "$w1 Nature damge inflicted every $t1 sec.", ua = "Завдає $w1 шкоди від сил природи кожні $t1 с." },
    { en = "Inflicting $266077s1 Shadow damage to allies within $266077A1 yards every $266077t1 sec.\nA Plague Amalgam grows inside you.\nStunned.", ua = "Завдає $266077s1 тіньової шкоди союзникам у межах $266077A1 м кожні $266077t1 с.\nУсередині тебе росте Чумна амальгама.\nПриголомшено." },
    { en = "$281473s1 Shadow damage inflicted every $t1 sec.\n\nSummons an Ominous Cloud upon expiration.", ua = "Завдає $281473s1 шкоди від тіні кожні $t1 с.\n\nПісля завершення прикликає Зловісну Хмару." },
    { en = "Maximum health, damage done, and healing done increased by $s3%\n\n$?$W12=1[You are mind controlled upon expiration.]?$W12=5[You are mind controlled and release a $@spellname270589 upon expiration, inflicting $270589s1 Shadow damage to players within $270589a1 yards and causing them to flee in fear for $270589d2.][]", ua = "Максимальне здоров'я, завдавана шкода та зцілення збільшені на $s3%\n\n$?$W12=1[Після завершення дії ти потрапляєш під контроль розуму.]?$W12=5[Після завершення дії ти потрапляєш під контроль розуму та вивільняєш $@spellname270589, що завдає $270589s1 шкоди від тіні гравцям у радіусі $270589a1 м і змушує їх тікати в страху на $270589d2.][]" },
    { en = "$s1 Fire damage inflicted every $t1 sec.\nCreates a pool of Molten Gold when removed.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с.\nПісля зняття створює калюжу Розплавленого Золота." },
    { en = "Every fourth attack, The Golden Serpent will Tail Thrash its primary target.", ua = "Кожною четвертою атакою Золотий Змій завдає «Удару хвостом» своїй основній цілі." },
    { en = "Your next auto-attack will deal extra Physical damage.", ua = "Твоя наступна автоатака завдасть додаткову фізичну шкоду." },
    { en = "$w1 damage absorbed.\nDamage done increased by $s2%.", ua = "Поглинає $w1 шкоди.\nЗавдана шкода збільшена на $s2%." },
    { en = "Healing for $w1 every $t1 sec. Healing increases over time.", ua = "Зцілює $w1 здоров'я кожні $t1 с. Зцілення зростає з часом." },
    { en = "Versatility increased by ${$w1+$w2}.", ua = "Універсальність збільшено на ${$w1+$w2}." },
    { en = "Damage done reduced by $s4%.", ua = "Завдавана шкода зменшена на $s4%." },
    { en = "Inflicts $s1 Nature damage every $265986t1 sec.\n\nPhysical damage taken increased by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $265986t1 с.\n\nОтримувана фізична шкода збільшена на $s2%." },
    { en = "$s3 Shadow damage inflicted every $t3 sec.", ua = "Завдає $s3 шкоди від тіні кожні $t3 с." },
