    { en = "Damage done increased by $s1%.\nDamage taken increased by $s2%.\nHealing done increased by $s6%.", ua = "Завдавана шкода збільшена на $s1%.\nОтримувана шкода збільшена на $s2%.\nЗцілення збільшене на $s6%." },
    { en = "Slow movement speed.\nMighty melee attacks.", ua = "Низька швидкість пересування.\nМогутні атаки ближнього бою." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\nCauses Desiccation at the end of the effect.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nПісля завершення ефекту спричиняє «Висушення»." },
    { en = "Damage done reduced by $s1%.\nMovement speed reduced by $s2%.\nRemoved when healed above 90%.", ua = "Завдавана шкода зменшена на $s1%.\nШвидкість пересування знижена на $s2%.\nЗнімається після зцілення понад 90% здоров'я." },
    { en = "Damage taken from Sanitizing Strike increased by $s2%.", ua = "Шкода від «Очисного Удару» збільшена на $s2%." },
    { en = "Being interrupted causes a Blowback, creating a tornado at a nearby location.", ua = "Якщо вас перервати, виникає Зворотний порив, що породжує торнадо в сусідній точці." },
    { en = "Inflicts $s1 Nature damage and knocks back enemies within $A1 yards.", ua = "Завдає $s1 шкоди від сил природи та відкидає ворогів у радіусі $A1 м." },
    { en = "Increases Physical damage dealt by $s1%.\nReduces movement speed by $s2%.", ua = "Збільшує завдавану фізичну шкоду на $s1%.\nЗнижує швидкість пересування на $s2%." },
    { en = "Absorbs all healing.", ua = "Поглинає все зцілення." },
    { en = "Reducing healing received by $268080s1% against all enemies.", ua = "Зменшує зцілення, отримуване всіма ворогами, на $268080s1%." },
    { en = "Inflicting $268086s1 Shadow damage every $268086t1 sec to all enemies. This effect stacks.", ua = "Завдає $268086s1 тіньової шкоди всім ворогам кожні $268086t1 с. Цей ефект накопичується." },
    { en = "$268126s1 Physical damage inflicted when hit by any attacker.", ua = "Завдає $268126s1 фізичної шкоди при кожному влучанні нападника." },
    { en = "Increased Physical damage taken by $s2%. This effect stacks.", ua = "Отримувана фізична шкода збільшена на $s2%. Цей ефект накопичується." },
    { en = "$pri increased by $w1.", ua = "$pri збільшено на $w1." },
