    { en = "$s1 Physical damage every $t1 sec.\nStunned.", ua = "$s1 фізичної шкоди кожні $t1 с.\nПриголомшено." },
    { en = "Inflicts $s2 Shadow damage every $t2 sec.\nReduces movement speed by $s3%.", ua = "Завдає $s2 шкоди від тіні кожні $t2 с.\nЗнижує швидкість пересування на $s3%." },
    { en = "$?ml[Supplies and Gold rewards from world quests increased by $w4%.][Experience gained from killing monsters and completing quests increased by $w1%.]", ua = "$?ml[Нагороди припасами та золотом за світові завдання збільшено на $w4%.][Досвід, отриманий за вбивство монстрів і виконання завдань, збільшено на $w1%.]" },
    { en = "Lord Stormsong begins to Waken the Void, summoning many Awoken Void which pursue players and attempt to explode on them.", ua = "Лорд Штормосонг починає Пробуджувати Порожнечу, прикликаючи багатьох Пробуджених Порожнечі, які переслідують гравців і намагаються вибухнути біля них." },
    { en = "Unable to take actions.\nImmune to Stun.\nReceiving sufficient damage will remove the Ancient Mindbender from its host.", ua = "Не може діяти.\nНесприйнятливість до приголомшення.\nДостатня отримана шкода вижене Прадавнього викривлювача розуму з носія." },
    { en = "Absorbs all damage, converting it to blood energy.", ua = "Поглинає всю шкоду, перетворюючи її на кров'яну енергію." },
    { en = "Surrender to the Void and become a Disciple of the Vol'zith. Receiving sufficient damage will cancel the cast of Surrender to the Void.\n\n|cFF00AA99Whispers beckon you towards the Void.|r", ua = "Ти скоряєшся Порожнечі й стаєш Учнем Вол'зіт. Достатня отримана шкода перерве творення «Покори Порожнечі».\n\n|cFF00AA99Шепоти кличуть тебе до Порожнечі.|r" },
    { en = "Damage done to Dazar is redirected to T'zala.", ua = "Шкода, завдана Дазару, перенаправляється на Т'залу." },
    { en = "$s2% Holy damage inflicted every $t2 sec.\nStunned.", ua = "Завдає $s2% священної шкоди кожні $t2 с.\nПриголомшено." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nSilenced.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nЗмушено замовкнути." },
    { en = "Healing done reduced by $s1%.\n$?$w2>0[$w2 Plague damage every $t2 sec.][]", ua = "Здійснюване зцілення зменшено на $s1%.\n$?$w2>0[$w2 чумної шкоди кожні $t2 с.][]" },
    { en = "Damage of $@spellname270443 increased by $s1%.\n\nThis effect stacks with each consecutive melee attack against the same target.", ua = "Шкода «$@spellname270443» збільшена на $s1%.\n\nЦей ефект накопичується з кожною послідовною атакою ближнього бою по тій самій цілі." },
    { en = "Increases your movement speed by $s1%.", ua = "Збільшує твою швидкість пересування на $s1%." },
    { en = "$280485s1 Physical damage inflicted every $t2 sec.", ua = "Завдає $280485s1 фізичної шкоди кожні $t2 с." },
    { en = "Your healing spells restore $w1 mana.", ua = "Твої зцілювальні закляття відновлюють $w1 мани." },
    { en = "$s1 Nature damage every $t1 sec.\nMovement speed reduced by $s2%.", ua = "$s1 шкоди від сил природи кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "$s1% maximum health healed every $t1 sec.", ua = "Зцілює $s1% максимального здоров'я кожні $t1 с." },
    { en = "Disregarding foes, acquiring currency.", ua = "Не зважає на ворогів, збирає монети." },
    { en = "Deactivated. All damage taken reduced by 99%.", ua = "Деактивовано. Уся отримувана шкода зменшена на 99%." },
    { en = "Maximum health reduced by $s1%.\nInflicts $278150s1 Shadow damage every $t2 sec.", ua = "Максимальне здоров'я зменшене на $s1%.\nЗавдає $278150s1 шкоди від тіні кожні $t2 с." },
    { en = "Annihilation applied every $t1 sec.\nCharmed.", ua = "«Знищення» накладається кожні $t1 с.\nЗачаровано." },
    { en = "Constantly flees from melee combat unless snared or rooted.", ua = "Постійно тікає з ближнього бою, якщо тільки не сповільнений чи знерухомлений." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nExplodes for $272543s1 Shadow damage on expiration.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля завершення вибухає, завдаючи $272543s1 шкоди від тіні." },
    { en = "Explodes on contact, inflicting $272586s1 Fire damage and knocking back all enemies within $272586A1.", ua = "Вибухає при зіткненні, завдаючи $272586s1 вогняної шкоди та відкидаючи всіх ворогів у радіусі $272586A1." },
    { en = "Melee attacks inflict Fire damage.", ua = "Ближні атаки завдають шкоди вогнем." },
    { en = "Restores ${$w3/5} health and ${$w1/5} mana per second.", ua = "Відновлює ${$w3/5} здоров'я та ${$w1/5} мани щосекунди." },
    { en = "Restores $s1% Health and Mana every $t1 seconds for $d1. Must remain seated while eating.", ua = "Відновлює $s1% здоров'я та мани кожні $t1 секунд протягом $d1. Під час їжі потрібно лишатися сидячи." },
    { en = "Triggers a Dark Revelation upon expiration.", ua = "Після завершення спричиняє «Темне Одкровення»." },
    { en = "Absorbs $w1 damage.\nDamage increased by $s2%.\nKills the target when removed.", ua = "Поглинає $w1 шкоди.\nШкода збільшена на $s2%.\nПісля зняття вбиває ціль." },
    { en = "$s2 Physical damaqge inflicted every $t2 sec.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с." },
    { en = "Attack and casting speed slowed by $s%.", ua = "Швидкість атаки та прочитання сповільнена на $s%." },
    { en = "Healing taken reduced by $w1%.", ua = "Отримуване зцілення зменшено на $w1%." },
    { en = "Inflicts $s1 Shadow damage and applies Annihilation every $t1 sec.", ua = "Завдає $s1 шкоди від тіні та накладає «Знищення» кожні $t1 с." },
    { en = "All sources of healing trigger an additional $s1 points of healing.", ua = "Усі джерела зцілення додатково зцілюють на $s1." },
    { en = "Your Blood Plague deals damage $w5% more often.", ua = "Твоя «Кривава чума» завдає шкоди на $w5% частіше." },
    { en = "Forced to walk to your death.\nInflicts damage reduced by range and creates Minions of Zul upon removal.", ua = "Мусиш іти назустріч своїй смерті.\nЗавдає шкоди, що зменшується з відстанню, і після зняття створює Прислужників Зула." },
    { en = "Healing for $w1 every $t1 seconds.", ua = "Зцілює $w1 здоров'я кожні $t1 с." },
    { en = "$s2 Physical damage every $t2 sec.\nCreates a pool of Ruptured Blood on expiration.", ua = "$s2 фізичної шкоди кожні $t2 с.\nПісля завершення створює калюжу Прорваної Крові." },
    { en = "Haste increased by $w1 based on missing health.", ua = "Поспіх збільшено на $w1 залежно від втраченого здоров'я." },
    { en = "Melee attacks inflict Frost damage.", ua = "Атаки ближнього бою завдають шкоди від морозу." },
    { en = "Melee attacks increase the likelihood of seeking out a new target.", ua = "Атаки ближнього бою підвищують імовірність пошуку нової цілі." },
    { en = "Restores $s1% of your health per second. So rich... so decadent.", ua = "Відновлює $s1% твого здоров'я щосекунди. Такий насичений... такий розкішний." },
    { en = "You don't feel so good.", ua = "Тобі щось недобре." },
    { en = "Attacking your afflicted target will grant you Critical Strike.", ua = "Атаки по твоїй ураженій цілі дають тобі Критичний удар." },
    { en = "Explodes on death, inflicting Shadow damage to all enemies.", ua = "Вибухає після смерті, завдаючи шкоди від тіні всім ворогам." },
    { en = "Healing every $t2 sec.", ua = "Зцілює кожні $t2 с." },
    { en = "Healing done reduced by $s1%.", ua = "Здійснюване зцілення зменшено на $s1%." },
