    { en = "Reduces magic damage taken by $<reduction>.", ua = "Зменшує отриману магічну шкоду на $<reduction>." },
    { en = "Get out of the water!", ua = "Вибирайся з води!" },
    { en = "Inflicts Physical damage to the attacker on melee damage received.", ua = "Завдає фізичної шкоди нападнику при отриманні шкоди в ближньому бою." },
    { en = "All secondary stats increased by $w1.", ua = "Усі вторинні характеристики збільшено на $w1." },
    { en = "Periodically gaining energy.", ua = "Періодично отримує енергію." },
    { en = "Taking $w1% increased damage from $@auracaster.", ua = "Отримує на $w1% більше шкоди від $@auracaster." },
    { en = "Frost Strike$?s194913[, Glacial Advance,][] and Howling Blast grant Killing Machine and have a $s2% chance to generate a Rune.", ua = "«Удар морозу»$?s194913[, «Льодовиковий Наступ»,][] та «Виючий шквал» дають «Машину вбивства» й мають $s2% шансу створити Руну." },
    { en = "Disguised as a trogg.", ua = "Замасковано під троґа." },
    { en = "Inflicting $281940s1 Nature damage and applying a stack of $@spellname282010 to all enemies every $t1 sec.", ua = "Завдає $281940s1 шкоди від сил природи і накладає заряд $@spellname282010 на всіх ворогів кожні $t1 с." },
    { en = "$284420s1 Fire damage to all players every $t3 sec.", ua = "$284420s1 шкоди вогнем усім гравцям кожні $t3 с." },
    { en = "Damage done increased by $s1%.\nDamage received reduced by $s2%.", ua = "Завдавана шкода збільшена на $s1%.\nОтримувана шкода зменшена на $s2%." },
    { en = "Threat generation increased by $s2%.\n\nUpon expiration, transforms into an Agent of Demise.", ua = "Створення загрози збільшено на $s2%.\n\nПісля завершення перетворюється на Посланця Загибелі." },
    { en = "Inflicting $282412s1 Shadow damage and applying a stack of $@spellname282415 to all enemies every $t1 sec.", ua = "Завдає $282412s1 шкоди від тіні і накладає заряд $@spellname282415 на всіх ворогів кожні $t1 с." },
    { en = "$s1 Frost damage every second.\nMovement speed reduced by $s2%.", ua = "$s1 шкоди від морозу щосекунди.\nШвидкість пересування знижена на $s2%." },
    { en = "$?ml&a277253[Gold]?ml[Gold][]$?ml[ rewards from world quests increased by $w4%.][Experience gained from killing monsters and completing quests increased by $w1%.]", ua = "$?ml&a277253[Золоті]?ml[Золоті][]$?ml[ нагороди за світові завдання збільшено на $w4%.][Досвід, отриманий за вбивство монстрів і виконання завдань, збільшено на $w1%.]" },
    { en = "Immune to all damage.\n\nDefeating all summoned wisps will end this effect.", ua = "Несприйнятливість до будь-якої шкоди.\n\nЗнищення всіх прикликаних блукаючих вогників завершить цей ефект." },
    { en = "Damage taken from $@spellname282621 increased by $s2%.", ua = "Шкода, отримувана від «$@spellname282621», збільшена на $s2%." },
    { en = "Absorbing $s2% of incoming damage.", ua = "Поглинає $s2% вхідної шкоди." },
    { en = "Obscured.\n$?$w2>0[$w2 damage every $t2 sec.][]", ua = "Приховано.\n$?$w2>0[$w2 шкоди кожні $t2 с.][]" },
    { en = "Holy damage increased by $s1%.", ua = "Святу шкоду збільшено на $s1%." },
    { en = "Threat generation increased by $s2%.", ua = "Створення загрози збільшено на $s2%." },
    { en = "Inflicting $283422s2 Physical damage and knocking back all enemies in it's path.", ua = "Завдає $283422s2 фізичної шкоди і відкидає всіх ворогів на своєму шляху." },
    { en = "Melee attacks inflict Holy damage over time.", ua = "Атаки ближнього бою завдають священної шкоди з часом." },
    { en = "Damage dealt reduced by $s3%.\n\nComing into contact with a full-sized ally inflicts $284214s1 damage and stuns you for $284214d1.\n\nAllows you to hijack and tamper with Spark Bots.", ua = "Завдавана шкода зменшена на $s3%.\n\nЗіткнення із союзником звичайного розміру завдає $284214s1 шкоди та приголомшує тебе на $284214d1.\n\nДозволяє захоплювати іскроботів і порпатися в них." },
    { en = "You and your pet gain $s1% Leech.", ua = "Ви та ваш улюбленець отримуєте $s1% Висмоктування." },
    { en = "Damage taken from Magma Trap increased by $s3%.", ua = "Шкода від «Магмової пастки» збільшена на $s3%." },
    { en = "Being tempted by a Siren.", ua = "Тебе спокушає сирена." },
    { en = "Attacks received generate stacks of $@spellname284459.\nPlayers affected by $@spellname283572 do not generate stacks of $@spellname284459.", ua = "Отримані атаки генерують заряди $@spellname284459.\nГравці під дією $@spellname283572 не генерують зарядів $@spellname284459." },
    { en = "Allies damage and healing done increased.\nMelee attacks cause $@spellname284488.\nAllies killed while $@spellname284469 is active provide stacks of $@spellname284459.", ua = "Шкода та зцілення союзників збільшені.\nАтаки ближнього бою спричиняють $@spellname284488.\nСоюзники, вбиті, поки діє $@spellname284469, дають заряди $@spellname284459." },
    { en = "Moving causes Deadly Hex.", ua = "Рух спричиняє «Смертельний врок»." },
    { en = "Absorbs 50% of all incoming damage, up to a maximum of 300% of the player's maximum health in damage.", ua = "Поглинає 50% усієї вхідної шкоди, щонайбільше до 300% максимального здоров'я гравця." },
    { en = "The Diamond of the Unshakeable Protector is spent and requires time to recharge.", ua = "«Діамант Непохитного Захисника» вичерпано; йому потрібен час на перезарядження." },
    { en = "Shadow damage taken reduced by $s1%.\n\nTaking Shadow damage triggers Dark Knowledge.", ua = "Отримувана тіньова шкода зменшена на $s1%.\n\nОтримання тіньової шкоди викликає «Темне Знання»." },
    { en = "Haste increased by $s2%.\nYour heals apply Shadow-Touched, reducing Shadow damage taken by $284556s1% for $284556d.", ua = "Поспіх збільшено на $s2%.\nТвої зцілення накладають «Торкнутий тінню», зменшуючи отримувану тіньову шкоду на $284556s1% на $284556d." },
    { en = "Channeling the power of the Tempest Caller.", ua = "Підтримує силу Закликача бурі." },
    { en = "Immune to all healing effects.", ua = "Несприйнятливість до всіх ефектів зцілення." },
    { en = "Gaining $s1 Energy every $t1 sec.", ua = "Отримує $s1 енергії кожні $t1 с." },
    { en = "Inflicts $s2 Physical damage every $t2 sec.\nYou will bleed until healed past 90% of your maximum health.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с.\nТи стікатимеш кров'ю, доки тебе не зцілять понад 90% максимального здоров'я." },
    { en = "Some money is coming your way...", ua = "До тебе пливуть грошенята..." },
    { en = "Unable to be killed.\nDamage done increased by $w2%.", ua = "Не можна вбити.\nЗавдавана шкода збільшена на $w2%." },
    { en = "On expiration it will inflict $s1 Fire damage to all allies within $285355A1 yards.", ua = "Після завершення завдасть $s1 вогняної шкоди всім союзникам у радіусі $285355A1 м." },
    { en = "Inflicting $s1 Nature damage every $t1 sec.\nUpon expiration, an Energized Storm is created.\nCan absorb $@spellname285075s.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nПісля завершення дії створюється Заряджена Буря.\nМоже поглинати $@spellname285075s." },
    { en = "You are being stalked by a Spirit of Xuen!", ua = "Тебе вистежує Дух Сюеня!" },
    { en = "Increased chance to catch Midnight Salmon.", ua = "Збільшено шанс упіймати Опівнічного Лосося." },
    { en = "Absorbs the next $w1 damage taken.\nCannot be interrupted.", ua = "Поглинає наступні $w1 отриманої шкоди.\nНе можна перервати." },
    { en = "$286439s1 Nature damage to all enemies every $t1 sec.", ua = "$286439s1 шкоди від сил природи всім ворогам кожні $t1 с." },
    { en = "$?$w1>0[Damage dealt increased by $w1%.][Life forces are balanced.]", ua = "$?$w1>0[Завдана шкода збільшена на $w1%.][Життєві сили врівноважені.]" },
    { en = "$s2 Nature damage every $T2 sec.\n\nTriggers a $@spellname283411 that strikes all targets within line of sight upon expiraton.", ua = "$s2 шкоди від сил природи кожні $T2 с.\n\nПісля завершення спричиняє $@spellname283411, що вражає всі цілі в полі зору." },
    { en = "$s1 Shadow damage inflicted every $t1 sec. \nInterruptable by target.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с. \nЦіль може перервати." },
    { en = "Inflicts $286821s1 Nature damage upon expiring.\nCreates $@spellname286833s upon expiring.", ua = "Після завершення дії завдає $286821s1 шкоди від сил природи.\nПісля завершення дії створює $@spellname286833s." },
    { en = "$287296s1 Frost damage inflicted every $t1 sec.", ua = "Завдає $287296s1 шкоди від морозу кожні $t1 с." },
    { en = "Stunned.\n$s5 Frost damage inflicted every $t5 sec.", ua = "Приголомшено.\nЗавдає $s5 морозної шкоди кожні $t5 с." },
    { en = "$s1 Plague damage every second.\nMovement speed reduced by $s2%.", ua = "$s1 шкоди від чуми щосекунди.\nШвидкість пересування знижена на $s2%." },
    { en = "Immune to all damage.\n\nDefeating all summoned plaguelings will end this effect.", ua = "Несприйнятливість до будь-якої шкоди.\n\nЗнищення всіх прикликаних чумників завершить цей ефект." },
    { en = "$s1 Shadow damage inflicted every $t1 sec for $d.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с протягом $d." },
    { en = "Inflicts $244532s1 Frost damage to enemies within $244532A1 yards of impact.", ua = "Завдає $244532s1 шкоди від морозу ворогам у радіусі $244532A1 м від місця удару." },
    { en = "Absorbs up to $w1 damage shared amongst your allies with Enveloping Protection.", ua = "Поглинає до $w1 шкоди; поглинання спільне з твоїми союзниками під дією «Огортального Захисту»." },
    { en = "$287590s1 Shadow every second.", ua = "$287590s1 шкоди від тіні щосекунди." },
    { en = "Rooted.\nApplies a stack of chilling touch every $t3 sec for $d.", ua = "Знерухомлено.\nНакладає заряд «Холодного Дотику» кожні $t3 с протягом $d." },
    { en = "Protects Uu'nat if within $s1 yds.", ua = "Захищає Уу'ната, якщо той у радіусі $s1 м." },
    { en = "Extends your current V.I.G.O.R. setting for $d.", ua = "Подовжує твоє поточне налаштування V.I.G.O.R. на $d." },
    { en = "Movement speed reduced by $s1%.\nInflicting $s2 Frost damage every $t2 sec.", ua = "Швидкість пересування знижена на $s1%.\nЗавдає $s2 морозної шкоди кожні $t2 с." },
    { en = "Absorbing $w2 healing.", ua = "Поглинає $w2 зцілення." },
    { en = "Permanently stealthed.", ua = "Постійна скрадливість." },
    { en = "Haste increased by $w1 and Speed increased by $w2.", ua = "Поспіх збільшено на $w1, а Швидкість — на $w2." },
    { en = "Dealing $288269s1 Physical damage split among nearby enemies every $t1 sec.", ua = "Завдає $288269s1 фізичної шкоди, розділеної між ворогами поблизу, кожні $t1 с." },
    { en = "Critical strike chance increased by $s3% and critical strike damage increased by $s4%. Aimed Shot recovers its cooldown $s2% faster and Rapid Fire recovers its cooldown $s1% faster$?a471366[, the cast time of Aimed Shot by $471366s1%, and the Focus cost of Aimed Shot by $471366s2%.][.]", ua = "Шанс критичного удару збільшений на $s3%, а шкода критичних ударів — на $s4%. «Прицільний постріл» перезаряджається на $s2% швидше, а «Швидкий вогонь» — на $s1% швидше$?a471366[, час творення «Прицільного пострілу» зменшений на $471366s1%, а його вартість у зосередженні — на $471366s2%.][.]" },
    { en = "Melee attacks inflict additional Nature damage.", ua = "Атаки ближнього бою завдають додаткової шкоди від сил природи." },
    { en = "Unleashing a wave of Tide Elementals at your target.", ua = "Випускає хвилю припливних елементалів на твою ціль." },
    { en = "Threat generation reduced.", ua = "Створення загрози зменшено." },
    { en = "Haste rating increased by $w1.", ua = "Рейтинг поспіху збільшено на $w1." },
    { en = "Drops herbs when killed.", ua = "Після смерті випадають трави." },
    { en = "Attacks random targets.", ua = "Атакує випадкові цілі." },
    { en = "$291939s1 Nature damage inflicted every $t3sec.\nDamage taken from $@spellname291928 increased by $s4%.", ua = "Завдає $291939s1 шкоди від сил природи кожні $t3 с.\nШкода, отримувана від «$@spellname291928», збільшена на $s4%." },
    { en = "Inflicting $291949s1 Fire damage to all players not within cover every $t sec.", ua = "Завдає $291949s1 шкоди вогнем усім гравцям поза укриттям кожні $t с." },
    { en = "Reduces incoming healing by $s1%.", ua = "Зменшує отримуване зцілення на $s1%." },
    { en = "Incoming healing functions as normal.", ua = "Отримуване зцілення діє як зазвичай." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\nIncoming healing functions as normal.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nВхідне зцілення діє як зазвичай." },
    { en = "$s3 Nature damage inflicted every $t3sec.\nDamage taken from $@spellname292267 increased by $s4%.", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с.\nШкода від $@spellname292267 збільшена на $s4%." },
    { en = "Slowed by $w1% for $d.", ua = "Сповільнено на $w1% протягом $d." },
    { en = "Creatures from below are preparing to devour you.", ua = "Істоти знизу готуються тебе пожерти." },
    { en = "Feared.\n$s2 Shadow damage inflicted every $t2 sec.", ua = "Налякано.\n$s2 тіньової шкоди кожні $t2 с." },
    { en = "Inflicting $303585s1 Shadow Damage to nearby allies every $t1 sec.\nCreates $@spellname303819 every $t1 sec.\nUpon expiration, summons a Horrific Vision.", ua = "Завдає $303585s1 шкоди від тіні союзникам поблизу кожні $t1 с.\nСтворює $@spellname303819 кожні $t1 с.\nПісля завершення дії прикликає Жахливе Видіння." },
    { en = "Allows the wearer to see secret fish.", ua = "Дозволяє носієві бачити таємних риб." },
    { en = "Inflicting $302588s1 Frost damage every $t4 sec.\nMovement speed reduced by $s3%.\nMoving too close to a player with the opposite mark causes $@spellname294847.", ua = "Завдає $302588s1 шкоди від морозу кожні $t4 с.\nШвидкість пересування знижена на $s3%.\nНадто близький підхід до гравця з протилежною міткою спричиняє $@spellname294847." },
    { en = "You are holding a Flatulent Fish.", ua = "Ти тримаєш Газисту Рибу." },
    { en = "Inflicting $302589s1 Nature damage every $t4 sec.\nHealing received reduced by $s2%.\nMoving too close to a player with the opposite mark causes $@spellname294847.", ua = "Завдає $302589s1 шкоди від сил природи кожні $t4 с.\nОтримуване зцілення зменшене на $s2%.\nНадто близький підхід до гравця з протилежною міткою спричиняє $@spellname294847." },
    { en = "Inflicting $294856s1 Nature damage to all players every $t1 sec for $d.", ua = "Завдає $294856s1 шкоди від сил природи всім гравцям кожні $t1 с. протягом $d." },
    { en = "Spewing flammable fluid into the air.", ua = "Вивергає в повітря займисту рідину." },
    { en = "Inflicts $s2 Fire damage every $t2 sec for $d. This effect stacks.\n\nExplodes when dispelled, inflicting $294961s1 Fire damage to all players.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с. протягом $d. Цей ефект накопичується.\n\nПри розвіюванні вибухає, завдаючи $294961s1 шкоди вогнем усім гравцям." },
    { en = "Create a Hyper-Compressed Ocean.", ua = "Створи Гіперстиснений Океан." },
    { en = "Silenced.\nMovement speed reduced by $s1%.", ua = "Змушено замовкнути.\nШвидкість пересування знижена на $s1%." },
    { en = "Absorbing the next $w1 damage or healing taken.", ua = "Поглинає наступні $w1 отриманої шкоди або зцілення." },
    { en = "Damage taken from Wreck increased by $s2%.", ua = "Шкода від «Розтрощення» збільшена на $s2%." },
    { en = "Targeted with an Aqua Lance that will impact after $d, creating Raging Rapids which inflict $300244s1 Nature damage every $300244t1 sec to players within.", ua = "На тебе націлено «Водяний Спис», що вдарить через $d, створивши «Шалені Пороги», які завдають $300244s1 шкоди від сил природи кожні $300244t1 с гравцям усередині." },
    { en = "Inflicts $w2 Frost damage to players outside of the Eye of the Storm.\nDamage taken reduced by $s3%.", ua = "Завдає $w2 шкоди від морозу гравцям поза «Оком бурі».\nОтримувана шкода зменшена на $s3%." },
