    { en = "Damage against this target increased by $s1%.", ua = "Шкода по цій цілі збільшена на $s1%." },
    { en = "$w1 incoming damage and $w2 healing is suspended in time, and will be delivered over $296101d after this expires.", ua = "$w1 вхідної шкоди та $w2 зцілення зупинено в часі; їх буде застосовано протягом $296101d після завершення цього ефекту." },
    { en = "Combine 10 Prismatic Chips to generate a Prismatic Soul, granting you a Legendary Item.", ua = "Поєднай 10 Призматичних Уламків, щоб створити Призматичну Душу, яка надає вам Легендарний Предмет." },
    { en = "Create a Legendary Item for your specialization.", ua = "Створи Легендарний Предмет для вашої спеціалізації." },
    { en = "$s2% health healed every $t2 sec.\nDamage taken reduced by $s1%.", ua = "Зцілює $s2% здоров'я кожні $t2 с.\nОтримувана шкода знижена на $s1%." },
    { en = "Increases Gale Buffet damage inflicted by $s3%.", ua = "Збільшує шкоду, завдавану «Вихровим Натиском», на $s3%." },
    { en = "Allows walking over water while mounted. Any damage will cancel the effect.", ua = "Дозволяє ходити по воді верхи. Будь-яка шкода скасує ефект." },
    { en = "Mount Shoes Inflated.", ua = "Підкови їздової тварини надуто." },
    { en = "All damage done increased by $s1%.\nAll damage received reduced by $s2%.", ua = "Уся завдавана шкода збільшена на $s1%.\nУся отримувана шкода знижена на $s2%." },
    { en = "Infusing your body with arcane energies.", ua = "Наповнює твоє тіло арканними енергіями." },
    { en = "Receiving $s2% of damage taken by $@auracaster.", ua = "Отримує $s2% шкоди, якої зазнає $@auracaster." },
    { en = "Inflicts $s1 Nature damage to the victim and an ally within $297311a1 yards every $t1 sec.\n\nMoving within $297311a1 yards of Stolen Tech removes $@spellname297257 and temporarily powers the device.", ua = "Завдає $s1 шкоди від сил природи жертві та союзнику в радіусі $297311a1 м кожні $t1 с.\n\nНаближення на $297311a1 м до Викраденої технології знімає $@spellname297257 і тимчасово живить пристрій." },
    { en = "Powered Up!", ua = "Заряджено!" },
    { en = "Incapcitated.\n$s1 Nature damage inflicted every $t1 sec.", ua = "Виведено з ладу.\n$s1 шкоди від сил природи кожні $t1 с." },
    { en = "Absorbing all healing.", ua = "Поглинає все зцілення." },
    { en = "Forced to stand alone.\nBeing close to others inflicts $297672s1 Frost damage to you and all nearby players.", ua = "Мусиш стояти самотою.\nБлизькість до інших завдає $297672s1 морозної шкоди тобі та всім гравцям поблизу." },
    { en = "Surface Tension Maintained.", ua = "Поверхневий натяг збережено." },
    { en = "Prevents the application of Gooped.", ua = "Запобігає накладанню ефекту «Заляпаний слизом»." },
    { en = "Failure to see their lost love will Torment them.", ua = "Не бачачи втраченого кохання, зазнає «Муки»." },
    { en = "The mere sight of their lover will inflict Torment.", ua = "Сам лише вигляд коханої людини завдасть «Муки»." },
    { en = "All damage taken reduced by $s1%.\n\nInflicts Heart-Stopping Paralysis at 10 stacks.", ua = "Уся отримувана шкода знижена на $s1%.\n\nЗа 10 зарядів накладає «Серцезупинний параліч»." },
    { en = "$pri increased by $w2.", ua = "$pri збільшено на $w2." },
    { en = "Incapcitated.\n\n$s1 Plague damage inflicted every $t1 sec until the goop is destroyed.", ua = "Виведено з ладу.\n\n$s1 чумної шкоди кожні $t1 с, доки слиз не знищено." },
    { en = "Absorb $w1 damage.", ua = "Поглинає $w1 шкоди." },
    { en = "Stunned.\n\n$s1 Nature damage inflicted every $t1 sec.", ua = "Приголомшено.\n\nЗавдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Inflicting $s1 Nature damage to all players on each successful melee attack.", ua = "Завдає $s1 шкоди від сил природи всім гравцям за кожну успішну атаку ближнього бою." },
    { en = "Targeted for $@spellname299914", ua = "Обрано ціллю: $@spellname299914" },
    { en = "Immune to all damage.\nImmune to Silence and Interrupt effects.", ua = "Несприйнятливість до будь-якої шкоди.\nНесприйнятливість до ефектів німоти та переривання." },
    { en = "Suffering $s1 Shadow damage and losing $s2 Sanity every $t1 sec.", ua = "Зазнає $s1 тіньової шкоди та втрачає $s2 глузду кожні $t1 с." },
    { en = "Inflicting $s1 Frost damage every $t1 sec.\nUpon expiration, creates a pool of $@spellname300715.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\nПісля завершення дії створює калюжу $@spellname300715." },
    { en = "Inflicting $s1 Nature damage every $t1 sec.\nUpon expiration, creates a pool of $@spellname300719.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nПісля завершення дії створює калюжу $@spellname300719." },
    { en = "Stunned.\n$s2 Physical damage every $t2 sec.", ua = "Приголомшено.\n$s2 фізичної шкоди кожні $t2 с." },
    { en = "Inflicting $s1 Frost damage.\nApplying stacks of $@spellname294711.", ua = "Завдає $s1 шкоди від морозу.\nНакладає заряди $@spellname294711." },
    { en = "Inflicting $s1 Nature damage.\nApplying stacks of $@spellname294715.", ua = "Завдає $s1 шкоди від сил природи.\nНакладає заряди $@spellname294715." },
    { en = "You have created a hologram of King Mechagon.", ua = "Ти створив голограму Короля Мехагона." },
    { en = "All damage taken is shared with Ulmath.", ua = "Уся отримувана шкода розділяється з Ульматом." },
    { en = "Inflicting $301937s1 Shadow damage to targets within $301937A1 yards every $301657T2 sec.", ua = "Завдає $301937s1 шкоди від тіні цілям у радіусі $301937A1 м кожні $301657T2 с." },
    { en = "Feeling the pressure from Pashmar. \nAt 10 stacks, $@spellname30130 becomes $@spellname301832, causing you to become mind controlled.", ua = "Відчуваєш тиск Пашмара. \nЗа 10 зарядів «$@spellname30130» перетворюється на «$@spellname301832», і ти потрапляєш під контроль розуму." },
    { en = "Paintbot Orange", ua = "Фарбобот помаранчевий" },
    { en = "Paintbot Blue", ua = "Фарбобот синій" },
    { en = "Paintbot Green", ua = "Фарбобот зелений" },
    { en = "About to relocate with Ripple in Space.", ua = "Ось-ось переміститься за допомогою «Брижів у просторі»." },
    { en = "Periodically dealing Arcane damage to nearby enemies.", ua = "Періодично завдає арканної шкоди ворогам поблизу." },
    { en = "Arcane damage taken increased by $w1%.", ua = "Отримувана арканна шкода збільшена на $w1%." },
    { en = "Bleeding.\nInflicting $s2 Physical damage every $t2 sec.", ua = "Кровотеча.\nЗавдає $s2 фізичної шкоди кожні $t2 с." },
    { en = "Suffering $s1 Shadow damage and losing $s2 Sanity every $t1 sec, and healing the caster for 100% of that amount.", ua = "Зазнає $s1 тіньової шкоди та втрачає $s2 глузду кожні $t1 с, а заклинач зцілюється на 100% цієї величини." },
    { en = "Restores ${$w2/5} mana per second.", ua = "Відновлює ${$w2/5} мани щосекунди." },
    { en = "Ready to eat!", ua = "Можна їсти!" },
    { en = "In Horrific Visions, upon losing all Sanity or health, you revive instantly and gain $304816m1 Sanity and full health. Occurs once per Vision.", ua = "У Жахливих Видіннях, втративши весь глузд або здоров'я, ви миттєво оживаєте та отримуєте $304816m1 глузду й повне здоров'я. Трапляється раз на Видіння." },
    { en = "Damage done increased by $m0%, Damage taken reduced by $m0%", ua = "Завдавана шкода збільшена на $m0%, отримувана шкода зменшена на $m0%" },
    { en = "In Horrific Visions, the first revival you perform on an ally costs no Sanity.", ua = "У Жахливих Видіннях перше воскресіння союзника не коштує глузду." },
    { en = "In Horrific Visions, increases all party members' maximum Sanity by $m1.", ua = "У Жахливих Видіннях збільшує максимальний глузд усіх членів групи на $m1." },
    { en = "Inflicting ${$305251s1*(1+$@versadmg)} damage and absorbing ${$305251s2*(1+$@versadmg)} healing every $t1 sec.", ua = "Завдає ${$305251s1*(1+$@versadmg)} шкоди та поглинає ${$305251s2*(1+$@versadmg)} зцілення кожні $t1 с." },
    { en = "Shielded against damage, losing mana instead of health.\n\nInflicting $s1% of incoming damage back on attackers.", ua = "Захищено від шкоди: замість здоров'я втрачається мана.\n\nПовертає $s1% вхідної шкоди нападникам." },
    { en = "$s1 Fire damage inflicted every $t1 sec.\n\nIncreases damage from $@spellname305978 by $s2%.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с.\n\nЗбільшує шкоду від $@spellname305978 на $s2%." },
    { en = "Absorbs $w1 healing taken.\n$s2 Shadow damage every $t2 sec.", ua = "Поглинає $w1 отримуваного зцілення.\n$s2 шкоди від тіні кожні $t2 с." },
    { en = "Your movement speed is increased by the blessing of the Lightspawn.", ua = "Твою швидкість пересування збільшено благословенням Поріддя Світла." },
    { en = "Inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с протягом $d." },
    { en = "Inflicting $s3 Nature damage every $t3 sec.", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с." },
    { en = "Absorbs $306990w1 damage.\nImmune to Crowd Control and Interrupt effects.\nUnable to be slowed below $306990s3% of normal speed.", ua = "Поглинає $306990w1 шкоди.\nІмунітет до ефектів контролю та переривання.\nНе можна сповільнити нижче $306990s3% звичайної швидкості." },
    { en = "Suffering increasing Shadow damage every $307011T1 sec.", ua = "Зазнає дедалі більшої тіньової шкоди кожні $307011T1 с." },
    { en = "Suffering ${$313283s1} Shadow damage every $t1 sec.", ua = "Зазнає ${$313283s1} тіньової шкоди кожні $t1 с." },
    { en = "Inflicting $s1 Nature damage.\nUpon expiration, $@spellname307358 jumps to new targets.", ua = "Завдає $s1 шкоди від сил природи.\nПісля завершення дії $@spellname307358 перестрибує на нові цілі." },
    { en = "Inflicting $310455s1 Shadow damage every $t1 sec.", ua = "Завдає $310455s1 шкоди від тіні кожні $t1 с." },
    { en = "Suffering $w2 Arcane damage every $t2 sec.", ua = "Зазнає $w2 арканної шкоди кожні $t2 с." },
    { en = "Increasing Physical damage taken by $s3%.\nIncreasing damage taken from $@spellname307472 by $s2%.", ua = "Отримувана фізична шкода збільшена на $s3%.\nОтримувана шкода від $@spellname307472 збільшена на $s2%." },
    { en = "In Horrific Visions, killing an enemy grants $m1% increased movement speed and haste for $m2 sec. Stacks up to $m3.", ua = "У Жахливих Видіннях убивство ворога дає $m1% до швидкості руху та поспіху на $m2 с. Накопичується до $m3 разів." },
    { en = "In Horrific Visions, able to see and loot treasure chests in Tainted areas.", ua = "У Жахливих Видіннях дозволяє бачити й відкривати скрині зі скарбами в осквернених місцевостях." },
    { en = "You can perceive only some of the Prophet's illusions.", ua = "Ти бачиш лише частину ілюзій Пророка." },
    { en = "Charmed.\nDoing N'Zoth's bidding.\nHealth increased by $307832s2%.", ua = "Зачаровано.\nВиконує волю Н'Зота.\nЗдоров'я збільшене на $307832s2%." },
    { en = "Increases all Shadow damage taken by $s1%.", ua = "Збільшує всю отримувану тіньову шкоду на $s1%." },
    { en = "$308456s1 healed every $t1 sec.\nDamage caused by players afflicted by $@spellname308377 can not be healed.", ua = "Зцілює на $308456s1 кожні $t1 с.\nШкоду, завдану гравцями під дією «$@spellname308377», неможливо зцілити." },
    { en = "Damage you deal to Drest'agath can not be healed.", ua = "Шкоду, яку ти завдаєш Дрест'аґату, неможливо зцілити." },
    { en = "Damage dealt reduced by $s3%.\nAble to safely interact with Void Orbs.", ua = "Завдавана шкода зменшена на $s3%.\nМожна безпечно взаємодіяти зі Сферами Порожнечі." },
    { en = "Increases all damage taken from Eye of N'Zoth by $s2%.", ua = "Збільшує всю отримувану шкоду від «Ока Н'Зота» на $s2%." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nHaste reduced by $s2%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПоспіх знижено на $s2%." },
    { en = "Transformed into your Soulshape, increasing movement speed by $w3%.$?a137010[\nArmor increased by $344402s2%.\nStamina increased by $344402s1%.][]$?a342309[\nRegenerating $342309s1% health every $342309t sec.][]", ua = "Перетворено на твою «Душевну подобу»: швидкість пересування збільшена на $w3%.$?a137010[\nБроню збільшено на $344402s2%.\nВитривалість збільшено на $344402s1%.][]$?a342309[\nВідновлює $342309s1% здоров'я кожні $342309t с.][]" },
    { en = "$s1 Shadow damage inflicted every $t1.\n$@spellname310288 triggered on expiration.", ua = "Завдає $s1 шкоди від тіні кожні $t1.\nПісля завершення спрацьовує $@spellname310288." },
    { en = "Slowed $310359s1%.\n$@spellname310361 triggered on expiration.", ua = "Сповільнено на $310359s1%.\nПісля завершення спрацьовує $@spellname310361." },
    { en = "Increases your Mastery by $?c1[${$117906bc1*$w1}]?c2[${$117907bc1*$w1}][${$115636bc1*$w1}]%$?a137025[, Rising Sun Kick reduces Chi costs by $311054s1 for $311054d, and Blackout Kick reduces the cooldown of affected abilities by an additional ${$s8/1000} sec.]?a137023 [ and your Keg Smash increases the damage you deal to those enemies by $312106s1%, up to ${$312106s1*$312106u}% for $312106d.]?a137024[ and your Essence Font heals nearby allies for $311123s1 health on channel start and end.][ and your abilities are enhanced.]", ua = "Збільшує твою Майстерність на $?c1[${$117906bc1*$w1}]?c2[${$117907bc1*$w1}][${$115636bc1*$w1}]%$?a137025[, «Удар висхідного сонця» зменшує вартість ці на $311054s1 на $311054d, а «Удар затемнення» додатково скорочує перезарядження уражених здібностей на ${$s8/1000} с.]?a137023 [, а твій «Удар барилом» збільшує шкоду, яку ти завдаєш цим ворогам, на $312106s1%, аж до ${$312106s1*$312106u}%, на $312106d.]?a137024[, а твоє «Джерело есенції» зцілює союзників поблизу на $311123s1 здоров'я на початку й наприкінці підтримання.][, а твої здібності посилено.]" },
    { en = "A miasma cloud interferes with targeting.\n$s2 Shadow damage inflicted every $t2 sec.", ua = "Хмара міазмів заважає прицілюванню.\nЗавдає $s2 шкоди від тіні кожні $t2 с." },
    { en = "Calling upon Azeroth's Radiance.", ua = "Закликає Сяйво Азерота." },
    { en = "In Horrific Visions, defeating an Elite enemy restores $m1 Sanity.", ua = "У Жахливих Видіннях перемога над елітним ворогом відновлює $m1 глузду." },
    { en = "Absorbing up to $w1 per attack.", ua = "Поглинає до $w1 за атаку." },
    { en = "Damage taken from $@spellname311551 increased by $s2%.", ua = "Шкода від «$@spellname311551» збільшена на $s2%." },
    { en = "Surrounded by a mist of Anima, increasing your chance to Dodge by $s2% and dealing $311730s1 Shadow damage every $t1 sec to nearby enemies.", ua = "Тебе огортає туман аніми, що збільшує твій шанс ухилення на $s2% і завдає $311730s1 тіньової шкоди ворогам поблизу кожні $t1 с." },
    { en = "Carrying a $@spellname312099.", ua = "Несе $@spellname312099." },
    { en = "Suffering $w1 Arcane damage every $t1 sec. Dealing $s2% less damage to $@auracaster.", ua = "Зазнає $w1 арканної шкоди кожні $t1 с. Завдає $@auracaster на $s2% менше шкоди." },
    { en = "In Horrific Visions, while above 50% Sanity, your damage done is increased by $m1%.\n\nWhile below 50% Sanity, your damage taken is reduced by $m2%.", ua = "У Жахливих Видіннях, поки в тебе понад 50% глузду, твоя завдавана шкода збільшена на $m1%.\n\nПоки в тебе менше ніж 50% глузду, отримувана шкода зменшена на $m2%." },
    { en = "In Horrific Visions, able to see and loot treasure chests in Tainted and Corrupted areas.", ua = "У Жахливих Видіннях дозволяє бачити й відкривати скрині зі скарбами в осквернених і зіпсутих місцевостях." },
    { en = "In Horrific Visions, able to see and loot treasure chests in Tainted, Corrupted, and Lost areas.", ua = "У Жахливих Видіннях дозволяє бачити й відкривати скрині зі скарбами в осквернених, зіпсутих і втрачених місцевостях." },
    { en = "Taking $s1 Shadow damage every $t1 sec. Restores mana to the caster each time damage is dealt.", ua = "Отримує $s1 тіньової шкоди кожні $t1 с. Щоразу, коли завдається шкода, відновлює заклиначеві ману." },
    { en = "Damage done increased by $313334s1%.\nHealing done increase by $313334s2%.\nBecomes a $@spellname307832 when expired.", ua = "Завдавана шкода збільшена на $313334s1%.\nЗцілення збільшене на $313334s2%.\nПісля завершення перетворюється на «$@spellname307832»." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\n\nDrains $313402s1 Sanity after $d.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\n\nЧерез $d висмоктує $313402s1 глузду." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\n\nHaste reduced by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nПоспіх знижено на $s2%." },
    { en = "Critical strike increased by $w2.", ua = "Критичний удар збільшений на $w2." },
    { en = "Increases Critical Strike chance by $s1%.", ua = "Збільшує шанс критичного удару на $s1%." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\nPacified and Silenced.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nУмиротворено та змушено замовкнути." },
    { en = "Instantly slain upon expiring.", ua = "Після завершення дії гине миттєво." },
    { en = "Damage reduced by $w1%.", ua = "Шкода зменшена на $w1%." },
    { en = "Every $t1 sec, deal $325130s1 Nature damage to enemies within $325130A1 yds and reduce the remaining cooldown of your abilities by ${-$s2/1000} sec.", ua = "Кожні $t1 с завдає $325130s1 природної шкоди ворогам у радіусі $325130A1 м і скорочує залишок перезарядження твоїх здібностей на ${-$s2/1000} с." },
    { en = "Attacking, casting a spell or ability, consumes a mirror to inflict Shadow damage and reduce cast and movement speed by $320035s3%. \n\nYour final mirror will instead Root and Silence you for $317589d.", ua = "Атака чи застосування закляття або здібності витрачає дзеркало, що завдає шкоди від тіні та знижує швидкість прочитання й пересування на $320035s3%.\n\nОстаннє дзеркало натомість знерухомить тебе й накладе безмовність на $317589d." },
    { en = "Resting.", ua = "Відпочиває." },
    { en = "Damage dealt increased by $w2%.", ua = "Завдавана шкода збільшена на $w2%." },
    { en = "Drain power from each enemy within the area, reducing their damage done by 10% and increasing your Strength by 80 for 10 sec.", ua = "Висмоктує силу з кожного ворога в області, зменшуючи завдавану ними шкоду на 10% і збільшуючи твою Силу на 80 на 10 с." },
    { en = "Pulling enemies to your location and dealing $323798s1 Shadow damage to nearby enemies every $t1 sec.", ua = "Притягує ворогів до тебе та завдає $323798s1 тіньової шкоди ворогам поблизу кожні $t1 с." },
    { en = "Each strike has a chance of poisoning the enemy, inflicting $315585s1 Nature damage.", ua = "Кожен удар має шанс отруїти ворога, завдавши $315585s1 природної шкоди." },
    { en = "Increases damage taken from $@spellname315954 by $315954s2%.", ua = "Збільшує отримувану шкоду від $@spellname315954 на $315954s2%." },
    { en = "Damage of your next Mortal Strike increased by $w1%.", ua = "Шкода твого наступного «Смертельного удару» збільшена на $w1%." },
    { en = "Absorbs $316847w1 damage.\nImmune to Crowd Control effects.\nUnable to be slowed below $316847s3% of normal speed.", ua = "Поглинає $316847w1 шкоди.\nІмунітет до ефектів контролю.\nНе можна сповільнити нижче $316847s3% звичайної швидкості." },
    { en = "Absorbs $316848w1 damage.\nHealing received reduced by $316848w4%.\nImmune to Sanity draining effects.\nImmune to Crowd Control and Interrupt effects.\nUnable to be slowed below $316848s3% of normal speed.", ua = "Поглинає $316848w1 шкоди.\nОтримуване зцілення знижене на $316848w4%.\nІмунітет до ефектів виснаження Здорового глузду.\nІмунітет до ефектів контролю та переривання.\nНе можна сповільнити нижче $316848s3% звичайної швидкості." },
    { en = "Falling speed slowed by ephemeral black dragon wings.", ua = "Швидкість падіння сповільнена ефемерними крилами чорного дракона." },
    { en = "Suffering $w1 Shadow damage every $t1 sec. Casting speed slowed by $w2%. Melee attack speed slowed by $w3%.", ua = "Зазнає $w1 тіньової шкоди кожні $t1 с. Швидкість читання заклять сповільнена на $w2%. Швидкість атак ближнього бою сповільнена на $w3%." },
    { en = "Interrupt and Silence effects reduced by $w1%. $?a339124[Fear effects are reduced by $w4%.][]", ua = "Тривалість ефектів переривання та заглушення зменшена на $w1%. $?a339124[Тривалість ефектів страху зменшена на $w4%.][]" },
    { en = "$?c2[Each of your weapon attacks causes up to $10444s1 additional Fire damage]?c1[Fire spells deal  $382028s1% increased damage][].", ua = "$?c2[Кожна твоя атака зброєю завдає до $10444s1 додаткової шкоди вогнем]?c1[Закляття вогню завдають на $382028s1% більше шкоди][]." },
    { en = "Abilities not associated with your specialization are substantially empowered.", ua = "Здібності, не пов'язані з твоєю спеціалізацією, значно посилені." },
    { en = "$s2% maximum health healed every $t2 sec.\nDestroyed if struck by $@spellname319592.", ua = "Зцілює $s2% максимального здоров'я кожні $t2 с.\nРуйнується від влучання $@spellname319592." },
    { en = "Movement speed reduced by $320008s2%.", ua = "Швидкість пересування знижена на $320008s2%." },
    { en = "Hostile to Allies\n\nGain a stack of $@spellname332670 every $t5 sec.", ua = "Ворожість до союзників\n\nОтримуєш заряд $@spellname332670 кожні $t5 с." },
    { en = "Increases Diabolical Dooooooom! damage by $320142s2%.", ua = "Збільшує шкоду закляття «Диявольська Загибееееель!» на $320142s2%." },
    { en = "Suffering $320145s1 Physical damage every $320144T2 sec.", ua = "Зазнає $320145s1 фізичної шкоди кожні $320144T2 с." },
    { en = "$w2 healing absorbed.", ua = "Поглинає $w2 зцілення." },
    { en = "$s1 Plague damage every $t1 sec.\n$?$w3!=0[Movement speed reduced by $s3%.][]", ua = "$s1 шкоди від чуми кожні $t1 с.\n$?$w3!=0[Швидкість пересування знижена на $s3%.][]" },
    { en = "Inflicts $s2 Arcane damage every $t2 seconds for $d.", ua = "Завдає $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Noxious Spores form near your location every $t1 sec.", ua = "Кожні $t1 с поруч із тобою утворюються «Отруйні спори»." },
    { en = "Absorbing the next $w1 damage received.\nCannot be interrupted.", ua = "Поглинає наступні $w1 отриманої шкоди.\nНе можна перервати." },
    { en = "Movement speed reduced by $328664s1%.", ua = "Швидкість пересування знижена на $328664s1%." },
    { en = "Damage taken from $@spellname320784 increased by $s2%.", ua = "Шкода від «$@spellname320784» збільшена на $s2%." },
    { en = "Immobilized.\n$s1 Frost damage inflicted every $t1 sec.\n\nUpon expiration, $@spellname320788 spreads to players within $320790A1 yards.", ua = "Знерухомлено.\n$s1 морозної шкоди кожні $t1 с.\n\nПісля завершення $@spellname320788 поширюється на гравців у межах $320790A1 м." },
    { en = "Enslaved by drust magic. Hostile to players while above $s2% health.", ua = "Поневолено магією друстів. Вороже до гравців, поки здоров'я понад $s2%." },
    { en = "Directly controlling pet.", ua = "Пряме керування улюбленцем." },
    { en = "Absorbs $w1 damage.\nInflicts $321370s1 Frost damage to all players every $t2 sec.", ua = "Поглинає $w1 шкоди.\nЗавдає $321370s1 шкоди від морозу всім гравцям кожні $t2 с." },
    { en = "Damage taken from $@spellname321956 increased by $s2%.", ua = "Шкода від «$@spellname321956» збільшена на $s2%." },
    { en = "Absorbs $w1 damage.$?$w2>0[\nYour self-healing increased by $w2%.][]", ua = "Поглинає $w1 шкоди.$?$w2>0[\nТвоє самозцілення збільшене на $w2%.][]" },
    { en = "$w1 damage absorbed.\nWhile active $@spellname322450 cannot be interrupted.", ua = "Поглинає $w1 шкоди.\nПоки діє, $@spellname322450 неможливо перервати." },
    { en = "Inflicts $322567s1 Shadow damage to all players within $322567A1 yards.", ua = "Завдає $322567s1 шкоди від тіні всім гравцям у радіусі $322567A1 м." },
    { en = "All Gormling Larva are fixated on you.", ua = "Усі личинки гормлінгів зосередилися на тобі." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nYou duplicate all damage taken to all tethered players as Shadow damage.\nMove away from bonded player to dispel.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nУся отримана тобою шкода дублюється на всіх зв'язаних гравців як шкода від тіні.\nВідійди від пов'язаного гравця, щоб розвіяти ефект." },
    { en = "A meat hook will soon be hurled in your direction!", ua = "У твій бік невдовзі полетить м'ясний гак!" },
    { en = "Attacking all nearby enemies for Physical damage every $101546t1 sec.", ua = "Атакує всіх ворогів поблизу, завдаючи фізичної шкоди кожні $101546t1 с." },
    { en = "$s1 Shadow damage inflicted every $T1 sec.\nJumps to targets within $322746s2 yards.", ua = "Завдає $s1 шкоди від тіні кожні $T1 с.\nПерестрибує на цілі в радіусі $322746s2 м." },
    { en = "Causing winds to blow off of the platform.", ua = "Здіймає вітри, що здувають із платформи." },
    { en = "Causing winds to blow across the platform.", ua = "Здіймає вітри, що дмуть через платформу." },
    { en = "Movement speed reduced by $s3%.\n\nInflicts $s2 Physical damage every $t2 sec.", ua = "Швидкість пересування знижена на $s3%.\n\nЗавдає $s2 фізичної шкоди кожні $t2 с." },
    { en = "Taking $s2% increased damage.\nStunned.", ua = "Отримувана шкода збільшена на $s2%.\nПриголомшено." },
    { en = "Kael'thas cannot be healed beyond certain thresholds while the Shade of Kael'thas exists.", ua = "Кель'таса не можна зцілити понад певні межі, поки існує Тінь Кель'таса." },
    { en = "Losing $323543s1% of maximum health every $t3 sec.\n\nCreates $@spellname323130 upon death.", ua = "Втрачає $323543s1% максимального здоров'я кожні $t3 с.\n\nПісля смерті створює $@spellname323130." },
    { en = "$?<$w6<1>[Damage and healing increased by $w1% and haste increased by $w3%.\n\nIf you spend ${$s9~/10} sec idle, the Frenzy consumes $w3% of your health and ends.][Damage and healing increased by $w6% and haste increased by $w8%.]", ua = "$?<$w6<1>[Шкода та зцілення збільшені на $w1%, Поспіх збільшено на $w3%.\n\nЯкщо ти простоїш без дії ${$s9~/10} с, «Шаленство» поглине $w3% твого здоров'я і завершиться.][Шкода та зцілення збільшені на $w6%, Поспіх збільшено на $w8%.]" },
    { en = "$324659s1 Shadow damage inflicted to all players every $t1 sec.", ua = "Завдає $324659s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "A Ghastly Parishioner is fixated on you!", ua = "Примарний парафіянин зосередився на тобі!" },
    { en = "$?$W2>0[Nearby Rogue is tormenting the target, dealing $345316s1 Shadow damage for each combo point spent.][Combo points spent deal $345316s1 Shadow damage to the Rogue's tormented target. Haste increased by $s3%.]", ua = "$?$W2>0[Розбійник поблизу катує ціль, завдаючи $345316s1 шкоди від тіні за кожне витрачене комбо-очко.][Витрачені комбо-очки завдають $345316s1 шкоди від тіні катованій Розбійником цілі. Поспіх збільшено на $s3%.]" },
    { en = "The next $w2 damage and $w5 healing dealt will be reversed.", ua = "Наступні $w2 завданої шкоди та $w5 завданого зцілення буде обернено." },
    { en = "Damage taken from $@spellname323687 increased by $s1%.", ua = "Шкода від «$@spellname323687» збільшена на $s1%." },
    { en = "Damage taken reduced by 100%", ua = "Отримувана шкода зменшена на 100%" },
    { en = "Every ${$t1}.2 sec, casting $?a24858|a197625[Starsurge, Starfall,]?a768[Ferocious Bite, Shred, Tiger's Fury,]?a5487[Mangle, Ironfur,][Wild Growth, Swiftmend,] Moonfire, Wrath, Regrowth, Rejuvenation, Rake or Thrash on appropriate nearby targets.", ua = "Кожні ${$t1}.2 с творить $?a24858|a197625[«Зоряний сплеск», «Зорепад»,]?a768[«Лютий укус», «Шматування», «Лють тигра»,]?a5487[«Шматування», «Залізне хутро»,][«Дике зростання», «Швидке зцілення»,] «Місячний вогонь», «Гнів», «Відростання», «Омолодження», «Дряпання» або «Молотіння» на відповідних цілях поблизу." },
    { en = "Stunned.\n\n$s2 Shadow damage inflicted every $t2 sec.", ua = "Приголомшено.\n\nЗавдає $s2 тіньової шкоди кожні $t2 с." },
    { en = "Targeted for $@spellname323845.", ua = "Обрано ціллю: $@spellname323845." },
    { en = "Inflicts $323853s1 Shadow damage to all players every $t1 sec.", ua = "Завдає $323853s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "All damage increased by $s2%.", ua = "Уся шкода збільшена на $s2%." },
    { en = "Drained of Anima, damage taken increased by $s1%, cannot use abilities.", ua = "Аніму висмоктано: отримувана шкода збільшена на $s1%, неможливо використовувати здібності." },
    { en = "Generates $s1 Anima every $t1 sec. over $d.", ua = "Генерує $s1 аніми кожні $t1 с протягом $d." },
    { en = "You are being targeted by Millificent's $@spellname324047!", ua = "Мілліфісент націлює на тебе $@spellname324047!" },
    { en = "Movement speed slowed by $s3%.\nAbsorbing the next $w1 damage received.", ua = "Швидкість пересування сповільнена на $s3%.\nПоглинає наступні $w1 отриманої шкоди." },
    { en = "Mastery increased by $w1.\nMovement speed increased by $w2%.\nLess hindered by movement impairing effects.\nGenerating ${$w4/10} Rage per sec.\n$?$w8!=0[\nStrength increased by $w8%.][]$?$w9!=0[\nCritical strike chance increased by $w9%.][]", ua = "Майстерність збільшена на $w1.\nШвидкість пересування збільшена на $w2%.\nМенше піддається ефектам, що сповільнюють рух.\nГенерує ${$w4/10} од. люті щосекунди.\n$?$w8!=0[\nСила збільшена на $w8%.][]$?$w9!=0[\nШанс критичного удару збільшений на $w9%.][]" },
    { en = "Bleeding for $s1 Shadow damage every $t1 sec.", ua = "Кровотеча: $s1 шкоди від тіні кожні $t1 с." },
    { en = "Transformed into a powerful skeletal mage, greatly enhancing your Frostbolt, Fireball, and Arcane Blast and increasing your spell damage by $w2%.", ua = "Перетворено на могутнього мага-скелета: твої «Крижана стріла», «Вогняна куля» та «Чародійський вибух» значно підсилені, а шкода твоїх заклять збільшена на $w2%." },
    { en = "Damage done increased by $s1%.\n\nAbilities do not consume Anima.", ua = "Завдавана шкода збільшена на $s1%.\n\nЗдібності не витрачають аніму." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\n\nInflicts $324514s1 Shadow damage to the player and allies within $324514a1 yards.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\n\nЗавдає $324514s1 шкоди від тіні гравцю та союзникам у радіусі $324514a1 м." },
    { en = "Damage taken reduced by $w2%.", ua = "Отримувана шкода зменшена на $w2%." },
    { en = "Attackers siphon $325118s1 health.", ua = "Нападники висмоктують $325118s1 здоров'я." },
    { en = "$pri increased by $w1%.", ua = "$pri збільшено на $w1%." },
    { en = "$325004s1 Shadow damage every $t1 sec.", ua = "$325004s1 шкоди від тіні кожні $t1 с." },
    { en = "Empowered to cast $@spellname325020 and $@spellname325283. Damage and healing of Ascended Eruption increased by $w5%.", ua = "Можна творити «$@spellname325020» та «$@spellname325283». Шкода та зцілення «Виверження Вознесених» збільшені на $w5%." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\nMovement speed slowed by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Taking $w2% increased Physical damage from $@auracaster.", ua = "Отримує на $w2% більше фізичної шкоди від $@auracaster." },
    { en = "$?$w2=0[No Anima Containers are venting.\n]?$w2>1[$w2 Anima Containers are venting.\n][$w2 Anima Container is venting.\n]$w1 Shadow damage every $t1 sec.", ua = "$?$w2=0[Жодне Вмістилище аніми не випускає аніму.\n]?$w2>1[Аніму випускають $w2 |4Вмістилища:Вмістилищ; аніми.\n][Аніму випускає $w2 Вмістилище аніми.\n]$w1 шкоди від тіні кожні $t1 с." },
    { en = "Suffering $w1 damage every $t1 sec. When damaged, the attacker is healed for $325118m1.", ua = "Зазнає $w1 шкоди кожні $t1 с. Коли ціль зазнає шкоди, нападник зцілюється на $325118m1." },
    { en = "The Monk's abilities have a $h% chance to affect the target a second time at $s1% effectiveness as Shadow damage or healing.", ua = "Здібності монаха мають $h% шанс подіяти на ціль удруге з $s1% ефективності як шкода від тіні або зцілення." },
    { en = "Melee attacks inflict an additional $325550s1 Nature damage.", ua = "Атаки ближнього бою завдають додатково $325550s1 шкоди від сил природи." },
    { en = "Inflicted $s1% of Kael'thas's maximum health every $t1 sec.", ua = "Завдає $s1% максимального здоров'я Кель'таса кожні $t1 с." },
    { en = "Suffering $325725s1 Shadow damage every $325725T1 sec.\nTransfers to the ground when removed, exploding after $325647D.", ua = "Зазнає $325725s1 тіньової шкоди кожні $325725T1 с.\nПри знятті переходить на землю й вибухає через $325647D." },
    { en = "$w1 Shadow damage every $t1 sec.\nDamage received by the victim of $@spellname325379 is copied to you as a damage over time effect.", ua = "$w1 шкоди від тіні кожні $t1 с.\nШкода, якої зазнає жертва $@spellname325379, копіюється на тебе як періодична шкода." },
    { en = "Healing done increased by $s1%.", ua = "Здійснюване зцілення збільшено на $s1%." },
    { en = "Stunned.\n\n$s1 Arcane damage inflicted every $t1 sec until the $@spellname326302  is destroyed.", ua = "Приголомшено.\n\nЗавдає $s1 арканної шкоди кожні $t1 с, доки $@spellname326302 не буде знищено." },
    { en = "Bonded with $@auracaster. Every $327097d, they may empower the bond, granting bonuses based on your respective roles.", ua = "Пов'язано з $@auracaster. Кожні $327097d цей союзник може посилити зв'язок, даючи бонуси залежно від ролі кожного з вас." },
    { en = "${$326700s1} Shadow damage inflicted every $t1 sec.", ua = "Завдає ${$326700s1} шкоди від тіні кожні $t1 с." },
    { en = "Inflicting $326833s1 Shadow damage to all players every $324831t1 sec.", ua = "Завдає $326833s1 шкоди від тіні всім гравцям кожні $324831t1 с." },
    { en = "Summoning Ox, Crane, and Tiger adepts through the mirror.", ua = "Прикликає крізь дзеркало адептів Вола, Журавля й Тигра." },
    { en = "Energized by $@auracaster, increasing damage, healing, and mitigation by $s2% until Kindred Empowerment runs out.\n\nEmpowerment remaining: ${$w1-1}", ua = "Наснажено від $@auracaster: шкода, зцілення та захист збільшені на $s2%, доки не скінчиться «Спільне наснаження».\n\nЗалишок наснаження: ${$w1-1}" },
    { en = "$?$w1>0[$w1% of damage taken is redirected to $@auracaster.][Taking ${$s1*$e1}% of damage taken by bonded partner.]", ua = "$?$w1>0[$w1% отримуваної шкоди перенаправляється на $@auracaster.][Отримуєш ${$s1*$e1}% шкоди, якої зазнає пов'язаний напарник.]" },
    { en = "Receiving $327148s1% of healing dealt by $@auracaster.", ua = "Отримує $327148s1% зцілення, яке творить $@auracaster." },
