    { en = "$s3% of healing received is redirected to the$@spellname365293.", ua = "$s3% отриманого зцілення перенаправляється на $@spellname365293." },
    { en = "Attack speed decreased by $s2%.\nCast speed decreased by $s3%.", ua = "Швидкість атаки знижена на $s2%.\nШвидкість прочитання знижена на $s3%." },
    { en = "$s1% mana regenerated every $t1 sec.", ua = "Відновлює $s1% мани кожні $t1 с." },
    { en = "Immune to the effects of Lost Soul.\n\nDamage taken by $@spellname362405 increased by $s1%.", ua = "Несприйнятливість до ефектів «Загубленої душі».\n\nШкода, отримувана від $@spellname362405, збільшена на $s1%." },
    { en = "Passenger Protection.", ua = "Захист пасажира." },
    { en = "Increases $@spellname365682 damage taken by $365682s3%.", ua = "Збільшує отримувану шкоду від $@spellname365682 на $365682s3%." },
    { en = "While this armor is between players and Cartel Overseer, it absorbs all attacks.", ua = "Поки ця броня між гравцями та Наглядачем Картелю, вона поглинає всі атаки." },
    { en = "$@spellname365751 damage taken increased by $w2%.", ua = "Шкода від $@spellname365751 збільшена на $w2%." },
    { en = "$368660s1 Shadow damage inflicted every $t2 sec.\n\nInflicts $?diff15|diff16 [$361999s1 Twilight damage to all players within $361999A1 yds][]$?diff14|diff17 [$366933s1 Twilight damage][] upon expiration, or when coming into contact with $@spellname365966.", ua = "Завдає $368660s1 шкоди від тіні кожні $t2 с.\n\nПісля завершення або при контакті з «$@spellname365966» завдає $?diff15|diff16 [$361999s1 сутінкової шкоди всім гравцям у радіусі $361999A1 м][]$?diff14|diff17 [$366933s1 сутінкової шкоди][]." },
    { en = "Inflicting $366366s1 Cosmic damage to enemies every $t1 sec.", ua = "Завдає $366366s1 космічної шкоди ворогам кожні $t1 с." },
