    { en = "$s1 Cosmic damage every $t1 sec.", ua = "$s1 космічної шкоди кожні $t1 с." },
    { en = "Damage taken from $@spellname366408 increased by $s1%.\nDamage done increased by $s2%.\nHealing done increased by $s2%", ua = "Шкода від «$@spellname366408» збільшена на $s1%.\nЗавдавана шкода збільшена на $s2%.\nЗцілення збільшене на $s2%" },
    { en = "Inflicting $366943s1 Cosmic damage to all enemies every $t1 sec.", ua = "Завдає $366943s1 космічної шкоди всім ворогам кожні $t1 с." },
    { en = "Movement speed increased by $w1%.\nDamage done increased by $w2%.", ua = "Швидкість пересування збільшена на $w1%.\nЗавдавана шкода збільшена на $w2%." },
    { en = "All damage inflicted increased by $s2%.", ua = "Уся завдавана шкода збільшена на $s2%." },
    { en = "Dodge rating increased by $w2.", ua = "Рейтинг ухилення збільшений на $w2." },
    { en = "Upon reaching ${$u1+1} stacks or its removal, the Volatile Satchel detonates for $367901w1 Fire damage.", ua = "Сягнувши ${$u1+1} зарядів або після зняття «Нестійка торбинка» вибухає, завдаючи $367901w1 вогняної шкоди." },
    { en = "Moving away from the target will deal $w5 Shadow damage around it.", ua = "Віддалення від цілі завдасть $w5 тіньової шкоди довкола неї." },
