    { en = "$@auracaster is restoring mana to you when they cast an empowered spell.$?$w2>0[\n\nHealing and damage done increased by $w2%.][]", ua = "$@auracaster відновлює тобі ману, коли творить посилене закляття.$?$w2>0[\n\nЗцілення та завдана шкода збільшені на $w2%.][]" },
    { en = "Immune to damage.\nHeals by $369576s1% upon expiration.", ua = "Несприйнятливість до шкоди.\nПісля завершення зцілює на $369576s1%." },
    { en = "Combine the objects into something new!", ua = "Поєднай об'єкти в щось нове!" },
