    { en = "Frozen and unable to act. $s3 Frost damage inflicted every $t3 sec.", ua = "Заморожено, діяти неможливо. $s3 морозної шкоди кожні $t3 с." },
    { en = "Inflicts $s2 Nature damage every $t2 sec. and increases Nature damage taken by $s1%.\n\nChains to other players within 5 yards.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с. і збільшує отримувану шкоду від сил природи на $s1%.\n\nПерекидається на інших гравців у радіусі 5 м." },
    { en = "Frost damage taken increased by $s4%. Trapped in a $@spellname371591 at 10 stacks.\n\nFire damage taken reduced by $s3%.", ua = "Отримувана морозна шкода збільшена на $s4%. За 10 зарядів потрапляєш у пастку $@spellname371591.\n\nОтримувана вогняна шкода зменшена на $s3%." },
    { en = "You will trigger a burst of restorative energy after spending $w1 more Rage.", ua = "Витративши ще $w1 од. люті, ти вивільниш сплеск відновлювальної енергії." },
    { en = "Inflicts increasing Elemental damage while in the center of the chamber.", ua = "Завдає дедалі більшу стихійну шкоду, перебуваючи в центрі зали." },
    { en = "$s1 Frost damage inflicted every $t1 sec.\n\nUpon expiration or removal, inflicts $371979s1 Frost damage to all other players within $371979A1 yards.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\n\nПісля завершення або зняття завдає $371979s1 шкоди від морозу всім іншим гравцям у радіусі $371979A1 м." },
    { en = "Inflicts $w1 Elemental damage every $t1 sec.", ua = "Завдає $w1 стихійної шкоди кожні $t1 с." },
    { en = "Movement speed reduced by $s1%.\nCan be removed by $@spellname372045.\n\nBecome wrapped in webs after reaching $s2 applications.", ua = "Швидкість пересування знижена на $s1%.\nМожна зняти за допомогою $@spellname372045.\n\nПісля $s2 накладань тебе сповиє павутиння." },
    { en = "Stunned.\nCan be removed by $@spellname372045.\n\nWrapped in webs!", ua = "Приголомшено.\nМожна зняти за допомогою $@spellname372045.\n\nСповито павутинням!" },
    { en = "The duration of incoming crowd control effects are increased by $s2%.", ua = "Тривалість вхідних ефектів контролю збільшена на $s2%." },
    { en = "$s1 Physical damage inflicted every $t1 sec.\n\nReleasing $@spellname372030 every $t1 sec.", ua = "Завдає $s1 фізичної шкоди кожні $t1 с.\n\nВипускає $@spellname372030 кожні $t1 с." },
    { en = "Damage taken from Web Blast increased by $385083s2%.", ua = "Шкода від «Пострілу павутиною» збільшена на $385083s2%." },
