    { en = "Prevents all damage below $375809s2% remaining health.\n\nEmpowers nearby allies increasing damage done, decreasing damage taken, and healing every second.", ua = "Запобігає будь-якій шкоді, коли здоров'я нижче $375809s2%.\n\nПідсилює союзників поблизу: збільшує їхню завдану шкоду, зменшує отримувану та зцілює їх щосекунди." },
    { en = "Inflicts increasing Frost damage over time.", ua = "З часом завдає дедалі більшу шкоду від морозу." },
    { en = "Inflicts increasing Fire damage over time.", ua = "З часом завдає дедалі більшу шкоду вогнем." },
    { en = "Increases damage done by Clutchwatcher's Rage by $375829s2%.", ua = "Збільшує шкоду, завдавану «Люттю хранительки кладки», на $375829s2%." },
    { en = "$375873s2 Fire damage every $375873T2 sec.", ua = "$375873s2 шкоди вогнем кожні $375873T2 с." },
    { en = "Damage done increased by $s1%.$?diff16[][\nMortal Wounds duration doubled.]", ua = "Завдавана шкода збільшена на $s1%.$?diff16[][\nТривалість «Смертельних ран» подвоєна.]" },
    { en = "The Greatstaff is tracking you, inflicting $375843s1 Nature damage to nearby players.", ua = "Великий посох стежить за тобою, завдаючи $375843s1 шкоди від сил природи гравцям поблизу." },
    { en = "$s2 Physical damage inflicted every $t2 sec.\n\nDamage taken from $@spellname375929 increased by $s3%.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с.\n\nШкода від $@spellname375929 збільшена на $s3%." },
    { en = "Stunned.\n$376260s2 Nature damage every half-second.", ua = "Приголомшено.\n$376260s2 шкоди від сил природи кожні пів секунди." },
    { en = "Armor reduced by $376272s2%.", ua = "Броня знижена на $376272s2%." },
    { en = "Cause nearby creatures to flee in terror of the vortex.", ua = "Змушує істот поблизу тікати в жаху від вихору." },
    { en = "$s1 Arcane damage inflicted every $t1 sec.\nHaste reduced by $s2%.", ua = "Завдає $s1 арканної шкоди кожні $t1 с.\nПоспіх зменшено на $s2%." },
    { en = "Riding with Majordomo Selistra. Hold on tight!", ua = "Їдеш верхи з мажордомом Селістрою. Тримайся міцно!" },
    { en = "Marked for $@spellname376634!", ua = "Позначено для $@spellname376634!" },
    { en = "Raszageth's fury has manifested a lightning storm in this area.", ua = "Лють Расзаґет породила в цій місцевості грозову бурю." },
    { en = "$376732s1 Nature damage inflicted every $t1 sec.", ua = "Завдає $376732s1 шкоди від сил природи кожні $t1 с." },
    { en = "Absorbs $w2 damage taken.\n$@spellname376783 triggered every $t1 sec.", ua = "Поглинає $w2 отримуваної шкоди.\n$@spellname376783 спрацьовує кожні $t1 с." },
    { en = "$@spellname376783 damage taken increased by $w1%.", ua = "Шкода від $@spellname376783 збільшена на $w1%." },
    { en = "$s2 Nature damage inflicted every $t2 sec.\n\nDamage taken from $@spellname376829 increased by $s3%.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с.\n\nШкода від $@spellname376829 збільшена на $s3%." },
    { en = "Marked for $@spellname376864!", ua = "Позначено для $@spellname376864!" },
    { en = "Being dragged by Treemouth.\n\nOn expiration, Treemouth Consumes the closest player!", ua = "Тебе тягне Дереворот.\n\nПісля завершення Дереворот поглинає найближчого гравця!" },
    { en = "Movement speed reduced by $s1%.\nRemoved by taking Fire damage.", ua = "Швидкість пересування знижена на $s1%.\nЗнімається отриманням вогняної шкоди." },
    { en = "Skyriding Charges recover faster.", ua = "Заряди небесної їзди відновлюються швидше." },
    { en = "Grants ${$s1*$mas}% Mastery.", ua = "Дає ${$s1*$mas}% Майстерності." },
    { en = "$s2 Arcane damage inflicted every $t2 sec.\nMovement speed reduced by $s1%.\n\nUpon removal, triggers a $@spellname377561.", ua = "Завдає $s2 арканної шкоди кожні $t2 с.\nШвидкість пересування знижена на $s1%.\n\nПісля зняття спричиняє $@spellname377561." },
    { en = "Deal $w1 Nature damage per second to all enemies within $s5 yards, intensifying by $s4% each second.", ua = "Завдає $w1 природної шкоди щосекунди всім ворогам у радіусі $s5 м, посилюючись на $s4% щосекунди." },
    { en = "Inflicts $377881s1 Nature damage to players players within range and jumps to the nearest player.\n\n$?diff14|diff17|diff15 [$s4% reduced movement speed.][]$?diff16 [Rooted.][]", ua = "Завдає $377881s1 шкоди від сил природи гравцям у зоні досяжності та перестрибує на найближчого гравця.\n\n$?diff14|diff17|diff15 [Швидкість пересування знижена на $s4%.][]$?diff16 [Знерухомлено.][]" },
    { en = "$s1 Nature damage every $t1 sec.\n$s2% reduced movement speed.\nForced movement effects are reduced.", ua = "$s1 шкоди від сил природи кожні $t1 с.\nШвидкість пересування знижена на $s2%.\nЕфекти примусового переміщення послаблені." },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\n\nReduces movement speed by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nЗнижує швидкість пересування на $s2%." },
    { en = "Your Vigor is increased to $s2.", ua = "Ваша Снага збільшується до $s2." },
    { en = "Your Vigor regeneration rate is accelerated to $s1 Vigor every $s2 sec while grounded.", ua = "Швидкість відновлення Снаги пришвидшується до $s1 Снаги кожні $s2 сек, поки ви на землі." },
    { en = "Thrill of the Skies generates $s1 Vigor every $s2 sec.", ua = "«Захват небес» генерує $s1 Снаги кожні $s2 сек." },
    { en = "Increases damage done by $s2%.\nIncreases haste by $s1%.", ua = "Збільшує завдавану шкоду на $s2%.\nЗбільшує поспіх на $s1%." },
    { en = "$s2 Physical damage inflicted every $t2 sec. until healed over 90% health.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с., доки здоров'я не зцілено понад 90%." },
    { en = "While $@spellname378022, Treemouth absorbs the next $w1 damage. If broken, Treemouth spits the consumed player out.", ua = "Поки діє $@spellname378022, Деревопаща поглинає наступні $w1 шкоди. Якщо щит зламано, Деревопаща випльовує проковтнутого гравця." },
    { en = "Inflicts $s1 Nature damage every $t1 sec and reduces movement speed by $s2%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с. і знижує швидкість пересування на $s2%." },
    { en = "Increases all damage dealt by $w1%.", ua = "Збільшує всю завдавану шкоду на $w1%." },
    { en = "Your next healing or damaging Nature spell $?a1246131[or Hex ][]is instant cast and costs no mana.", ua = "Ваше наступне закляття Природи, що зцілює чи завдає шкоди, $?a1246131[або Вроки ][]є миттєвим і не коштує мани." },
    { en = "Your next $?a137015[Black Arrow]?a466932[Black Arrow][Kill Shot] can be used on any target, regardless of their current health.", ua = "Наступне застосування $?a137015[«Чорної стріли»]?a466932[«Чорної стріли»][«Добивального пострілу»] можливе на будь-якій цілі незалежно від її поточного здоров'я." },
    { en = "Absorbing $w1 damage. \n\nEnemies within range suffer $379080s1 Frost damage every sec.", ua = "Поглинає $w1 шкоди. \n\nВороги в радіусі дії зазнають $379080s1 шкоди від морозу щосекунди." },
    { en = "Critical Strike decreased by $w1.", ua = "Критичний удар зменшений на $w1." },
    { en = "Inflicts $381250s1 Nature damage to all players every $t1 sec.", ua = "Завдає $381250s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "Physical damage taken increased by $s3%.\n\nIncapacitated.", ua = "Отримувана фізична шкода збільшена на $s3%.\n\nВиведено з ладу." },
    { en = "Nature damage taken increased by $381515s1%.", ua = "Отримувана шкода від сил природи збільшена на $381515s1%." },
    { en = "Inflicts $381518s1 Nature damage every $381518T1 sec.", ua = "Завдає $381518s1 шкоди від сил природи кожні $381518T1 с." },
    { en = "$381526s1 Fire damage $381526t1 sec.", ua = "$381526s1 шкоди вогнем кожні $381526t1 с." },
    { en = "$381958s1 Nature damage every $t2 sec.\n\nUpon expiration, inflicts up to $381613s1 Nature damage$?diff14|diff15|diff17 [ and creates a $@spellname377662 at the wearer's location][]. This damage is reduced the further away players are from the blast.", ua = "$381958s1 шкоди від сил природи кожні $t2 с.\n\nПісля завершення завдає до $381613s1 шкоди від сил природи$?diff14|diff15|diff17 [ і створює «$@spellname377662» в місці носія][]. Ця шкода зменшується, що далі гравці від вибуху." },
    { en = "Each strike has a chance of poisoning the enemy, reducing their damage by ${$392388s1*-1}.1% for $392388d.", ua = "Кожен удар має шанс отруїти ворога, зменшивши його шкоду на ${$392388s1*-1}.1% на $392388d." },
    { en = "Each strike has a chance of inflicting Nature damage and applying Amplifying Poison. Envenom consumes the poison to deal increased damage.", ua = "Кожен удар має шанс завдати природної шкоди й накласти «Підсилювальну отруту». «Отруєння» витрачає отруту, завдаючи більшої шкоди." },
    { en = "Inflicts $381862s1 Fire damage every $t1 sec.\n\nExplodes upon removal, inflicting $381864s2 Fire damage to nearby players and creating $@spellname384773.", ua = "Завдає $381862s1 шкоди вогнем кожні $t1 с.\n\nПісля зняття вибухає, завдаючи $381864s2 шкоди вогнем гравцям поблизу та створюючи $@spellname384773." },
    { en = "Heals $w1 every $t1 sec.$?$w2>0[\n\nReceiving $w2% increased healing from $@auracaster.][]", ua = "Зцілює $w1 здоров'я кожні $t1 с.$?$w2>0[\n\nЗцілення, отримуване від $@auracaster, збільшено на $w2%.][]" },
    { en = "Protected by an arcane sentry.", ua = "Під захистом арканного вартового." },
    { en = "Receiving additional healing from $@auracaster.", ua = "Отримує додаткове зцілення від $@auracaster." },
    { en = "Restores $s1 health per second.", ua = "Відновлює $s1 здоров'я щосекунди." },
    { en = "Allows you to detect and mark treasures through physical barriers in the Dragon Isles outdoor world.", ua = "Дозволяє тобі виявляти й позначати скарби крізь фізичні перешкоди у відкритому світі Драконових Островів." },
    { en = "Opens nearly any locked chest in the Dragon Isles outdoor world.", ua = "Відмикає майже будь-яку замкнену скриню у відкритому світі Драконових Островів." },
    { en = "Absorbing $w1 damage.\n\nInflicts $382541s1 Nature damage to all players every $t3 sec.", ua = "Поглинає $w1 шкоди.\n\nЗавдає $382541s1 шкоди від сил природи всім гравцям кожні $t3 с." },
    { en = "Damage taken from Consecration and Divine Hammers increased by $382538s1%.", ua = "Шкода від «Освячення» та «Божественних молотів» збільшена на $382538s1%." },
    { en = "Damage and Healing done increased by $s2%.", ua = "Завдавана шкода та зцілення збільшені на $s2%." },
    { en = "Periodically creating several $@spellname383686 nearby.", ua = "Періодично створює поруч кілька $@spellname383686." },
    { en = "Strunraan's presence electrifies the air.", ua = "Присутність Струнраана електризує повітря." },
    { en = "Increased chance to catch Aileron Seamoth.", ua = "Збільшено шанс упіймати Крилоперого Морського Метелика." },
    { en = "While Enraged, your auto-attacks can no longer miss.", ua = "Поки діє «Розлюченість», твої автоатаки більше не можуть схибити." },
    { en = "Sit next to the old dwarf and take a break.", ua = "Сидиш поруч зі старим дворфом і відпочиваєш." },
    { en = "Each time you dodge or an enemy misses you,your next Tiger Palm or Spinning Crane Kick deals $383800s1% increased damage.", ua = "Щоразу, коли ти ухиляєшся або ворог промахується, твоя наступна «Тигряча долоня» чи «Обертовий удар журавля» завдає на $383800s1% більше шкоди." },
    { en = "Damage taken reduced by $s1%.\n\nCan be removed by $@spellname389446.", ua = "Отримувана шкода зменшена на $s1%.\n\nМожна зняти за допомогою «$@spellname389446»." },
    { en = "Pyroblast and Flamestrike have no cast time, are guaranteed to critically strike, and increase the damage of Pyroblast and Flamestrike by $1242220s1%.", ua = "Піровибух і Вогняний Удар не мають часу прочитання, гарантовано завдають критичного удару та підвищують шкоду Піровибуху і Вогняного Удару на $1242220s1%." },
    { en = "Recently affected by $@spellname377222.\n\nDamage taken by $@spellname377222 increased by $s1%.", ua = "Нещодавно під дією $@spellname377222.\n\nШкода від $@spellname377222 збільшена на $s1%." },
    { en = "Your bond with the blaze grows stronger. Strength increased by $w1.", ua = "Твій зв'язок із полум'ям міцнішає. Силу збільшено на $w1." },
    { en = "Healing for $w1 every $t1. Armor increased by $w2.", ua = "Зцілює $w1 здоров'я кожні $t1 с. Броню збільшено на $w2." },
    { en = "Increases the remaining stock of fish by $s0.", ua = "Збільшує залишковий запас риби на $s0." },
