    { en = "Inflicts $s1 Arcane damage every $t1 sec.\n\nReduces movement speed by $s2%.\n\nReduces haste by $s3%.", ua = "Завдає $s1 арканної шкоди кожні $t1 с.\n\nЗнижує швидкість пересування на $s2%.\n\nЗнижує Поспіх на $s3%." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nMaximum health reduced by $s2%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nМаксимальне здоров'я знижено на $s2%." },
    { en = "Stunned!\n$403202s1 Arcane damage inflicted every $t2 sec.", ua = "Приголомшено!\nЗавдає $403202s1 арканної шкоди кожні $t2 с." },
    { en = "$401952s1 Shadow damage inflicted every $s2 sec.\n\nUpon reaching $s1 applications, become lost in the $@spellname401215.", ua = "Завдає $401952s1 шкоди від тіні кожні $s2 с.\n\nПісля досягнення $s1 накладань на тебе накладається «$@spellname401215»." },
    { en = "$402053s1 Fire damage inflicted every $t1 sec.", ua = "Завдає $402053s1 шкоди вогнем кожні $t1 с." },
