    { en = "You have created a hologram of Ysera.", ua = "Ти створив голограму Ісери." },
    { en = "Inflicting $s1 Volcanic damage every $t1 sec.", ua = "Завдає $s1 вулканічної шкоди кожні $t1 с." },
    { en = "Exposing Temporal Wounds on enemies in your path. Immune to crowd control.", ua = "Відкриває «Часові рани» на ворогах на твоєму шляху. Імунітет до ефектів контролю." },
    { en = "$?(s403696)[Burning for $w2 damage every $t2 sec and movement speed reduced by $s1%.] [Movement speed reduced by $s1%.]", ua = "$?(s403696)[Горить, отримуючи $w2 шкоди кожні $t2 с; швидкість пересування знижена на $s1%.] [Швидкість пересування знижена на $s1%.]" },
    { en = "You have created a hologram of Alexstrasza.", ua = "Ти створив голограму Алекстрази." },
