    { en = "$405672s1 Arcane damage every $403910T1 sec.\nDamage taken reduced by $403910s2%.", ua = "$405672s1 арканної шкоди кожні $403910T1 с.\nОтримувана шкода знижена на $403910s2%." },
    { en = "$405671s1 Arcane damage every $403912T1 sec.\nMovement speed increased by $403912s2%.", ua = "$405671s1 арканної шкоди кожні $403912T1 с.\nШвидкість пересування збільшена на $403912s2%." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec.", ua = "Завдає $s1 шкоди тіньовим полум'ям кожні $t1 с." },
    { en = "$405478s2 Arcane damage every $?a403910[${$404141T1*$404141s1}.1][$404141T1] sec.\nReleases |5 $@spellname405448 upon removal.", ua = "$405478s2 арканної шкоди кожні $?a403910[${$404141T1*$404141s1}.1][$404141T1] с.\nПісля зняття вивільняє |5 $@spellname405448." },
    { en = "When skyriding near the ground, your Skyriding Charges recharge faster.", ua = "Під час небесного польоту біля землі ваші заряди небесного польоту відновлюються швидше." },
    { en = "Triggers a $@spellname404154 upon expiration unless within the $@spellname401215.", ua = "Після завершення спричиняє $@spellname404154, якщо не перебувати в межах $@spellname401215." },
    { en = "Ground Skimming regenerates $s1 Vigor every $s2 sec.", ua = "«Ковзання над землею» відновлює $s1 завзяття кожні $s2 сек." },
    { en = "Damage done increased by $s2%.\nMovement speed increased by $s1%.\n\nAt $s3 stacks, the caster becomes immune to crowd controlling and interrupting effects.", ua = "Завдавана шкода збільшена на $s2%.\nШвидкість пересування збільшена на $s1%.\n\nЗа $s3 зарядів той, хто творить закляття, стає несприйнятливим до ефектів контролю та переривання." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\n\nUpon removal, inflicts $404300s1 Shadow damage to all players and knocks them away.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\n\nПісля зняття завдає $404300s1 шкоди від тіні всім гравцям і відкидає їх." },
    { en = "Skyriding is currently enabled. In areas where you can fly, Skyriding abilities will be active.", ua = "Небесну їзду ввімкнено. Там, де можна літати, діятимуть здібності небесної їзди." },
    { en = "Damage taken from $@spellname410535 increased by $s1%.", ua = "Шкода від «$@spellname410535» збільшена на $s1%." },
    { en = "Surging forward in time, causing your cooldowns to recover $s1% faster.", ua = "Ти рвешся вперед у часі, і твої перезарядження відновлюються на $s1% швидше." },
    { en = "Cauterizing the wound, dealing ${$w1*($d/($t1))}  Fire damage over $d.", ua = "Припікає рану, завдаючи ${$w1*($d/($t1))} шкоди вогнем протягом $d." },
    { en = "Increases $@spellname404448's damage done by $s1%.", ua = "Збільшує шкоду, завдавану $@spellname404448, на $s1%." },
    { en = "Inflicts $406172s1 Shadowflame damage to all players every $t2 sec. Immune to the Elder's Conduit.", ua = "Завдає $406172s1 шкоди тіньовим полум'ям усім гравцям кожні $t2 с. Несприйнятливий до «Каналу Старійшини»." },
    { en = "Suffering $s1 Spellfrost damage every $t1 sec.", ua = "Зазнає $s1 шкоди чарокригою кожні $t1 с." },
    { en = "Inflicting $s1 Shadowflame damage every $t1 sec and reducing max health by $s2%. This effect stacks.", ua = "Завдає $s1 шкоди тіньовим полум'ям кожні $t1 с. і зменшує максимальне здоров'я на $s2%. Цей ефект накопичується." },
    { en = "$404650s2 Arcane damage every $404650T2 sec.", ua = "$404650s2 арканної шкоди кожні $404650T2 с." },
    { en = "$405448s1 Arcane damage every half-second.", ua = "$405448s1 арканної шкоди кожні півсекунди." },
    { en = "Inflicts $s1 Fire damage every $t1 sec.\n\nThis effect stacks.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с.\n\nЦей ефект накопичується." },
    { en = "Allows you to deactivate an active Dragonfire Trap.", ua = "Дозволяє тобі знешкодити активну пастку драконячого вогню." },
    { en = "Helps put out fire.", ua = "Допомагає гасити вогонь." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec. $?diff16[Upon removal, triggers a $@spellname405828.][]", ua = "Завдає $s1 шкоди тіньовим полум'ям кожні $t1 с. $?diff16[Після зняття спричиняє $@spellname405828.][]" },
    { en = "Ephemeral black dragon wings remain after your Seething Descent.", ua = "Після твого «Несамовитого Пікірування» залишаються ефемерні крила чорного дракона." },
    { en = "Inflicts $s1 Shadowflame damage to all players every $405316t2 sec. Immune to the Elder's Conduit.", ua = "Завдає $s1 шкоди тіньовим полум'ям усім гравцям кожні $405316t2 с. Несприйнятливий до «Каналу Старійшини»." },
    { en = "Melee attacks cause the target to suffer additional Arcane damage over time.", ua = "Атаки ближнього бою змушують ціль зазнавати додаткової арканної шкоди з часом." },
    { en = "$406313s1 Arcane damage inflicted every $406313t1 sec.\n\nColliding with another player with $@spellname406311 causes an $@spellname407302.", ua = "Завдає $406313s1 арканної шкоди кожні $406313t1 с.\n\nЗіткнення з іншим гравцем під дією $@spellname406311 спричиняє $@spellname407302." },
    { en = "Bleeding $s2 Physical damage every $t2 sec.", ua = "Кровотеча: $s2 фізичної шкоди кожні $t2 с." },
    { en = "Haste and movement speed increased by $M2%. This effect stacks up to $U times.", ua = "Поспіх і швидкість пересування збільшено на $M2%. Цей ефект накопичується до $U разів." },
    { en = "Radiating $405618s1 Fire damage to all players every $t1 sec.", ua = "Випромінює $405618s1 вогняної шкоди всім гравцям кожні $t1 с." },
    { en = "Able to cast spells while moving and spell range increased by $s4%.", ua = "Можеш творити закляття на ходу, а дальність заклять збільшена на $s4%." },
    { en = "Losing $m1% of your maximum health per second. Why?", ua = "Втрачаєш $m1% максимального здоров'я щосекунди. Навіщо?" },
    { en = "Spreads toxic ooze that drains this creature's energy.\n\nAt 0 energy, re-energizes with $@spellname407159.", ua = "Поширює токсичний слиз, що висмоктує енергію цієї істоти.\n\nЗа 0 енергії відновлює її за допомогою $@spellname407159." },
    { en = "Bleeding for $s2 Physical damage every $T2 sec.", ua = "Кровотеча завдає $s2 фізичної шкоди кожні $T2 с." },
