    { en = "Increases damage taken from $@spellname407547 by $w2%.", ua = "Збільшує отримувану шкоду від $@spellname407547 на $w2%." },
    { en = "Increases damage taken from $@spellname407597 by $s2%.", ua = "Збільшує отримувану шкоду від $@spellname407597 на $s2%." },
    { en = "Gaining $407795s1% energy and inflicting $407911s1 Fire damage to all players every $t2 sec.", ua = "Отримує $407795s1% енергії та завдає $407911s1 вогняної шкоди всім гравцям кожні $t2 с." },
