    { en = "$s1 Shadow damage taken every $t1 sec.\n\nDamage from $@spellname407917 reduced by $s3%.", ua = "Отримуєш $s1 шкоди від тіні кожні $t1 с.\n\nШкода від $@spellname407917 знижена на $s3%." },
    { en = "Increases damage taken from $@spellname404448 by $s1%.", ua = "Збільшує отримувану шкоду від $@spellname404448 на $s1%." },
    { en = "Tranformed into an adult and gained improved speed.", ua = "Перетворено на дорослу особину; швидкість підвищено." },
    { en = "$?j1g[Increases ground speed by $j1g%. ][]$?j1f[Increases flight speed by $j1f%. ][]$?j1s[Increases swim speed by $369869w2%. ][]", ua = "$?j1g[Збільшує швидкість руху по землі на $j1g%. ][]$?j1f[Збільшує швидкість польоту на $j1f%. ][]$?j1s[Збільшує швидкість плавання на $369869w2%. ][]" },
