    { en = "Burrowed underground. \n\nCannot be attacked.", ua = "Зарився під землю.\n\nНе можна атакувати." },
    { en = "Inflicting $s1 Shadow damage every $t1 sec. \n\nShadow damage taken increased by $s2%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с. \n\nОтримувана шкода від тіні збільшена на $s2%." },
    { en = "Inflicting $s1 Fire damage every $t1 sec. \n\nFire damage taken increased by $s2%.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с. \n\nОтримувана шкода вогнем збільшена на $s2%." },
    { en = "Accumulating $w1% damage from $@auracaster's allies who are affected by Ebon Might.", ua = "Накопичує $w1% шкоди від союзників $@auracaster, на яких діє «Ебенова міць»." },
    { en = "Your Technoscryers are tuned to discover nearby relics.", ua = "Твої Технопровидці налаштовані на пошук реліквій поблизу." },
    { en = "Iridikron builds energy as his foes attack him.\n\nAt 100 energy, he unleashes $@spellname414184.", ua = "Іридикрон накопичує енергію, коли вороги атакують його.\n\nПри 100 од. енергії він вивільняє $@spellname414184." },
    { en = "Damage done increased by $s1%.  \n\nIncreases every $408788t1 sec.", ua = "Завдавана шкода збільшена на $s1%.  \n\nЗростає кожні $408788t1 с." },
    { en = "Damage taken from $@spellname409942 increased by $s2%.", ua = "Шкода від «$@spellname409942» збільшена на $s2%." },
    { en = "$w1 healing absorbed.", ua = "Поглинає $w1 зцілення." },
    { en = "$410238s1 Physical damage every $410236T1 sec.", ua = "$410238s1 фізичної шкоди кожні $410236T1 с." },
    { en = "Bearing a Weyrnstone. $@auracaster holds the other.", ua = "Несе вейрнкамінь. Інший у $@auracaster." },
    { en = "Healing effects received reduced by $410497s1%.", ua = "Отримувані ефекти зцілення зменшено на $410497s1%." },
    { en = "Increases damage taken from $@spellname410608 by $s1%.", ua = "Збільшує отримувану шкоду від $@spellname410608 на $s1%." },
    { en = "The cast time of your next Healing Surge or Chain Heal is reduced by $w1% and its healing is increased by $w2%.", ua = "Час творення твого наступного «Цілющого сплеску» або «Ланцюгового зцілення» скорочено на $w1%, а його зцілення збільшено на $w2%." },
    { en = "Infinity Nova damage taken increased by $410908s2%.", ua = "Отримувана шкода від «Нови нескінченності» збільшена на $410908s2%." },
    { en = "Hostile to all other players.\n\nAble to attack enemies $@spellname407036.", ua = "Ворожість до всіх інших гравців.\n\nМожеш атакувати ворогів з ефектом $@spellname407036." },
    { en = "Ripped from another timeline, reducing initial health to $w1% of total.", ua = "Вирвано з іншої часової лінії: початкове здоров'я зменшене до $w1% від максимуму." },
    { en = "$s1 Arcane damage every $T1 sec.", ua = "$s1 арканної шкоди кожні $T1 с." },
    { en = "Threat generation reduced by $w1%. Cast by $@auracaster.", ua = "Створення загрози зменшено на $w1%. Накладено: $@auracaster." },
    { en = "Inflicting $412769s1 Arcane damage to enemies within $412769A1 yards every $t1 sec.", ua = "Завдає $412769s1 арканної шкоди ворогам у радіусі $412769A1 м кожні $t1 с." },
    { en = "Absorbs $w2 healing received.$?diff8|diff23[\n\nPrevents dispels.][]", ua = "Поглинає $w2 отримуваного зцілення.$?diff8|diff23[\n\nНе можна розвіяти.][]" },
    { en = "Increases damage taken by $s1%.\n\nCannot be dispelled if afflicted by $@spellname413013.", ua = "Збільшує отримувану шкоду на $s1%.\n\nНе можна розвіяти, якщо на цілі діє $@spellname413013." },
    { en = "$s1 Physical damage inflicted every $t1 sec.\nMovement speed reduced by $s2%.", ua = "Завдає $s1 фізичної шкоди кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "$s1 Frost damage inflicted every $t1 sec.\n$s2% reduced damage and healing.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с.\nШкода та зцілення знижені на $s2%." },
    { en = "$s1 Nature damage every $t1 sec.\nUnable to attack or cast spells.", ua = "$s1 шкоди від сил природи кожні $t1 с.\nНе можеш атакувати чи творити закляття." },
    { en = "100% of the damage done to Dazhak  also occurs to Loszkeleth.", ua = "100% шкоди, завданої Дажаку, також отримує Лозкелет." },
    { en = "Each of Iridikron's successful melee attacks causes his target to take $409558s1% increased Physical damage for $409558d.\n\nThis effect stacks.", ua = "Кожна успішна атака ближнього бою Іридикрона змушує його ціль отримувати на $409558s1% більше фізичної шкоди протягом $409558d.\n\nЦей ефект накопичується." },
    { en = "A fissure of Shadowflame will soon erupt from your location.", ua = "Невдовзі там, де ти стоїш, вирветься розколина тіньового полум'я." },
    { en = "Your next Holy Light is instant cast and has a $w2% reduced mana cost.", ua = "Твоє наступне «Святе світло» твориться миттєво й коштує на $w2% менше мани." },
    { en = "Generating a time distortion bubble that grants players their future maximum potential.", ua = "Створює бульбашку викривлення часу, що дарує гравцям їхній майбутній максимальний потенціал." },
    { en = "Chromie reduces damage to players within her time bubble by $414333s1%.\n\nWhen $@spellname414330 ends, Chromie is $@spellname414353.", ua = "Хромі знижує шкоду гравцям усередині своєї часової бульбашки на $414333s1%.\n\nКоли $@spellname414330 завершується, Хромі отримує $@spellname414353." },
    { en = "Damage taken increased by $s1%.\n\nRemoved if protected from $@spellname414535.", ua = "Отримувана шкода збільшена на $s1%.\n\nЗнімається, якщо є захист від «$@spellname414535»." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec.\n$?diff15|diff16 [When applied, inflicts $@spellname419462.][]", ua = "Завдає $s1 шкоди тіньовим полум'ям кожні $t1 с.\n$?diff15|diff16 [При накладанні спричиняє $@spellname419462.][]" },
    { en = "Damage taken reduced by $s8%.", ua = "Отримувана шкода зменшена на $s8%." },
    { en = "Limited uses of a large orb of magical water. Throw part of it off to extinguish nearby fires.", ua = "Обмежена кількість використань великої сфери чарівної води. Хлюпни частиною води, щоб загасити вогонь поблизу." },
    { en = "Incoming damage reduced by $s1%.\n\nAttempting to inhabit a viable host.", ua = "Отримувана шкода зменшена на $s1%.\n\nНамагається оселитися в придатному носії." },
    { en = "The next time rift you complete is guaranteed to grant you a reward.", ua = "Наступний часовий розлом, який ти завершиш, гарантовано дасть тобі нагороду." },
    { en = "Investigate the area, and tell Kaiana to absorb the nearby information.", ua = "Досліди місцевість і скажи Каяні увібрати навколишню інформацію." },
    { en = "$416139s2 Arcane damage every $416139T2 sec.", ua = "$416139s2 арканної шкоди кожні $416139T2 с." },
    { en = "$417026s1 Frost damage every $417026T1 sec.", ua = "$417026s1 шкоди від морозу кожні $417026T1 с." },
    { en = "$417630s1 Shadowflame damage inflicted each time Fyrakk melee attacks.", ua = "Завдає $417630s1 шкоди тіньовим полум'ям щоразу, коли Фіракк атакує в ближньому бою." },
    { en = "Targets random players with $@spellname413590 and $@spellname408141.", ua = "Обирає ціллю випадкових гравців ($@spellname413590 та $@spellname408141)." },
    { en = "Inflicting $417585s1 Fire damage every $t1 sec to all enemies and creating $@spellname417632.", ua = "Завдає $417585s1 шкоди вогнем кожні $t1 с. усім ворогам і створює $@spellname417632." },
    { en = "Fiery Treants seek to spread flame throughout the temple and leave behind $@spellname417610.\n\nWhen killed, they transform into a $@spellname417667.", ua = "Вогняні тренти прагнуть поширити полум'я по всьому храму й лишають по собі «$@spellname417610».\n\nПісля смерті вони перетворюються на «$@spellname417667»." },
    { en = "Charred Treants are inert and can be healed by players.\n\nUpon reaching full health, they transform into a $@spellname417668.", ua = "Обвуглені тренти бездіяльні, і гравці можуть їх зцілювати.\n\nДосягнувши повного здоров'я, вони перетворюються на $@spellname417668." },
    { en = "Friendly Renewed Treants channel $@spellname424997, sacrificing their own life to empower the Seed of Life.", ua = "Дружні Відновлені тренти творять $@spellname424997, жертвуючи власним життям, щоб підсилити Насінину Життя." },
    { en = "The spirit of cooperation binds a fallen delver and their avenger together, granting both $s1% increased movement speed and reducing damage they take by $s2%.", ua = "Дух співпраці поєднує полеглого дослідника глибин та його месника, підвищуючи їм обом швидкість пересування на $s1% і зменшуючи отриману ними шкоду на $s2%." },
    { en = "Inflicts $418978s1 Shadowflame damage to all players every $t1 sec.", ua = "Завдає $418978s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 с." },
    { en = "Recording $w1% of all healing done.", ua = "Записує $w1% усього твого зцілення." },
    { en = "Charmed.\n\nOccurs if $@spellname407406 afflicts a player for its full duration.", ua = "Зачаровано.\n\nСтається, якщо $@spellname407406 діє на гравця всю свою тривалість." },
    { en = "Fighting alongside yourself, granting $w1 $?e1[Critical Strike]?e2[Haste]?e3[Versatiliy]?e4[Mastery][Highest secondary stat].", ua = "Б'єшся пліч-о-пліч із собою, отримуючи $w1 $?e1[критичного удару]?e2[поспіху]?e3[універсальності]?e4[майстерності][найвищої другорядної характеристики]." },
    { en = "Renewed Bramble Barriers provide protection against $@spellname417634.\n\nWhen destroyed, they erupt in $@spellname418535.", ua = "Відновлені Тернові Бар'єри захищають від $@spellname417634.\n\nПри знищенні вони вибухають $@spellname418535." },
    { en = "Scorching Roots fixate on random players, pursuing them relentlessly and speed over time.\n\nWhen killed, they transform into Charred Brambles. $?diff15|diff16 [\n\nScorched Roots remain untargetable until doused with $@spellname425249.][]", ua = "«Палюче Коріння» зосереджується на випадкових гравцях, невпинно переслідує їх і з часом пришвидшується.\n\nПісля загибелі перетворюється на «Обвуглені Терни». $?diff15|diff16 [\n\n«Палюче Коріння» не можна обрати ціллю, доки його не полито $@spellname425249.][]" },
    { en = "Charred Brambles are inert and can be healed by players.\n\nUpon reaching full health, they transform into a $@spellname418653.", ua = "Обвуглені Терни бездіяльні, і гравці можуть їх зцілювати.\n\nДосягнувши повного здоров'я, вони перетворюються на $@spellname418653." },
    { en = "Scorching Brambles emerge from the ground, becoming targetable.", ua = "«Пекучі терни» виходять із землі, і їх можна обрати ціллю." },
    { en = "Investigate the area, and tell your familiar to absorb the nearby information.", ua = "Досліди місцевість і скажи своєму фамільярові увібрати навколишню інформацію." },
    { en = "Transformed into a duck!\n\nUpon removal, transforms other players within $418740A1 yards into ducks.", ua = "Перетворено на качку!\n\nПісля зняття перетворює інших гравців у межах $418740A1 м на качок." },
    { en = "Increases damage done, healing done, and movement speed by $s1% for each player within 5 yds.", ua = "Збільшує завдавану шкоду, зцілення та швидкість пересування на $s1% за кожного гравця в межах 5 м." },
    { en = "Inflicting $419056s1 Fire damage every $t1 sec.\nDamage taken from $@spellname423117 increased by $s2%.", ua = "Завдає $419056s1 шкоди вогнем кожні $t1 с.\nОтримувана шкода від $@spellname423117 збільшена на $s2%." },
    { en = "Experience earned increased by $s1%.", ua = "Отримуваний досвід збільшений на $s1%." },
    { en = "Reduces damage taken from $@spellname417634 by $M1%.", ua = "Знижує отримувану шкоду від $@spellname417634 на $M1%." },
    { en = "Upon killing an enemy, Grommash gains Thirst for Battle. Melee attacks consume these stacks inflicting $419604s1 Nature damage to all players.", ua = "Убивши ворога, Ґроммаш отримує «Спрагу битви». Атаки ближнього бою витрачають ці заряди, завдаючи $419604s1 шкоди від сил природи всім гравцям." },
    { en = "Upon defeating an enemy, Lothar gains Battle Senses. Melee attacks consume these stacks inflicting $419616s1 Nature damage to all players.", ua = "Здолавши ворога, Лотар отримує «Бойові чуття». Атаки ближнього бою витрачають ці заряди, завдаючи $419616s1 шкоди від сил природи всім гравцям." },
    { en = "Absorb $w1 incoming damage.", ua = "Поглинає $w1 вхідної шкоди." },
    { en = "Targeted for Darkflame!", ua = "Обрано ціллю: «Темнопломінь»!" },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\nUpon removal  inflicts $424195s1 Nature damage to all players in line of sight.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nПісля зняття завдає $424195s1 шкоди від сил природи всім гравцям у полі зору." },
    { en = "Inflicting $420911s1 Nature damage to players every $420907t1 sec.", ua = "Завдає $420911s1 шкоди від сил природи гравцям кожні $420907t1 с." },
    { en = "Damage taken decreased by $s1%. Pulsing $@spellname421421 every $422370t1 sec.\n$?diff14 [Emitting $@spellname426617 every $426623t1 sec.][]$?diff15|diff16 [Emitting $@spellname421350 every $422366t1 sec.][]", ua = "Отримувана шкода зменшена на $s1%. Пульсує «$@spellname421421» кожні $422370t1 с.\n$?diff14 [Випромінює «$@spellname426617» кожні $426623t1 с.][]$?diff15|diff16 [Випромінює «$@spellname421350» кожні $422366t1 с.][]" },
    { en = "$423488s1 Nature damage inflicted every $t2 sec. \nStunned.", ua = "Завдає $423488s1 шкоди від сил природи кожні $t2 с. \nПриголомшено." },
    { en = "Inflicting $425002s1 Shadowflame damage every $425002t1 sec.", ua = "Завдає $425002s1 шкоди тіньовим полум'ям кожні $425002t1 с." },
    { en = "Walking through dreams.", ua = "Мандрує снами." },
    { en = "Inflicts $s3 Nature damage every $t3 sec for $d. \n\nMovement speed reduced by $s2%. \n\nJumping reduces stacks of $@spellname421260.", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с. протягом $d. \n\nШвидкість пересування знижена на $s2%. \n\nСтрибки зменшують кількість зарядів $@spellname421260." },
    { en = "Sleeping. Damage taken increased by $s2%\n\nTaking damage removes this effect.", ua = "Спить. Отримувана шкода збільшена на $s2%\n\nОтримання шкоди знімає цей ефект." },
    { en = "Inflicting $421315s1 Fire damage ever $t1 sec. to all players, pulling players towards him.\n\nTransforming into the Avatar of Ash.", ua = "Завдає $421315s1 шкоди вогнем кожні $t1 с. усім гравцям, притягуючи їх до себе.\n\nПеретворюється на Втілення Попелу." },
    { en = "Suffering $421324s1 Fire damage every $421407t1 sec. This effect stacks.", ua = "Зазнає $421324s1 вогняної шкоди кожні $421407t1 с. Цей ефект накопичується." },
    { en = "Healing effects received reduced by $s1% and suffering $423787s1 Fire damage every $t2 sec.\n\nLeeching $423807s1 health from all allies within $423807A yards every $t2 sec.", ua = "Отримувані ефекти зцілення зменшено на $s1%, і ти зазнаєш $423787s1 вогняної шкоди кожні $t2 с.\n\nВисмоктуєш $423807s1 здоров'я з усіх союзників у межах $423807A м кожні $t2 с." },
    { en = "Absorbing $427299M1 healing. Upon expiring, inflicts $421467s1 Fire damage to players within $421463a1 yards.\n\nIf the absorb is not healed before expiring, also applies $@spellname421463 to players hit.", ua = "Поглинає $427299M1 зцілення. Після завершення завдає $421467s1 шкоди вогнем гравцям у радіусі $421463a1 м.\n\nЯкщо поглинання не зцілено до завершення, також накладає $@spellname421463 на уражених гравців." },
    { en = "Damage taken from $@spellname421368 increased by $s2%.", ua = "Шкода від «$@spellname421368» збільшена на $s2%." },
    { en = "Absorbing $w3 damage.", ua = "Поглинає $w3 шкоди." },
    { en = "$421515s1 Fire damage every $t1 sec. $?diff17|diff14[ ][\n\nCreates $@spellname421969 upon expiring.]", ua = "$421515s1 шкоди вогнем кожні $t1 с. $?diff17|diff14[ ][\n\nПісля завершення створює $@spellname421969.]" },
    { en = "Absorbing $s1 healing and stunned. Releases a $@spellname421469 when removed.", ua = "Поглинає $s1 зцілення; приголомшено. Після зняття вивільняє $@spellname421469." },
    { en = "Tindral shapeshifts into a flaming owl, allowing him to fly towards different platform.", ua = "Тіндрал перетворюється на палаючу сову, що дозволяє йому перелітати на інші платформи." },
    { en = "You've been branded by Emberscar. Damage taken from $@spellname421643 increased by $s1%.", ua = "Тебе затаврував Емберскар. Отримувана шкода від $@spellname421643 збільшена на $s1%." },
    { en = "Absorbing $w1 healing.\n\nCauses a $@spellname424233 when removed.", ua = "Поглинає $w1 зцілення.\n\nПісля зняття спричиняє $@spellname424233." },
    { en = "Inflicting $421674s1 Fire damage to all players every $t1 sec.", ua = "Завдає $421674s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "Targeted for a $@spellname421817!", ua = "Обрано ціллю: $@spellname421817!" },
    { en = "$s1% increased damage done.\n$s2% increased healing and absorptions done.", ua = "Завдана шкода збільшена на $s1%.\nЗцілення та поглинання збільшені на $s2%." },
    { en = "Increased flying speed.", ua = "Швидкість польоту збільшено." },
    { en = "Applying a stack of $@spellname421323 to players every $421323t1 sec.\n\n$@spellicon421323 $@spellname421323:\n$@spelldesc421323", ua = "Накладає заряд $@spellname421323 на гравців кожні $421323t1 с.\n\n$@spellicon421323 $@spellname421323:\n$@spelldesc421323" },
    { en = "Counterattacking all incoming damage from enemies within $421996r yards. Regenerating $w1 every $t sec.", ua = "Контратакує у відповідь на всю вхідну шкоду від ворогів у радіусі $421996r м. Відновлює $w1 кожні $t с." },
    { en = "$@spellname420950 occurs every $s1 sec$?diff17|diff14[. ][ and damage increased by $s3%.]\n\nChanneling molten energies into Emberscar.", ua = "$@spellname420950 відбувається кожні $s1 с$?diff17|diff14[. ][, а шкода збільшена на $s3%.]\n\nСпрямовує розплавлені енергії в Емберскар." },
    { en = "$s1% increased Physical damage taken", ua = "Отримувана фізична шкода збільшена на $s1%" },
    { en = "Able to dragonride within The Blessed Boughs.", ua = "Можна літати на драконі в межах Благословенних Гілок." },
    { en = "After $422297s3 sec, the blade ignites with Shadowflame and returns to you, dealing $422297w2 Shadowflame damage split between the target and all enemies in its path.", ua = "Через $422297s3 с клинок спалахує тіньовим полум'ям і повертається до тебе, завдаючи $422297w2 шкоди тіньовим полум'ям, розподіленої між ціллю та всіма ворогами на його шляху." },
    { en = "Melee abilities sever a root, dealing $422440w1 additional Shadowflame damage split between nearby enemies.\n\nSlowed by $w2%.", ua = "Здібності ближнього бою перерубують корінь, завдаючи $422440w1 додаткової шкоди тіньовим полум'ям, розділеної між ворогами поблизу.\n\nСповільнено на $w2%." },
    { en = "Inflicting $422523s1 Shadowflame damage to enemies within $422523a1 yards every $t1 sec.", ua = "Завдає $422523s1 шкоди тіньовим полум'ям ворогам у радіусі $422523a1 м кожні $t1 с." },
    { en = "Light being stolen!", ua = "Світло викрадають!" },
    { en = "Inflicts up to $422578s1 Fire damage to all players upon expiration.", ua = "Після завершення дії завдає до $422578s1 шкоди вогнем усім гравцям." },
    { en = "Applies $@spellname443694 on hit.\n\n$@spellicon443694$@spellname443694:\n$@spelldesc443694", ua = "При влучанні накладає $@spellname443694.\n\n$@spellicon443694$@spellname443694:\n$@spelldesc443694" },
    { en = "Suffering $422652w2 Shadowflame damage and targeting a nearby enemy with $@spellname425701 every $t1 sec.", ua = "Зазнає $422652w2 шкоди тіньовим полум'ям і кожні $t1 с обирає ворога поблизу ціллю для $@spellname425701." },
    { en = "Inflicts $423705s1 Shadowflame damage to all players every $t1 sec.", ua = "Завдає $423705s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 с." },
    { en = "Suffering $422953w1 Nature damage over $d.", ua = "Зазнає $422953w1 шкоди від сил природи протягом $d." },
    { en = "Physical damage inflicted increased by $s1%.\nEmpowers spells.", ua = "Завдана фізична шкода збільшена на $s1%.\nПідсилює закляття." },
    { en = "Inflicts $s2 Holy damage every $t2 seconds", ua = "Завдає $s2 священної шкоди кожні $t2 с" },
    { en = "Damage taken from $@spellname418423 prevented.\nMovement speed increased by $s2%.", ua = "Шкода від «$@spellname418423» відвернена.\nШвидкість пересування збільшена на $s2%." },
    { en = "Inflicts $423266s1 Fire damage to players every $t1 sec.", ua = "Завдає $423266s1 шкоди вогнем гравцям кожні $t1 с." },
    { en = "Inflicting $423327s1 Shadow damage every $t1 sec.", ua = "Завдає $423327s1 шкоди від тіні кожні $t1 с." },
    { en = "Falling speed slowed.", ua = "Швидкість падіння сповільнена." },
    { en = "Damage done to $@spellname423228 increased by $438583s1%\nHealing done increased by $438583s2%. \nTaking $464980s1 Shadow damage every $435813t1 sec.", ua = "Шкода по «$@spellname423228» збільшена на $438583s1%\nЗцілення збільшене на $438583s2%. \n$464980s1 тіньової шкоди кожні $435813t1 с." },
    { en = "Absorbs $w1 damage.\nImmune to interrupt effects.", ua = "Поглинає $w1 шкоди.\nНесприйнятливий до ефектів переривання." },
    { en = "Holding a $@spellname423601.", ua = "Тримаєш $@spellname423601." },
    { en = "Holy damage increased by $s2%.\n\nThis effect stacks.", ua = "Святу шкоду збільшено на $s2%.\n\nЦей ефект накопичується." },
    { en = "You've got a festive friend!", ua = "У тебе є святковий друг!" },
    { en = "Absorbs the next $w1 incoming damage.", ua = "Поглинає наступні $w1 вхідної шкоди." },
    { en = "Physical damage taken increased by $s1%. This effect decreases in stacks over time.", ua = "Отримувана фізична шкода збільшена на $s1%. Кількість зарядів цього ефекту з часом зменшується." },
    { en = "$@spellname423842 damage taken increased by $s2%.", ua = "Шкода від $@spellname423842 збільшена на $s2%." },
    { en = "Absorb the next $w2 damage.\n\nInflicting $429162s1 Fire damage every $t1 sec.\n\nInflicts $429164s1 damage after $d.", ua = "Поглинає наступні $w2 шкоди.\n\nЗавдає $429162s1 шкоди вогнем кожні $t1 с.\n\nЧерез $d завдає $429164s1 шкоди." },
    { en = "Increased damage done by $s1%.\nIncreased healing and absorb effects done by $s4%.", ua = "Завдавану шкоду збільшено на $s1%.\nЗдійснювані зцілення та ефекти поглинання збільшено на $s4%." },
    { en = "Bleeding for $s2 Physical damage every $t2 sec.\n\nThis effect stacks.", ua = "Кровотеча: $s2 фізичної шкоди кожні $t2 с.\n\nЦей ефект накопичується." },
    { en = "Inflicts $424430s1 Holy damage every $424430t1 sec.", ua = "Завдає $424430s1 священної шкоди кожні $424430t1 с." },
