    { en = "Inflicts $427339s1 Fire damage every $t1 sec.$?diff17[]\n$?diff14|diff16|diff15[\nWhen removed, leaves behind $@spellname424499]$?diff14|diff15[.]$?diff16[and afflicts all players with $@spellname424582.]", ua = "Завдає $427339s1 шкоди вогнем кожні $t1 с.$?diff17[]\n$?diff14|diff16|diff15[\nПісля зняття лишає по собі $@spellname424499]$?diff14|diff15[.]$?diff16[ і вражає всіх гравців $@spellname424582.]" },
    { en = "Inflicts $w1 Fire damage every $t1 sec.\n\nEach stack of $@spellname424582 increases its damage by $s2%.", ua = "Завдає $w1 шкоди вогнем кожні $t1 с.\n\nКожен заряд $@spellname424582 збільшує цю шкоду на $s2%." },
    { en = "Roots the target in place for $d.", ua = "Прикорінює ціль на місці на $d." },
    { en = "$?j1g[Increases ground speed by $j1g%. ][]$?j1f[Increases flight speed by $j1f%. ][]$?j1s[Increases swim speed by $j1s%. ][] What a good boy!", ua = "$?j1g[Збільшує швидкість на землі на $j1g%. ][]$?j1f[Збільшує швидкість польоту на $j1f%. ][]$?j1s[Збільшує швидкість плавання на $j1s%. ][] Який хороший хлопчик!" },
    { en = "Damage done increased by $s1%.\nThis effect is increased for each nearby member of the Trusted Guard.", ua = "Завдавана шкода збільшена на $s1%.\nЦей ефект посилюється за кожного члена Довіреної Варти поблизу." },
