    { en = "Bonded with the Seed of Life, draining it of energy.\n\n$?diff14|diff17|diff15 [Dousing][]$?diff16 [The final player in the bond expels emerald magic, dousing][] $@spellname417632 and $@spellname418654.", ua = "Пов'язано з Сім'ям життя, що виснажує його енергію.\n\n$?diff14|diff17|diff15 [Гасить][]$?diff16 [Останній гравець у зв'язку вивільняє смарагдову магію, гасячи][] $@spellname417632 та $@spellname418654." },
    { en = "Unable to form a bond with the Seed of Life.", ua = "Не може утворити зв'язок із Насіниною Життя." },
    { en = "Inflicting $425575s1 Fire damage every $t1 sec.", ua = "Завдає $425575s1 шкоди вогнем кожні $t1 с." },
    { en = "Upon landing, inflict $s1 Fire damage to enemies within $a1 yards and dismounts the player.", ua = "Під час приземлення завдає $s1 вогняної шкоди ворогам у межах $a1 м і скидає гравця з їздової тварини." },
    { en = "Primary stat increased by $s1%.", ua = "Основна характеристика збільшена на $s1%." },
    { en = "Inflicting $425821s1 Fire damage to players within $425821A1 yards every $t1 sec.\nMovement speed reduced by $s2%.", ua = "Завдає $425821s1 шкоди вогнем гравцям у радіусі $425821A1 м кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Creating $@spellname417610. This effect is reduced when standing next to $@spellname417610.", ua = "Створює $@spellname417610. Цей ефект слабший, якщо стояти поруч із $@spellname417610." },
