    { en = "Damage taken by $@spellname429876 increased by $s1%.\n\nDamage taken by $@spellname429875 increased by $s2%.", ua = "Шкода від «$@spellname429876» збільшена на $s1%.\n\nШкода від «$@spellname429875» збільшена на $s2%." },
