    { en = "Damage taken increased by $s2%.\nDamage done reduced by $s1%.", ua = "Отримувана шкода збільшена на $s2%.\nЗавдавана шкода зменшена на $s1%." },
    { en = "Your physical damage taken is reduced by $w1% until you receive a physical attack.", ua = "Отримувана тобою фізична шкода зменшена на $w1%, доки ти не зазнаєш фізичної атаки." },
