    { en = "Haste increased by $w1%", ua = "Поспіх збільшено на $w1%" },
    { en = "Dealing damage consumes a charge dealing $433824w1 additional Frost damage and apply Wellspring's Frost.", ua = "Завдання шкоди витрачає заряд, завдаючи додатково $433824w1 морозної шкоди й накладаючи «Мороз Джерела»." },
    { en = "Damage taken by $@spellname432969 increased by $s2%.", ua = "Шкода від «$@spellname432969» збільшена на $s2%." },
