    { en = "$?$W1==$U[Ready to deliver Light's justice.][Building up Light's Deliverance. At $u stacks, your next Hammer of Light cast will activate another Hammer of Light for free.]", ua = "$?$W1==$U[Готово звершити правосуддя Світла.][Накопичує «Спасіння Світла». За $u зарядів твоє наступне прочитання «Молота Світла» безкоштовно активує ще один «Молот Світла».]" },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\n\nThe $@spellname433740 will form into a $@spellname433747 when this expires.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nПісля завершення дії $@spellname433740 перетвориться на $@spellname433747." },
    { en = "Damage reduced by $w3%, absorbing up to $w1 damage. Armor increased by $w2. Gain an additional $433000w4 armor when hit.", ua = "Шкода зменшена на $w3%, поглинає до $w1 шкоди. Броня збільшена на $w2. При влучанні додає ще $433000w4 броні." },
    { en = "$434113s1 Shadow damage every $434113T1 sec.\nPulled in by $@spellname434089.\nMoving $434113A2 yards snaps the tether!\nCauses $@spellname434119 when snapped.", ua = "$434113s1 шкоди від тіні кожні $434113T1 с.\nТебе притягує $@spellname434089.\nВідійди на $434113A2 м, щоб розірвати прив'язь!\nПісля розриву спричиняє $@spellname434119." },
    { en = "$434096s1 Shadow damage every $434096T1 sec.\nMovement speed reduced by $434096s2%.", ua = "$434096s1 шкоди від тіні кожні $434096T1 с.\nШвидкість пересування знижена на $434096s2%." },
    { en = "Apply pheromones to blend into the Umbral Bazaar.", ua = "Нанеси феромони, щоб злитися з Тіньовим Базаром." },
    { en = "$434441s2 Nature damage every $434441T2 sec.\nMovement speed reduced by $434441s3%.", ua = "$434441s2 шкоди від сил природи кожні $434441T2 с.\nШвидкість пересування знижена на $434441s3%." },
    { en = "Inflicting $435415s1 Shadow damage to all players every $t1 sec.", ua = "Завдає $435415s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "Ready to defend themselves!!", ua = "Готові захищатися!!" },
    { en = "$s1 Nature damage every $T1 sec.", ua = "$s1 шкоди від сил природи кожні $T1 с." },
    { en = "$434668s2 Fire damage every $434668T2 sec.\nCarrying an Arathi Bomb.", ua = "$434668s2 шкоди вогнем кожні $434668T2 с.\nНесеш аратійську бомбу." },
    { en = "$s1 Nature damage inflicted every $t1 sec. Movement speed reduced by $435466s1~%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с. Швидкість пересування знижена на $435466s1~%." },
    { en = "Inflicts $s2 Holy damage every $t2 sec.", ua = "Завдає $s2 священної шкоди кожні $t2 с." },
    { en = "Inflicting $435415s1 Shadow damage to all players every $435405t1 sec.", ua = "Завдає $435415s1 шкоди від тіні всім гравцям кожні $435405t1 с." },
    { en = "Absorbing up to $w2 damage from webbed attackers.", ua = "Поглинає до $w2 шкоди від обплутаних павутиною нападників." },
    { en = "Targeted for $@spellname435486.", ua = "Обрано ціллю: $@spellname435486." },
    { en = "Attempting to execute any player below $s1% health.", ua = "Намагається стратити будь-якого гравця, у якого менше $s1% здоров'я." },
    { en = "Inflicting $437342s1 Shadow damage every $t1 sec.\n\nUpon expiration, inflicts $437469s1 Shadow damage.", ua = "Завдає $437342s1 шкоди від тіні кожні $t1 с.\n\nПісля завершення дії завдає $437469s1 шкоди від тіні." },
    { en = "Damage from $@spellname438218 is increased by $s2%.", ua = "Шкода від «$@spellname438218» збільшена на $s2%." },
    { en = "Damage increased by $439333s1%.", ua = "Шкода збільшена на $439333s1%." },
    { en = "Feed Ulgrax.", ua = "Нагодуй Улґракса." },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\nAll damage taken increased by $s4%.\nRemoval triggers $@spellname449993 and transfers to nearest player or Skeinspinner Takazj.\n$s3 stacks trigger $@spellname456235.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nУся отримувана шкода збільшена на $s4%.\nЗняття спричиняє $@spellname449993 і переносить ефект на найближчого гравця або Прядильницю Таказж.\nНакопичення $s3 зарядів спричиняє $@spellname456235." },
    { en = "Increases damage taken by $s1%", ua = "Збільшує отримувану шкоду на $s1%" },
    { en = "$438957s1 Nature damage every $438957T1 sec.", ua = "$438957s1 шкоди від сил природи кожні $438957T1 с." },
    { en = "Bleeding $s1 Physical damage every $t1 sec.", ua = "Кровотеча: $s1 фізичної шкоди кожні $t1 с." },
    { en = "The Ravenous Cinderbee is docile and can be ridden by players.\n\nThe Cinderbee perishes upon expiration.", ua = "Ненажерлива попеляста бджола слухняна, і гравці можуть на ній їздити.\n\nПісля завершення ефекту бджола гине." },
    { en = "Absorbed latent arcane energy from an Irradiated herb. Allows you to magically duplicate the basic form of a nearby herb using Arcane Duplication.", ua = "Увібрано приховану арканну енергію опроміненої трави. Дозволяє тобі магічно відтворити базову форму трави поблизу за допомогою «Арканного роздвоєння»." },
    { en = "Duplicating a nearby herb.", ua = "Дублює траву поблизу." },
    { en = "Seeing Sporelusive Herbs! Find the correct herb to continue gathering more! Gather the wrong herb and become disoriented by magical spores.", ua = "Ти бачиш спороневловимі трави! Знайди правильну траву, щоб зібрати ще! Збереш не ту — чарівні спори дезорієнтують тебе." },
    { en = "Disoriented by magical spores for picking an incorrect Sporelusive herb.", ua = "Дезорієнтовано магічними спорами через зірвану неправильну спорову траву." },
    { en = "The Fangs of the Queen harness a synergistic power, causing them to share $s1% of all damage taken.", ua = "Ікла Королеви черпають синергічну силу, завдяки чому розподіляють між собою $s1% усієї отриманої шкоди." },
    { en = "$439776s1 Nature damage every $439776T1 sec.", ua = "$439776s1 шкоди від сил природи кожні $439776T1 с." },
    { en = "$439780s1 Nature damage every $439780T1 sec.\nMovement speed reduced by $439780s2%.", ua = "$439780s1 шкоди від сил природи кожні $439780T1 с.\nШвидкість пересування знижена на $439780s2%." },
    { en = "$456170s1 Nature damage every $456170T1 sec.\nStretching this tether $439779A1 yards snaps it, causing a $@spellname439778.", ua = "$456170s1 шкоди від сил природи кожні $456170T1 с.\nРозтягнення цієї прив'язі на $439779A1 м розриває її, спричиняючи $@spellname439778." },
    { en = "$439785s1 Nature damage every $439785T1 sec.", ua = "$439785s1 шкоди від сил природи кожні $439785T1 с." },
    { en = "Movement speed reduced by $439786s2%.", ua = "Швидкість пересування знижена на $439786s2%." },
    { en = "$440191s1 Nature damage every $439811T1 sec.", ua = "$440191s1 шкоди від сил природи кожні $439811T1 с." },
    { en = "You're targeted by $@spellname439815!", ua = "Тебе обрано ціллю: $@spellname439815!" },
    { en = "Utilizing keen botanical insight with latent magic to get more herbs from your next gather.", ua = "Гостре ботанічне чуття в поєднанні з прихованою магією дасть більше трав за наступний збір." },
    { en = "$464748s1 Physical damage inflicted every $t3 sec.\nMovement speed decreased by $s2%.", ua = "Завдає $464748s1 фізичної шкоди кожні $t3 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Coated in spicy honey. Will inflict $440138s1 Fire damage to players within $440138A1 yards of their location after $d.", ua = "Вкрито гострим медом. Через $d завдасть $440138s1 шкоди вогнем гравцям у радіусі $440138A1 м від місця перебування." },
    { en = "Stunned!\nAll damage taken is increased by $s3%.", ua = "Приголомшено!\nУся отримувана шкода збільшена на $s3%." },
    { en = "$440193s1 Nature damage every $440193T1 sec.", ua = "$440193s1 шкоди від сил природи кожні $440193T1 с." },
    { en = "Knocked back by an Irradiated herb!", ua = "Відкинуто опроміненою травою!" },
    { en = "Able to see camouflaged gathering nodes with the assistance of magical spores.", ua = "Завдяки магічним спорам можеш бачити замасковані джерела ресурсів." },
    { en = "The magical spores from the Sporefused herbs linger on your person, affecting your perception of the world around you.", ua = "Магічні спори спорозрощених трав лишаються на тобі, впливаючи на твоє сприйняття навколишнього світу." },
    { en = "Inflicting $440577s1 Shadow damage every $t1 sec.\nDamage taken from Void Shredder strikes increased by $s2%.", ua = "Завдає $440577s1 шкоди від тіні кожні $t1 с.\nОтримувана шкода від ударів «Шматувальників Порожнечі» збільшена на $s2%." },
    { en = "Inflicts $440608s1 Nature damage to all players every $t1 sec.", ua = "Завдає $440608s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "Utilizing expert skinning knowledge and processes to guarantee a hide or carapace from your next Algari skinning attempt.", ua = "Використовуєш фахові знання й прийоми білування, щоб гарантовано отримати шкуру або панцир із наступної алґарійської спроби білування." },
    { en = "Freezing to death. $s1 Frost damage inflicted every $t1 sec.", ua = "Замерзаєш на смерть. $s1 морозної шкоди кожні $t1 с." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\n\nUpon expiration, inflicts Nature damage based on your missing health.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nПісля завершення завдає шкоди від сил природи залежно від твого втраченого здоров'я." },
    { en = "Inflicts $441703s1 Nature damage every $t1 sec.\n\nOccurs if $@spellname437417 detonates $@spellname438846.", ua = "Завдає $441703s1 шкоди від сил природи кожні $t1 с.\n\nВиникає, якщо $@spellname437417 підриває $@spellname438846." },
    { en = "Movement speed reduced by $s2%.\n\nInflicts $s1 Nature damage every $t1 sec.", ua = "Швидкість пересування знижена на $s2%.\n\nЗавдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\nCreates $s2 Blood Parasites upon expiration.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nПісля завершення дії створює $s2 |4Кров'яного паразита:Кров'яних паразитів;." },
    { en = "Health increased by $s1%.\nMovement speed increased by $458207s1%.", ua = "Здоров'я збільшено на $s1%.\nШвидкість пересування збільшено на $458207s1%." },
    { en = "Absorbs $w2 healing received.", ua = "Поглинає $w2 отримуваного зцілення." },
    { en = "Prepared to butcher the next creature Khaz Algar you skin, guaranteeing meat for use in cooking.", ua = "Підготовлено до розбирання наступної білуваної істоти Каз Алґару: гарантовано отримаєш м'ясо для кулінарії." },
    { en = "Haste increased by $w1% and $?s1259790[Unstable Affliction grants $w2 additional stack of Wither.][Chaos Bolt grants $w3 additional stack of Wither.]\n\nAll of your active Withers are acute.", ua = "Поспіх збільшено на $w1%, а $?s1259790[«Нестабільна недуга» дає $w2 додатковий заряд «В'янення».][«Стріла хаосу» дає $w3 додатковий заряд «В'янення».]\n\nУсі твої активні «В'янення» — гострі." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec and absorbs $w2 healing received.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с. і поглинає $w2 отримуваного зцілення." },
    { en = "Time between attacks increased by $w1% and casting time increased by $w3%. $?e1[Chance to critically strike reduced by $w2%.][]", ua = "Час між атаками збільшено на $w1%, а час творення заклять — на $w3%. $?e1[Шанс критичного удару зменшено на $w2%.][]" },
    { en = "Inflicting $443063s1 to all players every $t1 sec.", ua = "Завдає $443063s1 шкоди всім гравцям кожні $t1 с." },
    { en = "Mulch is prepared and ready for use, granting Finesse on your next herb gathered. You can only use one Mulch at a time.", ua = "Мульча приготована й готова до використання: вона дасть Витонченість за наступну зібрану траву. Одночасно можна використовувати лише одну мульчу." },
    { en = "Channeling the power of the August Celestials, $?c2[healing $s3 nearby allies.]?c3[damaging nearby enemies.][]$?a443059[\n\nDamage taken reduced by $w2%.][]$?a443566[\n\nMovement speed increased by $w5%.][]", ua = "Підтримує силу Величних Небожителів, $?c2[зцілюючи $s3 союзників поблизу.]?c3[завдаючи шкоди ворогам поблизу.][]$?a443059[\n\nОтримувана шкода знижена на $w2%.][]$?a443566[\n\nШвидкість пересування збільшена на $w5%.][]" },
    { en = "Tentacles forming at your feet every $443042t1 sec.", ua = "Біля твоїх ніг кожні $443042t1 с утворюються щупальця." },
    { en = "Black Blood sloughing off every $t1 sec.", ua = "Чорна кров відшаровується кожні $t1 с." },
    { en = "Your presence is masked in the Umbral Bazaar, The Skeins, The Burrows, and High Hollows.\n\nStill discoverable by Guards with Keen Senses.", ua = "Твою присутність приховано в Сутінковому Базарі, Мотках, Норах і Високих Улоговинах.\n\nВартові з гострим чуттям однаково можуть тебе виявити." },
    { en = "Your abilities have a chance to call an earthen ally to your aid, supporting you in combat.", ua = "Ваші здібності мають шанс прикликати на допомогу земляного союзника, що підтримує вас у бою." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nExplode with doubt upon removal.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля зняття вибухає сумнівом." },
    { en = "Your next healing or damaging spell $?a1246131[or Hex ][]is instant, costs no mana, and deals $s6% increased damage and healing.", ua = "Твоє наступне закляття зцілення чи шкоди $?a1246131[або «Зурочення» ][]твориться миттєво, не коштує мани й завдає на $s6% більше шкоди та зцілення." },
    { en = "Damage taken from $@spellname443494  increased by $s2%", ua = "Шкода від «$@spellname443494» збільшена на $s2%" },
    { en = "$?e2[Critical Strike]?e3[Haste]?e4[Mastery]?e5[Versatility][Highest secondary stat] increased by $w1.", ua = "$?e2[Критичний удар]?e3[Поспіх]?e4[Майстерність]?e5[Універсальність][Найвищу другорядну характеристику] збільшено на $w1." },
    { en = "Unleashing a tormenting chorus, inflicting Shadow damage every $t1 sec.", ua = "Вивільняє болісний хор, завдаючи тіньову шкоду кожні $t1 с." },
    { en = "Healing for $s4 every $t4 sec.\nHaste increased by $s1%.\nImmune to crowd control effects.", ua = "Зцілює $s4 здоров'я кожні $t4 с.\nПоспіх збільшено на $s1%.\nНесприйнятливість до ефектів контролю." },
    { en = "Suffering $w1 Nature damage every $T1 sec.", ua = "Зазнає $w1 шкоди від сил природи кожні $T1 с." },
    { en = "Redirecting $w1% of healing done until the Coagulum has consumed ${$w2} healing.", ua = "Перенаправляє $w1% зцілення, доки Згусток не поглине ${$w2} зцілення." },
    { en = "At the heart of the swarm.", ua = "У серці рою." },
    { en = "Periodically triggers a lightning strike.", ua = "Періодично викликає удар блискавки." },
    { en = "Your movement speed is increased by $?a391547[${$w5+$391547w1}][$w5]%, you cannot be slowed below $s10% of normal speed, and you are immune to forced movement effects and knockbacks.", ua = "Твою швидкість пересування збільшено на $?a391547[${$w5+$391547w1}][$w5]%, тебе не можна сповільнити нижче $s10% звичайної швидкості, і ти несприйнятливий до ефектів примусового переміщення та відкидання." },
    { en = "Damage taken increased by $s2%.\n\nStunned.", ua = "Отримувана шкода збільшена на $s2%.\n\nПриголомшено." },
    { en = "Absorbs ${$w1} damage and prevents crowd controlling effects.", ua = "Поглинає ${$w1} шкоди та блокує ефекти контролю." },
    { en = "Inflicts $445162s1 Shadow damage every $445152t1 sec.$?diff14|diff17[\n\nRemoved by $@spellname451802.][]$?diff15[\n\nRemoved by $@spellname443915, causing $@spellname446012 and destabilizing the conduit.][]$?diff16[\n\nDestabilizes $@spellname443915.\n\nUpon expiration, causes $@spellname446012 and reforms.][]", ua = "Завдає $445162s1 шкоди від тіні кожні $445152t1 с.$?diff14|diff17[\n\nЗнімається за допомогою $@spellname451802.][]$?diff15[\n\nЗнімається за допомогою $@spellname443915, спричиняючи $@spellname446012 і дестабілізуючи канал.][]$?diff16[\n\nДестабілізує $@spellname443915.\n\nПісля завершення дії спричиняє $@spellname446012 і відновлюється.][]" },
    { en = "Absorbing $w1 damage.\nProtected against $@spellname424371.", ua = "Поглинає $w1 шкоди.\nЗахищено від $@spellname424371." },
    { en = "Inflicts $<damage> Shadow damage every $t1 sec to all players.\n\n$@spellname451802 amplify this effect by $445268s~1% upon opening.\n\nAnsurek gains $@spellname451832 if she casts $@spellname445422 with $s~2 applications of this effect.", ua = "Завдає $<damage> шкоди від тіні кожні $t1 с. всім гравцям.\n\n$@spellname451802 при відкритті підсилює цей ефект на $445268s~1%.\n\nАнсурек отримує $@spellname451832, якщо творить $@spellname445422 із $s~2 зарядами цього ефекту." },
    { en = "$@spellname449578 and $@spellname449581 are unaffected by your movements.", ua = "Твої рухи не впливають на $@spellname449578 і $@spellname449581." },
    { en = "Damage taken from $@spellname443612 increased by $s1%.", ua = "Шкода від «$@spellname443612» збільшена на $s1%." },
    { en = "$@spellname451895 damage increased per stack.", ua = "Шкода $@spellname451895 збільшується з кожним зарядом." },
    { en = "Gripped by Ansurek's webs.\n\nPull force increases over time.", ua = "Схоплено павутинням Ансурек.\n\nСила притягання зростає з часом." },
    { en = "Movement speed decreased by $s1%.\n\nOccurs if Ansurek consumes$?diff14|diff17|diff220[ Summoned Acolytes][ $@spellname445152 or Summoned Acolytes] with $@spellname445422.", ua = "Швидкість пересування знижена на $s1%.\n\nВиникає, якщо Ансурек поглинає$?diff14|diff17|diff220[ прикликаних послушників][ $@spellname445152 або прикликаних послушників] за допомогою $@spellname445422." },
    { en = "Increases damage taken from $@spellname445152 by $s1%.", ua = "Збільшує отримувану шкоду від $@spellname445152 на $s1%." },
    { en = "Inflicts $s2 Nature damage every $t2 sec.\nMovement speed reduced by $s1%.\n\nWhen dispelled a $@spellname446351 is triggered.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с.\nШвидкість пересування знижена на $s1%.\n\nПри розвіюванні спрацьовує $@spellname446351." },
    { en = "$@spellaura440513\n\nSurf's up!", ua = "$@spellaura440513\n\nЛовимо хвилю!" },
    { en = "Health increased by $s1%.\nCasting speed increased by $s2%.", ua = "Здоров'я збільшено на $s1%.\nШвидкість прочитання збільшено на $s2%." },
    { en = "Health increased by $s1%.\nVicious Bite inflicts Necrotic Wounds.", ua = "Здоров'я збільшено на $s1%.\n«Лютий укус» накладає «Некротичні рани»." },
    { en = "$?$446794W1=0[Damage done increased by $446794s1%.][Avanoxx feasts on any Starved Crawlers that reach her, increasing damage done. This effect stacks.]", ua = "$?$446794W1=0[Завдана шкода збільшена на $446794s1%.][Аваноксс пожирає всіх зголоднілих повзунів, що дістаються до неї, збільшуючи завдану шкоду. Цей ефект накопичується.]" },
    { en = "Inflicts $447175s1 Nature damage every $t1 sec$?diff14|diff17[][ to players within $447175A1 yards.]", ua = "Завдає $447175s1 шкоди від сил природи кожні $t1 с.$?diff14|diff17[][ гравцям у радіусі $447175A1 м.]" },
    { en = "Channeling Skullsplitter.", ua = "Підтримує «Череполом»." },
    { en = "Inflicts $s2 Physical damage every $t2 sec and unable to move while being mauled.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с. і не дає рухатися, поки тебе шматують." },
    { en = "Periodically applies $@spellname447965 to players within $447972A1 yards.", ua = "Періодично накладає $@spellname447965 на гравців у радіусі $447972A1 м." },
    { en = "Inflicts $448006s1 Shadow damage every $t1 sec to$?diff220[ all players.][ players within $448006A1 yards.]$?diff14|diff17|diff220[][\n\nPeriodically forms $@spellname448176.]$?diff220[][\n\n$@spellname448046 occurs upon death.]", ua = "Завдає $448006s1 шкоди від тіні кожні $t1 с.$?diff220[ всім гравцям.][ гравцям у радіусі $448006A1 м.]$?diff14|diff17|diff220[][\n\nПеріодично утворює $@spellname448176.]$?diff220[][\n\n$@spellname448046 стається після смерті.]" },
    { en = "Inflicts $448064s1 Shadowflame damage every $t1 sec.", ua = "Завдає $448064s1 шкоди тіньовим полум'ям кожні $t1 с." },
    { en = "All damage taken is also dealt to allies.\nCaptain Dailcry's presence increases the health of his nearby trusted guard by $462855s1%.", ua = "Уся отримувана шкода також завдається союзникам.\nПрисутність капітана Дейлкрая збільшує здоров'я його довіреної варти поблизу на $462855s1%." },
    { en = "Absorbs ${$w1} damage.", ua = "Поглинає ${$w1} шкоди." },
    { en = "Spell damage increased by $W1%.", ua = "Шкода від заклять збільшена на $W1%." },
    { en = "Your Phoenix is aiding you in battle!", ua = "Твій фенікс допомагає тобі в бою!" },
    { en = "$448887s1 Nature damage every $448888T1 sec.", ua = "$448887s1 шкоди від сил природи кожні $448888T1 с." },
    { en = "Inflicts $s2 Physical damage every $t2 sec.\n\nReduced movement speed by $s1%.", ua = "Завдає $s2 фізичної шкоди кожні $t2 с.\n\nШвидкість пересування знижена на $s1%." },
    { en = "Enables skyriding, steady flight, and in-combat mounting.\nProtected from $@spellname449332.", ua = "Дозволяє небесну їзду, рівний політ і сідати верхи в бою.\nЗахист від «$@spellname449332»." },
    { en = "Melee attacks increase target's damage taken by $449236s1%.", ua = "Атаки ближнього бою збільшують отримувану ціллю шкоду на $449236s1%." },
    { en = "Instantly kills upon expiration.\nGain $@spellname449042 to remain alive.", ua = "Після завершення дії миттєво вбиває.\nОтримай $@spellname449042, щоб лишитися живим." },
    { en = "$s1% increased melee attack damage done.\n$s2% reduced movement speed.", ua = "Шкода атак ближнього бою збільшена на $s1%.\nШвидкість пересування знижена на $s2%." },
    { en = "Increases Acidic Eruption damage by $s2%.\nImmune to damage.", ua = "Збільшує шкоду «Кислотного виверження» на $s2%.\nНесприйнятливість до шкоди." },
    { en = "Stunned!\n$s1 Physical damage inflicted every $t1 sec.", ua = "Приголомшено!\nЗавдає $s1 фізичної шкоди кожні $t1 с." },
    { en = "After gorging $s2 times, the caster explodes.", ua = "Нажершись $s2 |4рази:разів;, заклинач вибухає." },
    { en = "Inflicts $450079s1 Shadow damage every $t1 sec.", ua = "Завдає $450079s1 шкоди від тіні кожні $t1 с." },
    { en = "Inflicts $s2 Shadow damage every $t2 sec.\n\nStunned.", ua = "Завдає $s2 шкоди від тіні кожні $t2 с.\n\nПриголомшено." },
    { en = "Absorb $w1 healing.\n\nMovement speed reduced by $s3%.", ua = "Поглинає $w1 зцілення.\n\nШвидкість пересування знижена на $s3%." },
    { en = "Suffering $s2 Sonic damage every $t2 sec.", ua = "Зазнає $s2 звукової шкоди кожні $t2 с." },
    { en = "Stunned.\n$450863s3 Fire damage inflicted every $450863t3 sec.", ua = "Приголомшено.\nЗавдає $450863s3 вогняної шкоди кожні $450863t3 с." },
    { en = "Restores $w1% health per second.", ua = "Відновлює $w1% здоров'я щосекунди." },
    { en = "Restores $w1% mana per second.", ua = "Відновлює $w1% мани щосекунди." },
    { en = "Silenced.\nSuffering $s2 Physical damage every $t2 sec.", ua = "Змушено замовкнути.\nЗазнає $s2 фізичної шкоди кожні $t2 с." },
    { en = "Absorbs $w2 damage.\nPeriodically casts $@spellname441782.", ua = "Поглинає $w2 шкоди.\nПеріодично творить $@spellname441782." },
    { en = "Arcane Barrage grants Clearcasting, $s2 stacks of Arcane Salvo, and generates $s1 Arcane Charges.", ua = "«Арканний шквал» дає «Чисте прочитання», $s2 зарядів «Арканного залпу» та генерує $s1 арканних зарядів." },
    { en = "Absorbs $w2 damage.\nPeriodically casts $@spellname460364.\nPeriodically casts $@spellname443068.", ua = "Поглинає $w2 шкоди.\nПеріодично творить $@spellname460364.\nПеріодично творить $@spellname443068." },
    { en = "Inflicts $464736s1 Nature damage every $t1 sec.$?diff15|diff16[\n\nCauses $@spellname464628.][]\n\nUpon expiration, inflicts $464640s1 Nature damage to nearby players.", ua = "Завдає $464736s1 шкоди від сил природи кожні $t1 с.$?diff15|diff16[\n\nСпричиняє $@spellname464628.][]\n\nПісля завершення дії завдає $464640s1 шкоди від сил природи гравцям поблизу." },
    { en = "Increased chance to catch Specular Rainbowfish.", ua = "Збільшено шанс упіймати Дзеркальну Райдужну Рибу." },
    { en = "Increased chance to catch Quiet River Bass.", ua = "Збільшено шанс упіймати Тихого Річкового Окуня." },
    { en = "Increased chance to catch Dornish Pike.", ua = "Збільшено шанс упіймати Дорнійську Щуку." },
    { en = "Increased chance to catch Arathor Hammerfish.", ua = "Збільшено шанс упіймати Аратійську Рибу-Молот." },
    { en = "Guaranteed to find Roaring Anglerseeker from any Fishing Pool in The Ringing Deeps or Hallowfall.", ua = "Гарантовано виловлюєш Ревучого Вудкошукача з будь-якого косяка риби у Дзвінких Глибинах чи Голловфолі." },
    { en = "Injured.\nStarting health reduced to $s1%.", ua = "Поранено.\nПочаткове здоров'я зменшене до $s1%." },
    { en = "Recasts $@spellname445422 indefinitely.\n\nApplies after casting $@spellname445422 with $445268s2 applications of $@spellname445268.", ua = "Безперервно повторює $@spellname445422.\n\nНакладається після прочитання $@spellname445422 із $445268s2 накладаннями $@spellname445268." },
    { en = "Mincing herbs.", ua = "Січе трави." },
    { en = "Taking $s1 Shadow damage every $t1 sec.", ua = "Зазнає $s1 шкоди від тіні кожні $t1 с." },
    { en = "Increases Acidic Eruption damage by $s2%.", ua = "Збільшує шкоду «Кислотного виверження» на $s2%." },
    { en = "Consumed automatically to heal allies who fall below 70% health. If not consumed, gain Intellect for $452565d upon expiration.", ua = "Витрачається автоматично, щоб зцілити союзників, чиє здоров'я падає нижче 70%. Якщо не витрачено, після завершення дає Інтелект на $452565d." },
    { en = "Holding a torch.", ua = "Тримаєш смолоскип." },
    { en = "$453214s2 Shadow damage every $453214T2 sec.", ua = "$453214s2 шкоди від тіні кожні $453214T2 с." },
    { en = "Your next Lava Lash grants you Hot Hand for ${$s1/1000} sec.", ua = "Ваш наступний Лавовий Батіг надає вам Гарячу Руку на ${$s1/1000} с." },
    { en = "$?a137041[Your next Sundering deals $w1% increased damage and summons a Searing Totem.][Your next Chain Heal applies Earthliving at $w2% effectiveness to all targets hit.]", ua = "$?a137041[Твій наступний «Розкол» завдає на $w1% більше шкоди та прикликає «Палючий тотем».][Твоє наступне «Ланцюгове зцілення» накладає «Живу землю» з $w2% ефективності на всі вражені цілі.]" },
    { en = "Your next Healing Wave also heals an ally inside of your Healing Rain at $w1% effectiveness.", ua = "Твоя наступна «Цілюща хвиля» також зцілює союзника всередині твого «Цілющого дощу» з $w1% ефективності." },
    { en = "$?a137041[Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes $s3 Surging Bolts at your Surging Totem.][The cast time of your next healing spell is reduced by $w1%.]", ua = "$?a137041[Твоя наступна «Блискавка», «Ланцюгова блискавка» чи «Стихійний вибух» вивільняє $s3 |4«Бурхливі розряди»:«Бурхливих розрядів»; по твоєму «Бурхливому тотему».][Час прочитання твого наступного зцілювального закляття зменшено на $w1%.]" },
    { en = "$453618w1 healing absorbed.", ua = "Поглинає $453618w1 зцілення." },
    { en = "Explodes upon death.", ua = "Вибухає після смерті." },
    { en = "Lightning Bolt replaced by Tempest.", ua = "«Блискавка» замінюється на «Буревій»." },
    { en = "Increases Movement speed by $s1%, while in Light's Blooming and nearby keyflame areas.", ua = "Збільшує швидкість пересування на $s1%, поки ти в Цвітінні Світла або в зонах ключового полум'я поблизу." },
    { en = "Stunned.\nDestroying these webs removes the effect.", ua = "Приголомшено.\nЗнищення цього павутиння знімає ефект." },
    { en = "Dealing damage has a chance to ignite your foes in holy flames. Cannot occur more than once every $proccooldown sec.", ua = "Завдаючи шкоди, ти маєш шанс запалити ворогів святим полум'ям. Не частіше ніж раз на $proccooldown с." },
    { en = "$s1 Nature damage every $T1 sec.$?diff16[\nMovement speed reduced by $s2%.][]", ua = "$s1 шкоди від сил природи кожні $T1 с.$?diff16[\nШвидкість пересування знижена на $s2%.][]" },
    { en = "Health is shared between Anub'arash and Skeinspinner Takazj.", ua = "Ануб'араш і Прядильниця Таказж мають спільне здоров'я." },
    { en = "Upon expiration, inflicts $455416s1 Shadow damage to nearby players.", ua = "Після завершення завдає $455416s1 тіньової шкоди гравцям поблизу." },
    { en = "Taking damage has a high chance to brand your assailant dealing $w1 Holy Fire damage and healing you for $w2% of damage dealt.", ua = "Отримання шкоди має високий шанс затаврувати твого нападника, завдаючи $w1 шкоди від Священного Вогню та зцілюючи тебе на $w2% завданої шкоди." },
    { en = "Increased movement speed and haste.", ua = "Швидкість пересування та Поспіх збільшено." },
    { en = "$pri increased by $w2. All other stats increased by $w1.", ua = "$pri збільшено на $w2. Усі інші характеристики збільшено на $w1." },
    { en = "Enshrouded in necromantic energies, absorbing $w1 damage.", ua = "Огорнуто некромантськими енергіями, поглинає $w1 шкоди." },
    { en = "Damage taken from $@spellname434776 increased by $s1%.", ua = "Шкода від $@spellname434776 збільшена на $s1%." },
    { en = "Kills any player without $@spellname455849 within $A yards.\nBeing damaged will sometimes create a $@spellname460357.", ua = "Убиває будь-якого гравця без $@spellname455849 у радіусі $A м.\nОтримання шкоди іноді створює $@spellname460357." },
    { en = "Kills any player without $@spellname455850 within $A yards.\nBeing damaged will sometimes create a $@spellname460263.", ua = "Убиває будь-якого гравця без $@spellname455850 у радіусі $A м.\nОтримання шкоди іноді створює $@spellname460263." },
    { en = "$460365s1 Chaos damage inflicted every $t1 sec.", ua = "Завдає $460365s1 шкоди хаосу кожні $t1 с." },
    { en = "The whispers grow...", ua = "Шепоти дужчають..." },
    { en = "Disoriented!\nAll damage taken is increased by $s2%.", ua = "Дезорієнтовано!\nУся отримувана шкода збільшена на $s2%." },
    { en = "Remorseless Winter has accumulated $w1 damage.", ua = "«Невблаганна зима» накопичила $w1 шкоди." },
    { en = "Hammerfished.", ua = "Вдарено Рибою-Молотом." },
    { en = "On death, caster unleashes shadow energy that afflicts players with $@spellname456719.", ua = "Гинучи, заклинач вивільняє тіньову енергію, що накладає на гравців $@spellname456719." },
    { en = "Increased Shadow damage taken by $s1%. This effect stacks.", ua = "Отримувана тіньова шкода збільшена на $s1%. Цей ефект накопичується." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec. \n\nReduced movement speed by $s2%.", ua = "Завдає $s1 шкоди тіньовим полум'ям кожні $t1 с. \n\nШвидкість пересування знижена на $s2%." },
    { en = "$w1 Physical damage inflicted every second.\n$w2 Nature damage inflicted every second.", ua = "Завдає $w1 фізичної шкоди щосекунди.\nЗавдає $w2 шкоди від сил природи щосекунди." },
    { en = "You are targeted with $@spellname458082!\nMovement speed increased by $s1%.", ua = "Тебе обрано ціллю: $@spellname458082!\nШвидкість пересування збільшена на $s1%." },
    { en = "Increase your Mastery Rating by $w1.", ua = "Збільшує твій рейтинг Майстерності на $w1." },
    { en = "Restores ${$m1/5} health and mana per second.", ua = "Відновлює ${$m1/5} здоров'я та мани щосекунди." },
    { en = "Stunned.\n$s2 Frost damage inflicted every $t2 sec.", ua = "Приголомшено.\nЗавдає $s2 морозної шкоди кожні $t2 с." },
    { en = "You have been deemed a minor threat.", ua = "Тебе визнано незначною загрозою." },
    { en = "Damage taken reduced by $w1.", ua = "Отримувана шкода зменшена на $w1." },
    { en = "The bond between you and your pet is strong, granting you both $s3% increased effectiveness from Mastery: Spirit Bond.", ua = "Зв'язок між тобою і твоїм улюбленцем міцний: ви обоє отримуєте на $s3% більше ефекту від «Майстерності: Духовний Зв'язок»." },
    { en = "$s2  Fire damage inflicted every $t2 sec.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с." },
    { en = "Riding in style around the streets of Undermine.\n\nWhat's better than the smell of fuel, flames, and fumes? Speed!", ua = "Стильна їзда вулицями Андермайна.\n\nЩо може бути краще за запах пального, полум'я та вихлопів? Швидкість!" },
    { en = "Repairing Protecting Plating to full.", ua = "Повністю відновлює захисну обшивку." },
    { en = "Increases damage taken from $@spellname438846 by $s1%.", ua = "Збільшує отримувану шкоду від $@spellname438846 на $s1%." },
    { en = "$w1 healing absorbed.\n$s4 Shadow damage inflicted every $t4 sec.\nMovement speed reduced by $s2%.", ua = "Поглинає $w1 зцілення.\nЗавдає $s4 шкоди від тіні кожні $t4 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Repairing the War Tank by $460153s1% every $t1 sec.", ua = "Ремонтує Бойовий танк на $460153s1% кожні $t1 с." },
    { en = "Unable to travel through a $@spellname460366.", ua = "Не може проходити крізь $@spellname460366." },
    { en = "$s1 Fire damage inflicted every $t1 sec.\nAt $s2 stacks $460365s2 Chaos damage is inflicted.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с.\nЗа $s2 зарядів завдає $460365s2 шкоди хаосу." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nAt $s2 stacks $460365s2 Chaos damage is inflicted.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nЗа $s2 зарядів завдає $460365s2 шкоди хаосу." },
    { en = "Damage and healing done increased by $s1%.\nMovement speed increased by $s2%.", ua = "Завдавана шкода та зцілення збільшені на $s1%.\nШвидкість пересування збільшена на $s2%." },
    { en = "Damage taken from $@spellname460472 increased by $s2%.", ua = "Шкода від «$@spellname460472» збільшена на $s2%." },
    { en = "$460798s1 Nature damage to players inside the indicated area upon expiration.", ua = "Після завершення завдає $460798s1 шкоди від сил природи гравцям у позначеній ділянці." },
    { en = "Shocking all other players for $460873s1 Nature damage every $t2 sec.", ua = "Б'є струмом усіх інших гравців, завдаючи $460873s1 шкоди від сил природи кожні $t2 с." },
    { en = "Unable to be reduced below $s2% health.\n\nCan be shattered with a $@spellname460181 chip.", ua = "Здоров'я не можна знизити нижче $s2%.\n\nМожна розбити фішкою $@spellname460181." },
    { en = "|cFF00AA99It's GAME TIME!|r", ua = "|cFF00AA99Час ГРАТИ!|r" },
    { en = "Damage done increased by $s1%.\n\n|cFF00AA99TILT TILT TILT!|r", ua = "Завдавана шкода збільшена на $s1%.\n\n|cFF00AA99TILT TILT TILT!|r" },
    { en = "Health reduced by $s1%.\n\nUpon death, releases explosive loot.", ua = "Здоров'я зменшено на $s1%.\n\nПісля смерті вивільняє вибухову здобич." },
    { en = "Health increased by $s1%\nDamage done increased by $s2%.\nImmune to crowd controlling and interrupting effects.", ua = "Здоров'я збільшено на $s1%\nЗавдавана шкода збільшена на $s2%.\nНесприйнятливий до ефектів контролю та переривання." },
    { en = "Maximum health increased by $s1%.\nMovement speed reduced by $s2%.\n\nUpon death, erupts in a massive burning blast.", ua = "Максимальне здоров'я збільшене на $s1%.\nШвидкість пересування знижена на $s2%.\n\nПісля смерті вибухає потужним палаючим спалахом." },
    { en = "$s1 Nature damage inflicted every $t1 sec.\n\nUpon removal, waves of poison erupt forth inflicting $461507s1 Nature damage and an additional $461507s2 Nature damage every $461507t2 sec for $461507d.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nПісля зняття вириваються хвилі отрути, що завдають $461507s1 шкоди від сил природи та додатково $461507s2 шкоди від сил природи кожні $461507t2 с протягом $461507d." },
    { en = "You are a nigh-unstoppable sphere of pure garbage. Roll up objects in your path to increase in size!\n\nDamage taken reduced by $s2%.", ua = "Ти — майже нестримна куля з чистісінького сміття. Накочуй предмети на своєму шляху, щоб вирости!\n\nОтримувана шкода зменшена на $s2%." },
    { en = "Inflicts $s1 Nature damage every $t1 sec for $d.", ua = "Завдає $s1 шкоди від сил природи щосекунди ($t1) протягом $d." },
    { en = "Mastery increased by $w9.", ua = "Майстерність збільшена на $w9." },
    { en = "Forge weekly Severed Threads Pacts, granting access to World Quests, Rumors, treasures, and unique abilities.", ua = "Укладай щотижневі пакти Перетятих Ниток, що відкривають доступ до світових завдань, чуток, скарбів та унікальних здібностей." },
    { en = "Restores ${$m1/5} health and ${$m3/5} mana per second.", ua = "Відновлює ${$m1/5} здоров'я та ${$m3/5} мани щосекунди." },
    { en = "Your primary stats have been increased by $w11. This aura persists through death.", ua = "Твої основні характеристики збільшено на $w11. Ця аура зберігається після смерті." },
    { en = "Lord Roccor will erupt after suffering significant damage.", ua = "Лорд Роккор вибухне, зазнавши значної шкоди." },
    { en = "$s1% of damage taken echoes to other creatures of this type.\n\nWhen close together, becomes immune to all damage and pulses $462698s1 Shadow damage to all players every $453990t3 sec.\n\nDamage increases by $462699s1% with each pulse.", ua = "$s1% отриманої шкоди відлунює на інших істот цього типу.\n\nКоли вони поруч, істота стає несприйнятливою до будь-якої шкоди й пульсує, завдаючи $462698s1 шкоди від тіні всім гравцям кожні $453990t3 с.\n\nШкода зростає на $462699s1% з кожним імпульсом." },
    { en = "Mastery increased by $w1% and auto attacks have a $h% chance to instantly strike again.", ua = "Майстерність збільшена на $w1%, а автоатаки мають $h% шансу миттєво вдарити ще раз." },
    { en = "$463428s1 Nature damage every $463428T1 sec.", ua = "$463428s1 шкоди від сил природи кожні $463428T1 с." },
    { en = "Damage from $@spellname460600 increased by $s1%.", ua = "Шкода від «$@spellname460600» збільшена на $s1%." },
    { en = "Damage from $@spellname460364 increased by $s1%.", ua = "Шкода від «$@spellname460364» збільшена на $s1%." },
    { en = "The dragonflights grant new adventurers their blessings, providing various boons.", ua = "Зграї драконів дарують новим шукачам пригод свої благословення, що дають різні переваги." },
    { en = "The magic of the red dragonflight has recently saved you, preventing you from death.", ua = "Магія червоної зграї драконів нещодавно врятувала тебе від смерті." },
    { en = "Inflicts $463603s1 Nature damage after $d.", ua = "Через $d завдає $463603s1 шкоди від сил природи." },
    { en = "Electric missiles are locked onto you!", ua = "Електричні ракети націлені на тебе!" },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\nCannot attack or cast spells.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\nНеможливо атакувати чи творити закляття." },
    { en = "Unable to act.\nDamage received reduced by $w2%.\nHealing received reduced by $w3%.", ua = "Не може діяти.\nОтримувана шкода зменшена на $w2%.\nОтримуване зцілення зменшене на $w3%." },
    { en = "Targeted by Blizzard.", ua = "Обрано ціллю: «Хуртовина»." },
    { en = "Absorbs $w2 damage.\nRestores $w3 health every $t3 sec.", ua = "Поглинає $w2 шкоди.\nВідновлює $w3 здоров'я кожні $t3 с." },
    { en = "Damage done reduced by $s1%.\nDamage taken reduced by $s2%.\nImmune to interrupts.", ua = "Завдавана шкода зменшена на $s1%.\nОтримувана шкода зменшена на $s2%.\nІмунітет до переривань." },
    { en = "Able to use powerful abilities.", ua = "Може використовувати потужні здібності." },
    { en = "Increases the damage of allies within $s1 yards by $464426s1%, reduces damage taken by $464426s2%, and grants immunity to interrupts.", ua = "Підвищує шкоду союзників у радіусі $s1 ярдів на $464426s1%, зменшує отримувану шкоду на $464426s2% та дає несприйнятливість до переривань." },
    { en = "Melee attacks inflict Sonic damage and apply $@spellname464518.", ua = "Атаки ближнього бою завдають звукової шкоди та накладають $@spellname464518." },
    { en = "Sonic damage taken increased by $s1%.", ua = "Отримувана звукова шкода збільшена на $s1%." },
    { en = "Increases damage taken from $@spellname451278 by $s1%.", ua = "Збільшує отримувану шкоду від $@spellname451278 на $s1%." },
    { en = "Upon expiration, inflicts $437632s1 Nature damage.\n\nApplications decreased for each player near a bursting $@spellname438846.$?diff16[\n\nCauses $@spellname464643 with matching applications.][]", ua = "Після завершення завдає $437632s1 шкоди від сил природи.\n\nКількість накладань зменшується за кожного гравця поруч із вибухом $@spellname438846.$?diff16[\n\nСпричиняє $@spellname464643 з такою самою кількістю накладань.][]" },
    { en = "Inflicts $464646s1 Nature damage every $t1 sec.", ua = "Завдає $464646s1 шкоди від сил природи кожні $t1 с." },
    { en = "Movement speed reduced by $s2%.\n$s1 Nature damage inflicted every $t1 sec.", ua = "Швидкість пересування знижена на $s2%.\nЗавдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Every $s1 autoattacks, Emperor Thaurissan strikes $465062s2 additional times.", ua = "Кожні $s1 автоатак імператор Тауріссан завдає $465062s2 додаткових ударів." },
    { en = "Emperor Thaurissan's abilites are empowered.", ua = "Здібності імператора Тауріссана посилені." },
    { en = "$s2 Sonic damage inflicted every $t2 sec.", ua = "Завдає $s2 звукової шкоди кожні $t2 с." },
    { en = "It's GAME TIME!", ua = "ЧАС ГРАТИ!" },
    { en = "Periodically blasting beams of fire, inflicting $465388s1 Fire damage.", ua = "Періодично випускає промені вогню, завдаючи $465388s1 вогняної шкоди." },
    { en = "Linked to Hyper Coils!", ua = "Пов'язано з «Гіперкотушками»!" },
    { en = "Gaining 10 Electricity and emitting $465462s1 Nature damage to all players every $465463t1 sec.", ua = "Отримує 10 Електрики та випромінює $465462s1 шкоди від сил природи всім гравцям кожні $465463t1 с." },
    { en = "Inflicting $465583s1 Physical damage to all players every $t1 sec.", ua = "Завдає $465583s1 фізичної шкоди всім гравцям кожні $t1 с." },
    { en = "Damage taken increased by $s1%.\nMovement speed slowed by $s2%.", ua = "Отримувана шкода збільшена на $s1%.\nШвидкість пересування знижена на $s2%." },
    { en = "Blaring $@spellname469429 and inflicting $472990s1 Sonic damage every $t1 sec.", ua = "Реве $@spellname469429 і завдає $472990s1 звукової шкоди кожні $t1 с." },
    { en = "Gaining additional power.", ua = "Набирає додаткової сили." },
    { en = "You're holding a $@spellname466155!", ua = "Ти тримаєш $@spellname466155!" },
    { en = "Detonates upon expiration!", ua = "Вибухає після завершення!" },
    { en = "$1217291s1 Fire damage every $T1 sec.", ua = "$1217291s1 шкоди вогнем кожні $T1 с." },
    { en = "Finish learning more about the story and continue experiencing the tale.", ua = "Дізнайся більше про історію та продовжуй переживати цю оповідь." },
    { en = "Increases Scatterblast Canister damage by $471603s1%.", ua = "Збільшує шкоду «Каністр розкидного вибуху» на $471603s1%." },
    { en = "$466489s1 Fire damage split among players within $466577A2 yards upon expiration.\nPlayers within $466577A2 yards also gain $@spellname1220761.", ua = "Після завершення $466489s1 шкоди вогнем розподіляється між гравцями в радіусі $466577A2 м.\nГравці в радіусі $466577A2 м також отримують $@spellname1220761." },
    { en = "Inflicting $1221079s1 Frost damage to players within $1221079a1 yards every $t1 sec and sliding. $?|diff15|diff16 [\n\nTargeted for $@spellname466480.][]", ua = "Завдає $1221079s1 морозної шкоди гравцям у межах $1221079a1 м кожні $t1 с; ковзання. $?|diff15|diff16 [\n\nЦіль для $@spellname466480.][]" },
    { en = "Durable plating protects The Geargrinder.\nGains energy over time.", ua = "Міцна обшивка захищає Шестернедробара.\nЗ часом накопичує енергію." },
    { en = "Radiating $466752s1 Fire damage every $466751T2 sec to all players.", ua = "Випромінює $466752s1 вогняної шкоди кожні $466751T2 с усім гравцям." },
    { en = "$@spellname466751 duration increased by $s1 sec.", ua = "Тривалість $@spellname466751 збільшена на $s1 с." },
    { en = "Absorbing $s2% of incoming damage until $w1 is prevented. The bomb suit will detonate upon removal.", ua = "Поглинає $s2% вхідної шкоди, доки не буде відвернено $w1 шкоди. Після зняття бомбокостюм вибухне." },
    { en = "Inflicts up to $466955s1 Nature damage every $466834T1 sec.", ua = "Завдає до $466955s1 шкоди від сил природи кожні $466834T1 с." },
    { en = "Innovating.", ua = "Винаходить." },
    { en = "Your next Aimed Shot deals $s1% increased damage to this target.", ua = "Твій наступний «Прицільний постріл» завдає цій цілі на $s1% більше шкоди." },
    { en = "Casting Black Arrow fires a barrage of $466990s3 additional Black Arrows at nearby targets.", ua = "Застосування «Чорної стріли» випускає шквал із $466990s3 додаткових «Чорних стріл» у цілі поблизу." },
    { en = "$467184s2 Fire damage every $467184T2 sec.", ua = "$467184s2 шкоди вогнем кожні $467184T2 с." },
    { en = "Brann has a chance during combat to toss a GMB grenade at an enemy target dealing moderate Nature damage with a $1215588w1% chance to stun for $1215627d. This has a $1215588w2% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members.", ua = "Під час бою Бранн має шанс кинути ҐСГ-гранату у ворожу ціль, завдавши помірної шкоди від сил природи з $1215588w1% шансом приголомшити на $1215627d. Із шансом $1215588w2% граната відскакує до нової цілі.\n\nГраната може безпечно відскакувати від членів групи." },
    { en = "Every $473679t sec or $1219068d after entering combat, scan the environment highlighting Mislaid Curiosities and making enemies below $w1% health take $468210w1% more damage for $468210d.", ua = "Кожні $473679t с або через $1219068d після початку бою сканує довкілля, підсвічуючи Загублені Дивовижі, а вороги з менш ніж $w1% здоров'я отримують на $468210w1% більше шкоди протягом $468210d." },
    { en = "Nature damage taken increased by $s3%. Inflicting $467048s1 Nature damage to players within $467048A1 yards every $t1 sec.", ua = "Отримувана шкода від сил природи збільшена на $s3%. Завдає $467048s1 шкоди від сил природи гравцям у радіусі $467048A1 м кожні $t1 с." },
    { en = "Periodically dripping $@spellname470089.\n\nUpon expiration, turned to $@spellname467225.", ua = "Періодично скрапує $@spellname470089.\n\nПісля завершення перетворюється на $@spellname467225." },
    { en = "Stunned.\n\n|cFF00AA99A drip fit for a king.|r", ua = "Приголомшено.\n\n|cFF00AA99Прикид, гідний короля.|r" },
    { en = "Your Mister Lock-N-Stalk is configured for Precision Blasting.", ua = "Твій «Пан Замкни-й-Висліди» налаштовано на «Прицільний підрив»." },
    { en = "Your Mister Lock-N-Stalk is configured for Mass Destruction.", ua = "Твій «Пан Замкни-й-Висліди» налаштовано на «Масове знищення»." },
    { en = "Inflicts $467621s1 Physical damage every $t1 sec.", ua = "Завдає $467621s1 фізичної шкоди кожні $t1 с." },
    { en = "After $1215531w3 sec of combat, party members and Brann deal $1215551w1% more damage and healing for $1215551d. Can only occur once per combat.", ua = "Через $1215531w3 с бою члени групи та Бранн завдають на $1215551w1% більше шкоди й зцілення протягом $1215551d. Може статися лише раз за бій." },
    { en = "$467992s1 Sonic damage inflicted every $t1 sec.", ua = "Завдає $467992s1 звукової шкоди кожні $t1 с." },
    { en = "$468120s1 Sonic damage inflicted every $t1 sec.", ua = "Завдає $468120s1 звукової шкоди кожні $t1 с." },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\n\nStunned.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nПриголомшено." },
    { en = "Mug inflicts $s1 Elemental damage every $t1 sec for $d.\n\nPlayers are then branded with $@spellname468663.", ua = "Муг завдає $s1 стихійної шкоди кожні $t1 с протягом $d.\n\nПісля цього гравці отримують тавро $@spellname468663." },
    { en = "Inflicting $468665s1 Elemental damage to all players every $t1 sec.", ua = "Завдає $468665s1 стихійної шкоди всім гравцям кожні $t1 с." },
    { en = "Zee inflicts $468660s1 Fire damage every $t1 sec for $d. \n\nPlayers are then afflicted with $@spellname469715.", ua = "Зі завдає $468660s1 вогняної шкоди кожні $t1 с протягом $d. \n\nПотім на гравців накладається $@spellname469715." },
    { en = "Absorbing $w1 healing.\n\nInflicting $469052s1 Fire damage every $t2 sec.", ua = "Поглинає $w1 зцілення.\n\nЗавдає $469052s1 шкоди вогнем кожні $t2 с." },
    { en = "Damage taken from $@spellname467381 increased by $s1%.\n\n|cFF00AA99You feel delusional. You should go to the infirmary.|r", ua = "Шкода від «$@spellname467381» збільшена на $s1%.\n\n|cFF00AA99Ти мариш. Тобі варто піти до лазарету.|r" },
    { en = "$469295s1 Nature damage to all players every $469293T1 sec.", ua = "$469295s1 шкоди від сил природи всім гравцям кожні $469293T1 с." },
    { en = "$469326s2 Nature damage every $469326T2 sec.", ua = "$469326s2 шкоди від сил природи кожні $469326T2 с." },
    { en = "$1218500s1 Nature damage every $469362T2 sec.\nCarrying a Giga Bomb.", ua = "$1218500s1 шкоди від сил природи кожні $469362T2 с.\nНесе гіга-бомбу." },
    { en = "Upon expiring, inflicts $469377s1 Fire damage to players and detonates $@spellname466539 within $469377a1 yards.", ua = "Після завершення завдає $469377s1 вогняної шкоди гравцям і підриває $@spellname466539 у межах $469377a1 м." },
    { en = "Inflicting $469393s1 Physical damage every $t1 sec. This effect stacks.", ua = "Завдає $469393s1 фізичної шкоди кожні $t1 с. Цей ефект накопичується." },
    { en = "$469404s2 Nature damage every $469404T2 sec.", ua = "$469404s2 шкоди від сил природи кожні $469404T2 с." },
    { en = "Targeted.", ua = "Взято на приціл." },
    { en = "Inflicting $468665s1 Fire damage to all players every $t1 sec.", ua = "Завдає $468665s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "Movement speed increased by $469795s2%.", ua = "Швидкість пересування збільшена на $469795s2%." },
    { en = "Absorbs up to $w1 damage. Blasts nearby enemies with $s3  Fire damage each time ${$s1/$s4} damage is absorbed.", ua = "Поглинає до $w1 шкоди. Щоразу, коли поглинуто ${$s1/$s4} шкоди, вражає ворогів поблизу, завдаючи $s3 шкоди вогнем." },
    { en = "Suffering $w1 Radiant damage every $t sec.", ua = "Зазнає $w1 променистої шкоди кожні $t с." },
