    { en = "Targeted by Cremate.", ua = "Обрано ціллю: «Спопеління»." },
    { en = "Bottle service! Doling out Kaja'Cola Mega-Lite to injured allies every $t1 sec.", ua = "Пляшковий сервіс! Роздає «Каджа'Колу Мега-Лайт» пораненим союзникам кожні $t1 с." },
    { en = "$s1 Fire damage inflicted every $t1 sec. Movement speed increased by $s4%.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с. Швидкість пересування збільшена на $s4%." },
    { en = "Damage done increased by $471352s3%\nMovement speed increased by $471352s4%.", ua = "Завдавана шкода збільшена на $471352s3%\nШвидкість пересування збільшена на $471352s4%." },
    { en = "|cFF00AA99Bonus Event: Delves|r\n\nDelver's Journey and The Labyrinth of Kindo'jan Journey progress gains increased by $s1%.\nCompanion experience gains increased by $s3%.\nUndercoin gains increased by $s2%.", ua = "|cFF00AA99Бонусна подія: Глибини|r\n\nПриріст поступу «Подорожі Глибинника» та «Подорожі Лабіринтом Кіндо'джан» збільшено на $s1%.\nПриріст досвіду супутника збільшено на $s3%.\nПриріст Підмонет збільшено на $s2%." },
    { en = "Damage increased by $s1%.\nRange drastically increased.", ua = "Шкода збільшена на $s1%.\nДальність різко збільшена." },
    { en = "You will soon be able to summon the aid of a Beast.", ua = "Невдовзі ти зможеш покликати на поміч Звіра." },
    { en = "You and your pet's damage is increased by $s1%.", ua = "Шкода твоя і твого улюбленця збільшена на $s1%." },
    { en = "You feel a little smaller, increasing your Speed by $472120w4 and Haste by $472120w3.", ua = "Ти почуваєшся трохи меншим: твою Рухливість збільшено на $472120w4, а Поспіх — на $472120w3." },
    { en = "You feel a bit larger, increasing maximum health by $472120w1, and $pri by $472120w2.", ua = "Ти почуваєшся трохи більшим: максимальне здоров'я збільшено на $472120w1, а $pri — на $472120w2." },
    { en = "Flarendo applies Molten Spite to all players within $472222A1 yards every $t1 sec.", ua = "Фларендо накладає «Розплавлену злобу» на всіх гравців у межах $472222A1 м кожні $t1 с." },
    { en = "Torq applies Galvanized Spite to all players within $472225A1 yards every $t1 sec.", ua = "Торк накладає «Гальванізовану злобу» на всіх гравців у межах $472225A1 м кожні $t1 с." },
    { en = "Charging up...", ua = "Заряджається..." },
    { en = "Defeating an Elite enemy restores $m1 Sanity.", ua = "Перемога над елітним ворогом відновлює $m1 глузду." },
    { en = "Power Word: Radiance is instant cast and mana cost reduced by $s3%.", ua = "«Слово Сили: Сяйво» читається миттєво, а його вартість у мані зменшена на $s3%." },
    { en = "On impact, divides $467381s1 Nature damage evenly among all players hit and summons a Gallagio Goon.", ua = "При влучанні розподіляє $467381s1 шкоди від сил природи порівну між усіма враженими гравцями та прикликає Громила Ґалладжіо." },
    { en = "Inflicts $s3 Nature damage every $t3 sec.$?diff23|diff8[ \n\nCreates $@spellname1216044 upon expiration.][]", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с.$?diff23|diff8[ \n\nПісля завершення дії створює $@spellname1216044.][]" },
    { en = "$@spellname460181 chips increase the One-Armed Bandit's damage done by $s1%.", ua = "Фішки $@spellname460181 збільшують шкоду, завдану Одноруким Бандитом, на $s1%." },
    { en = "Inflicts $s1 Nature damage every $t1 sec.\n\nIncreases damage taken from $@spellname472745 by $s3%.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с.\n\nЗбільшує отримувану шкоду від $@spellname472745 на $s3%." },
    { en = "Inflicts $474065s1 Physical damage every ${$t1}.2 sec.", ua = "Завдає $474065s1 фізичної шкоди кожні ${$t1}.2 с." },
    { en = "Inflicting $472849s1 Fire damage to players within $472849A1 yards every ${$t1}.2 sec.", ua = "Завдає $472849s1 шкоди вогнем гравцям у радіусі $472849A1 м кожні ${$t1}.2 с." },
    { en = "Unable to move.\nImmune to crowd control effects.\n\nRemoved upon reaching $s1% health.", ua = "Не може рухатися.\nНесприйнятливість до ефектів контролю.\n\nЗнімається, коли здоров'я сягає $s1%." },
    { en = "Inflicting $473081s1  Nature damage to all players every $t1 sec.", ua = "Завдає $473081s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "This crab is about to explode.", ua = "Цей краб ось-ось вибухне." },
    { en = "Attack speed increased by $s1%.\n$@spellname464149 targets additional garbage piles$?diff14|diff15|diff16 [ and Electromagnetic Sorting summons addiitional threats][].", ua = "Швидкість атаки збільшена на $s1%.\n$@spellname464149 націлюється на додаткові купи сміття$?diff14|diff15|diff16 [, а «Електромагнітне сортування» прикликає додаткові загрози][]." },
    { en = "$473836s1 Nature damage inflicted every $473836t1 sec.", ua = "Завдає $473836s1 шкоди від сил природи кожні $473836t1 с." },
    { en = "Conjured to disperse void against void.", ua = "Викликано, щоб розсіяти Порожнечу Порожнечею." },
    { en = "$?j1g[Increases ground speed by $j1g%. ][]$?j1f[Increases flight speed by $j1f%. ][]$?j1s[Increases swim speed by $j1s%. ][] Hek hek hek!", ua = "$?j1g[Збільшує швидкість на землі на $j1g%. ][]$?j1f[Збільшує швидкість польоту на $j1f%. ][]$?j1s[Збільшує швидкість плавання на $j1s%. ][] Гек-гек-гек!" },
    { en = "Damage taken from $@spellname1216740 increased by $s3%.", ua = "Шкода від «$@spellname1216740» збільшена на $s3%." },
    { en = "Followed by lingering shadows that will occasionally chase you. Look at the shadows to stop them in their tracks!", ua = "За тобою тягнуться примарні тіні, що час від часу кидаються навздогін. Подивися на тіні, щоб спинити їх!" },
    { en = "Damage done increased by $1218060s1%. Casting $@spellname467991 endlessly.", ua = "Завдавана шкода збільшена на $1218060s1%. Безперервно творить «$@spellname467991»." },
    { en = "Effectiveness of any healing reduced by $s2%.", ua = "Ефективність будь-якого зцілення зменшена на $s2%." },
    { en = "$474159s3 Nature damage inflicted every $474159t3 sec. \n\nMoving increases charge, staying still reduces it. Reaching max charge triggers a $@spellname473983.", ua = "Завдає $474159s3 шкоди від сил природи кожні $474159t3 с. \n\nРух збільшує заряд, нерухомість зменшує його. Досягнення максимального заряду спричиняє $@spellname473983." },
    { en = "Targeted by $@spellname474114.", ua = "Обрано ціллю: $@spellname474114." },
    { en = "Recharging.\nDamage taken increased by $s4%.", ua = "Перезаряджається.\nОтримувана шкода збільшена на $s4%." },
    { en = "Damage inflicted is increased by $s1%.", ua = "Завдавана шкода збільшена на $s1%." },
    { en = "Stuns the target for $24394d.", ua = "Приголомшує ціль на $24394d." },
    { en = "Inflicts $s2 Nature damage every $t2 sec and maximum health reduced by $w1%.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с. і зменшує максимальне здоров'я на $w1%." },
    { en = "Inflicts $472672s1 Nature damage every $t1 sec to nearby players.", ua = "Завдає $472672s1 шкоди від сил природи кожні $t1 с. гравцям поблизу." },
    { en = "Bonded with $@auracaster. Their self-healing also heals you for $474754s1% of the amount healed. Their healing to you also heals them for $474754s2% of the amount healed.", ua = "Пов'язано з $@auracaster. Самозцілення цього союзника також зцілює тебе на $474754s1% зціленого обсягу. Зцілення, яке він надає тобі, також зцілює його на $474754s2% зціленого обсягу." },
    { en = "Bonded with $@auracaster. Your self-healing also heals them for $s1% of the amount healed. Your healing to them also heals you for $s2% of the amount healed.", ua = "Пов'язано з $@auracaster. Твоє самозцілення також зцілює цього союзника на $s1% зціленого обсягу. Твоє зцілення цього союзника також зцілює тебе на $s2% зціленого обсягу." },
    { en = "Every $1213486t sec or $1219068d after entering combat, scan the environment highlighting Mislaid Curiosities and making enemies below $w1% health take $1213372w1% more damage for $1213372d.", ua = "Кожні $1213486t с або через $1219068d після початку бою сканує довкілля, підсвічуючи Загублені Дивовижі, а вороги з менш ніж $w1% здоров'я отримують на $1213372w1% більше шкоди протягом $1213372d." },
    { en = "Every $1213487t sec or $1219068d after entering combat, scan the environment highlighting Mislaid Curiosities and making enemies below $w1% health take $1213371w1% more damage for $1213371d.", ua = "Кожні $1213487t с або через $1219068d після початку бою сканує довкілля, підсвічуючи Загублені Дивовижі, а вороги з менш ніж $w1% здоров'я отримують на $1213371w1% більше шкоди протягом $1213371d." },
    { en = "Every $1213488t sec or $1219068d after entering combat, scan the environment highlighting Mislaid Curiosities and making enemies below $w1% health take $1213370w1% more damage for $1213370d.", ua = "Кожні $1213488t с або через $1219068d після початку бою сканує довкілля, підсвічуючи Загублені Дивовижі, а вороги з менш ніж $w1% здоров'я отримують на $1213370w1% більше шкоди протягом $1213370d." },
    { en = "$s1 Arcane damage inflicted every $t1 sec.\nRooted!", ua = "Завдає $s1 арканної шкоди кожні $t1 с.\nЗнерухомлено!" },
    { en = "Haste increased by $s2%. Movement speed increased by $s1%.\n\n|cFF00AA99Hyped up!|r", ua = "Поспіх збільшено на $s2%. Швидкість пересування збільшено на $s1%.\n\n|cFF00AA99На підйомі!|r" },
    { en = "Absorbs $w2 damage.\nImmune to interrupt effects.", ua = "Поглинає $w2 шкоди.\nІмунітет до ефектів переривання." },
    { en = "Increases Total Destruction!!! damage by $s2%.", ua = "Збільшує шкоду закляття «ЦІЛКОВИТЕ ЗНИЩЕННЯ!!!» на $s2%." },
    { en = "Charmed.\n\n|cFF00AA99Feelin' the hype!|r", ua = "Зачаровано.\n\n|cFF00AA99Відчуваєш драйв!|r" },
    { en = "Damage done increased by $s1%$?diff16[ and damage taken reduced by $s6%.][.]", ua = "Завдавана шкода збільшена на $s1%$?diff16[, а отримувана шкода зменшена на $s6%.][.]" },
    { en = "Targeted by $@spellname1214637!", ua = "Обрано ціллю: $@spellname1214637!" },
    { en = "$1214755s1 Fire damage every second.", ua = "$1214755s1 шкоди вогнем щосекунди." },
    { en = "Reinforced. Shielded from $@spellname466722", ua = "Укріплено. Захист від $@spellname466722" },
    { en = "Inflicting $s1 Fire damage every $t1 sec. This effect stacks.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с. Цей ефект накопичується." },
    { en = "Upon reaching $s1% health the flyer malfunctions, becoming stunned and taking $1215595s1% increased damage for $1215595d.", ua = "Досягнувши $s1% здоров'я, літун дає збій, стає приголомшеним і отримує на $1215595s1% більше шкоди протягом $1215595d." },
    { en = "Increased damage done by $s1%.\n\nGains $s2 energy after using powerful abilities.", ua = "Завдавану шкоду збільшено на $s1%.\n\nОтримує $s2 енергії після застосування потужних здібностей." },
    { en = "Brann has a chance during combat to toss a GMB grenade at an enemy target dealing moderate Nature damage with a $1215795w1% chance to stun for $1215627d. This has a $1215795w2% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members.", ua = "Під час бою Бранн має шанс кинути ҐСГ-гранату у ворожу ціль, завдавши помірної шкоди від сил природи з $1215795w1% шансом приголомшити на $1215627d. Із шансом $1215795w2% граната відскакує до нової цілі.\n\nГраната може безпечно відскакувати від членів групи." },
    { en = "Brann has a chance during combat to toss a GMB grenade at an enemy target dealing moderate Nature damage with a $1215797w1% chance to stun for $1215627d. This has a $1215797w2% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members.", ua = "Під час бою Бранн має шанс кинути ҐСГ-гранату у ворожу ціль, завдавши помірної шкоди від сил природи з $1215797w1% шансом приголомшити на $1215627d. Із шансом $1215797w2% граната відскакує до нової цілі.\n\nГраната може безпечно відскакувати від членів групи." },
    { en = "Brann has a chance during combat to toss a GMB grenade at an enemy target dealing moderate Nature damage with a $1215799w1% chance to stun for $1215627d. This has a $1215799w2% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members.", ua = "Під час бою Бранн має шанс кинути ҐСГ-гранату у ворожу ціль, завдавши помірної шкоди від сил природи з $1215799w1% шансом приголомшити на $1215627d. Із шансом $1215799w2% граната відскакує до нової цілі.\n\nГраната може безпечно відскакувати від членів групи." },
    { en = "After $1215824w3 sec of combat, party members and Brann deal $1215814w1% more damage and healing for $1215814d. Can only occur once per combat.", ua = "Через $1215824w3 с бою члени групи та Бранн завдають на $1215814w1% більше шкоди й зцілення протягом $1215814d. Може статися лише раз за бій." },
    { en = "After $1215823w3 sec of combat, party members and Brann deal $1215817w1% more damage and healing for $1215817d. Can only occur once per combat.", ua = "Через $1215823w3 с бою члени групи та Бранн завдають на $1215817w1% більше шкоди й зцілення протягом $1215817d. Може статися лише раз за бій." },
    { en = "After $1215822w3 sec of combat, party members and Brann deal $1215816w1% more damage and healing for $1215816d. Can only occur once per combat.", ua = "Через $1215822w3 с бою члени групи та Бранн завдають на $1215816w1% більше шкоди й зцілення протягом $1215816d. Може статися лише раз за бій." },
    { en = "Upon entering combat, Brann activates the conversion matrix for $w2 sec. A small percent of all party damage dealt during this time is converted to primary stat and split between party members.\n\nAfter the conversion matrix powers down, the primary stat buff persists for $w3 sec.", ua = "Вступаючи в бій, Бранн активує матрицю перетворення на $w2 с. Невеликий відсоток усієї шкоди, завданої групою за цей час, перетворюється на основну характеристику й розподіляється між членами групи.\n\nКоли матриця перетворення вимикається, підсилення основної характеристики зберігається ще $w3 с." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nUpon expiration, $@spellname1269631s launch from the player's location.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля завершення з місця гравця вилітають $@spellname1269631." },
    { en = "Inflicts $1283371s2 Nature damage every $t2 sec.\n\nRemoved by $@spellname1253977.", ua = "Завдає $1283371s2 шкоди від сил природи кожні $t2 с.\n\nЗнімається за допомогою $@spellname1253977." },
    { en = "inflicting $1216143s1 Fire damage to all players every $t1 sec.", ua = "завдаючи $1216143s1 вогняної шкоди всім гравцям кожні $t1 с." },
    { en = "$s2% increased damage taken from Unstable Explosion.", ua = "Шкода від «Нестійкого Вибуху» збільшена на $s2%." },
    { en = "Inflicts $1216446s1 Nature damage to all players every $t1 sec.", ua = "Завдає $1216446s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "Coughing, inflicting $s1 Nature damage every $t1 sec.", ua = "Кашель: завдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Wrench damage taken increased by $s2%.", ua = "Отримувана шкода від «Гайкового ключа» збільшена на $s2%." },
    { en = "Damage done increased by $w1%.\nMovement speed reduced by $w4%.", ua = "Завдавана шкода збільшена на $w1%.\nШвидкість пересування знижена на $w4%." },
    { en = "Contact with players afflicted with $@spellname1216934 will trigger a $@spellname1216965.", ua = "Контакт із гравцями під дією $@spellname1216934 спричинить $@spellname1216965." },
    { en = "Contact with players afflicted with $@spellname1216911 will trigger a $@spellname1216965.", ua = "Контакт із гравцями під дією $@spellname1216911 спричинить $@spellname1216965." },
    { en = "$?a1219022[Inflicting $1217126s1 Nature damage every $1217120t1 sec. Damage taken by Lingering Voltage increased by $s2%.][Damage taken by Lingering Voltage increased by $s2%.]", ua = "$?a1219022[Завдає $1217126s1 шкоди від сил природи кожні $1217120t1 с. Шкода від «Залишкової напруги» збільшена на $s2%.][Шкода від «Залишкової напруги» збільшена на $s2%.]" },
    { en = "Stunned.\nBleeding for $s2 Physical damage every $t2 sec.", ua = "Приголомшено.\nКровотеча завдає $s2 фізичної шкоди кожні $t2 с." },
    { en = "$s2% increased Fire damage taken.", ua = "Отримувана шкода вогнем збільшена на $s2%." },
    { en = "Damage taken increased by $s1%. Cannot be absorbed by Rolling Rubbish.", ua = "Отримувана шкода збільшена на $s1%. Не поглинається «Котливим сміттям»." },
    { en = "$1217964s1 Nature damage inflicted every $t1 sec.", ua = "Завдає $1217964s1 шкоди від сил природи кожні $t1 с." },
    { en = "$s2 Fire damage inflicted every $t2 sec.\nDamage taken from $@spellname464865 increased by $s1%.", ua = "Завдає $s2 шкоди вогнем кожні $t2 с.\nШкода від $@spellname464865 збільшена на $s1%." },
    { en = "Movement speed increased by $s1%.\nDamage taken by $@spellname1219223 reduced by $s2%.", ua = "Швидкість пересування збільшена на $s1%.\nОтримувана шкода від $@spellname1219223 зменшена на $s2%." },
    { en = "$s2% increased damage taken from Unstable Shrapnel.", ua = "Шкода від «Нестабільної шрапнелі» збільшена на $s2%." },
    { en = "Taking a few precious moments to aim a murderous shot.", ua = "Витрачає кілька дорогоцінних митей, щоб прицілитися для вбивчого пострілу." },
    { en = "Marked with the scent of prey. Other creatures will not hesitate to strike.", ua = "Позначено запахом здобичі. Інші істоти не вагатимуться напасти." },
    { en = "Being Hypercharged by a Prototype Powercoil.\n\n$1218706s1 Nature damage inflicted every $1218704t1 sec.", ua = "Гіперзаряджено прототипом котушки живлення.\n\nЗавдає $1218706s1 шкоди від сил природи кожні $1218704t1 с." },
    { en = "Damage taken from Prototype Powercoil increased by $s1%.", ua = "Шкода від «Прототипу котушки живлення» збільшена на $s1%." },
    { en = "Roasting nearby enemies, inflicting Fire damage every $t1 sec.", ua = "Підсмажує ворогів поблизу, завдаючи шкоди вогнем кожні $t1 с." },
    { en = "$1218989s1 Nature damage every $1218992T2 sec.\nCarrying a Discharged Giga Bomb.", ua = "$1218989s1 шкоди від сил природи кожні $1218992T2 с.\nНесе розряджену гіга-бомбу." },
    { en = "Movement speed reduced by $s2%.\n$s1 Nature damage every $T1 sec.", ua = "Швидкість пересування знижена на $s2%.\n$s1 шкоди від сил природи кожні $T1 с." },
    { en = "$s2% increased damage taken from Unstable Explosion and Polarized Catastro-Blast", ua = "Шкода від «Нестійкого Вибуху» та «Поляризованого катастро-вибуху» збільшена на $s2%" },
    { en = "Absorbing ${$w1} damage and dealing ${$w3} Nature damage to nearby enemies every $1221146t1 sec.", ua = "Поглинає ${$w1} шкоди та завдає ${$w3} шкоди від сил природи ворогам поблизу кожні $1221146t1 с." },
    { en = "Targeted for $@spellname1219263.", ua = "Обрано ціллю: $@spellname1219263." },
    { en = "Inflicting $1219280s1 Nature damage to targted players and additional players between them and Gallywix.", ua = "Завдає $1219280s1 шкоди від сил природи цільовим гравцям і гравцям між ними та Ґаллівіксом." },
    { en = "Immune to all damage.\n\nUpon reaching 100 energy, the mine becomes immune to crowd control effects and gains $1225928s1% movement speed.", ua = "Несприйнятливість до будь-якої шкоди.\n\nДосягнувши 100 енергії, міна стає несприйнятливою до ефектів контролю та отримує $1225928s1% швидкості пересування." },
    { en = "Stunned.\n$1219322s1 Nature damage every $1219319T1 sec.", ua = "Приголомшено.\n$1219322s1 шкоди від сил природи кожні $1219319T1 с." },
    { en = "Explodes for $s1 Nature damage to all players upon expiration, decreasing in damage as distance increases.", ua = "Після завершення вибухає, завдаючи $s1 природної шкоди всім гравцям; шкода зменшується з відстанню." },
    { en = "Inflicting $s1 Arcane Damage every $t1 sec.\nMovement Speed reduced by $s2%.", ua = "Завдає $s1 арканної шкоди кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Taah'bat and A'wazj are bonded, causing them to share all damage taken.", ua = "Таа'бат і А'вадж пов'язані, тож вони ділять усю отриману шкоду." },
    { en = "Inflicting $1226752s1 Arcane damage every $t1 sec for $d.", ua = "Завдає $1226752s1 арканної шкоди кожні $t1 с протягом $d." },
    { en = "Transformed into a powerful Fire Ascendant, empowering your Mastery: Elemental Overload.$?$w3>0[\n\nHaste increased by $w3%.][]", ua = "Перетворено на могутнього Вознесенця вогню, що підсилює твою «Майстерність: Стихійне перевантаження».$?$w3>0[\n\nПоспіх збільшено на $w3%.][]" },
    { en = "Targeted for Eradicating Salvo.", ua = "Обрано ціллю: «Залп винищення»." },
    { en = "Gains a stack of $@spellname1220290 every $1220290T1 sec.\nUpon reaching $1220290w2 stacks or when changing primary target all shots release inflicting $1220353s1 Physical damage  and an additional $1226288s1 Fire damage every $1220375T1 sec for $1220375D, each.", ua = "Отримує заряд $@spellname1220290 кожні $1220290T1 с.\nДосягнувши $1220290w2 зарядів або змінивши основну ціль, випускає всі постріли: кожен завдає $1220353s1 фізичної шкоди та додатково $1226288s1 вогняної шкоди кожні $1220375T1 с протягом $1220375D." },
    { en = "Radiating $w1 Nature damage to targeted players every $1220669T1 sec for each Sabotaged Control.", ua = "Випромінює $w1 шкоди від сил природи на обраних гравців кожні $1220669T1 с за кожне «Саботоване керування»." },
    { en = "Anchored to a javelin!\n$1239487s1 Arcane damage inflicted every $t3 sec.\nMovement speed reduced by $s2%.", ua = "Прикуто до дротика!\nЗавдає $1239487s1 арканної шкоди кожні $t3 с.\nШвидкість пересування знижена на $s2%." },
    { en = "Absorbs $w1 healing.\nExplodes for Shadow damage when removed.", ua = "Поглинає $w1 зцілення.\nПісля зняття вибухає, завдаючи шкоди від тіні." },
    { en = "Unable to drop or pick up Giga Bombs.\nExplodes for $1220791s1 Fire damage to all players upon removal.", ua = "Не може скидати чи підбирати Гіга-бомби.\nПісля зняття вибухає, завдаючи $1220791s1 вогняної шкоди всім гравцям." },
    { en = "Interrupts Gallywix's Giga Coils.", ua = "Перериває «Гіга-котушки» Ґаллівікса." },
    { en = "Chance to apply movement-triggered area-damage to your target as you attack it. Persists through death.", ua = "Шанс під час атаки накласти на ціль ефект шкоди по області, що спрацьовує від руху. Зберігається після смерті." },
    { en = "$?|diff16 [Increases damage taken from $@spellname1221477 by $s1% and $@spellname1225127 by $s2%.][Increases damage taken from $@spellname1221477 by $s1%.]", ua = "$?|diff16 [Збільшує шкоду від $@spellname1221477 на $s1%, а від $@spellname1225127 — на $s2%.][Збільшує шкоду від $@spellname1221477 на $s1%.]" },
    { en = "Damage increased by $s2% and movement speed increased by $s3%. Immune to crowd control effects and interrupts.", ua = "Шкода збільшена на $s2%, а швидкість пересування — на $s3%. Імунітет до ефектів контролю та переривань." },
    { en = "Inflicts $1221824s1 Fire and $1221825s2 Nature damage every $t1 sec.", ua = "Завдає $1221824s1 шкоди вогнем і $1221825s2 шкоди від сил природи кожні $t1 с." },
    { en = "Inflicts $s3 Nature damage every $t3 sec and decreasing movement speed by $s2%.\n\nUpon expiration inflicts $1222122s1 Nature damage to players within $1222122a1 yards and leaves behind $@spellname1222129.", ua = "Завдає $s3 шкоди від сил природи кожні $t3 с. і знижує швидкість пересування на $s2%.\n\nПісля завершення дії завдає $1222122s1 шкоди від сил природи гравцям у радіусі $1222122a1 м і лишає по собі $@spellname1222129." },
    { en = "$1222284s1 Nature damage inflicted to all players every $t1 sec.", ua = "Завдає $1222284s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "You have become the target of Adarus' $@spellname1222244. Increases Physical damage taken by $s3%.\n\nUpon removal, $@spellname1222057 transfers to the nearest player without $@spellname1222310 and inflicts $1226539s1 Cosmic damage to all players.", ua = "Ти став ціллю Адаруса: $@spellname1222244. Отримувана фізична шкода збільшена на $s3%.\n\nПісля зняття $@spellname1222057 переходить на найближчого гравця без ефекту $@spellname1222310 і завдає $1226539s1 космічної шкоди всім гравцям." },
    { en = "Damage and healing absorb taken from $@spellname1222244 increased by $s1%.", ua = "Шкода та поглинання зцілення від «$@spellname1222244» збільшені на $s1%." },
    { en = "Damage taken reduced by $s1%.\n\nRemoved by being hit with $@spellname466509.", ua = "Отримувана шкода зменшена на $s1%.\n\nЗнімається влучанням «$@spellname466509»." },
    { en = "$@spellname262161 inflicts ${$s1}.2% increased damage.\n\nIncreases $@spellname167105 duration by ${$S2/1000}.2 sec.", ua = "$@spellname262161 завдає на ${$s1}.2% більше шкоди.\n\nЗбільшує тривалість $@spellname167105 на ${$S2/1000}.2 с." },
    { en = "Critically blocking all incoming attacks, and inflicting $1223269s1 Shadowflame damage to all enemies in a $1223269A1 yard cone every $t2 sec.", ua = "Критично блокує всі вхідні атаки та завдає $1223269s1 шкоди Тіньовим Полум'ям усім ворогам у конусі $1223269A1 м кожні $t2 с." },
    { en = "Ejecting $@spellname1219687 at a player every $t1 sec.", ua = "Викидає «$@spellname1219687» у гравця кожні $t1 с." },
    { en = "Utilizing expert skinning knowledge and processes to guarantee a hide or scale from your next Midnight skinning attempt.", ua = "Використовуєш фахові знання й прийоми білування, щоб гарантовано отримати шкуру або луску з наступної спроби білування в Опівночі." },
    { en = "Mulch is prepared and ready for use, guaranteeing high-quality herbs on your next herb gathered. You can only use one Mulch at a time.", ua = "Мульчу підготовлено й готово до використання: наступна зібрана трава гарантовано буде високої якості. Одночасно можна використовувати лише одну Мульчу." },
    { en = "Mulch is prepared and ready for use, guaranteeing you rare reagents on your next herb gathered. You can only use one Mulch at a time.", ua = "Мульчу підготовлено й готово до використання: наступна зібрана трава гарантовано дасть рідкісні реагенти. Одночасно можна використовувати лише одну Мульчу." },
    { en = "Mulch is prepared and ready for use, guaranteeing Finesse on your next Midnight herb gathered. You can only use one Mulch at a time.", ua = "Мульчу підготовлено й готово до використання: наступна зібрана трава Опівночі гарантовано дасть Витонченість. Одночасно можна використовувати лише одну Мульчу." },
    { en = "Inflicting $s3 Arcane damage every $t3 sec.", ua = "Завдає $s3 арканної шкоди кожні $t3 с." },
    { en = "|cFF00AA99Bonus Event: Battle for Azeroth Timewalking|r\n\nBattle for Azeroth reputation gains from combat and quests increased by $s1%.", ua = "|cFF00AA99Бонусна подія: Мандри в часі Битви за Азерот|r\n\nПриріст репутації Битви за Азерот від боїв і завдань збільшено на $s1%." },
    { en = "$s1% of damage taken is inflicted to other Gemellus.", ua = "$s1% отриманої шкоди передається іншим Гемеллусам." },
    { en = "You are one of the devout.", ua = "Ти — один із відданих." },
    { en = "Inflicting $s2 Shadow damage every $t2 sec.\n\nUpon expiration creates $@spellname1224104.", ua = "Завдає $s2 шкоди від тіні кожні $t2 с.\n\nПісля завершення дії створює $@spellname1224104." },
    { en = "$s1 Shadow damage inflicted every $t1 sec and being pulled towards a Gemellus.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с і притягує до Гемеллуса." },
    { en = "Sworn under ethereal oath and vulnerable to conversion into $@spellname1224767.\n\nRemoved by surviving Conquer.", ua = "Скуто ефіріальською присягою; вразливість до перетворення на $@spellname1224767.\n\nЗнімається, якщо пережити «Підкорення»." },
    { en = "Serving the King.", ua = "Служить Королю." },
    { en = "Inflicting $1224825s1 Shadow damage to all players every $t1 sec.", ua = "Завдає $1224825s1 тіньової шкоди всім гравцям кожні $t1 с." },
    { en = "Targeted for $@spellname1224827.", ua = "Обрано ціллю: $@spellname1224827." },
    { en = "Void-Touched fragments collected from enemies.", ua = "Уламки, торкнуті Порожнечею, зібрані з ворогів." },
    { en = "Inflicts $1225155s1 Chaos damage to all players every $t1 sec.", ua = "Завдає $1225155s1 шкоди від хаосу всім гравцям кожні $t1 с." },
    { en = "Absorbing ambient Void energy that may erupt at any time.", ua = "Вбирає навколишню енергію Порожнечі, що може вирватися будь-якої миті." },
    { en = "$s1 healing absorbed.", ua = "Поглинає $s1 зцілення." },
    { en = "$?PC154828[|cnIQ1:- Basic Dive Suit|R][]$?PC154829[|cnIQ2:- Reinforced Joints Suit|R][]$?PC154830[|cnIQ3:- Depth-Greased Suit|R][]$?PC154832[|cnIQ4:- Pahk Trench Fins Suit|R][]\nSwim Speed +$w1%\n$?PC154836[\n|cnIQ1:- Basic Breath Tank|R\nMax Oxygen $1224700m6 units\n][]$?PC154835[\n|cnIQ2:- Depthdiver's Used Tank|R\nMax Oxygen $1271613m6 units\n][]$?PC154834[\n|cnIQ3:- Fathom-Tested Tank|R\nMax Oxygen $1271614m6 units\n][]$?PC154833[\n|cnIQ4:- Nalorakk's Breath Tank|R\nMax Oxygen $1271615m6 units\n][]$?PC154840[\n|cnIQ1:- Basic Bait|R\nCommon Fishable Creatures\n][]$?PC154839[\n|cnIQ2:- Finnow Chum Bait|R\nUncommon Fishable Creatures\n][]$?PC154838[\n|cnIQ3:- Plecofin Bait|R\nRare Fishable Creatures\n][]$?PC154837[\n|cnIQ4:- Murkskimmer Meat Bait|R\nEpic Fishable Creatures\n][]$?PC159072[\n|cnIQ2:- Shallows Net|R\nBarbed Crawlers and Thorny Seahorses\n][]$?PC152527[\n|cnIQ3:- Triple-Thread Net|R\nAll Small Creatures\n][]$?PC155370[\n|cnIQ4:- Pressurized Eyeglass|R\nAncient Relics discoverable][]", ua = "$?PC154828[|cnIQ1:- Базовий водолазний костюм|R][]$?PC154829[|cnIQ2:- Костюм із посиленими з'єднаннями|R][]$?PC154830[|cnIQ3:- Костюм із глибинним мастилом|R][]$?PC154832[|cnIQ4:- Костюм із ластами западини Пак|R][]\nШвидкість плавання +$w1%\n$?PC154836[\n|cnIQ1:- Базовий кисневий балон|R\nМакс. кисень: $1224700m6 од.\n][]$?PC154835[\n|cnIQ2:- Використаний балон глибоководного нурця|R\nМакс. кисень: $1271613m6 од.\n][]$?PC154834[\n|cnIQ3:- Перевірений глибиною балон|R\nМакс. кисень: $1271614m6 од.\n][]$?PC154833[\n|cnIQ4:- Кисневий балон Налоракка|R\nМакс. кисень: $1271615m6 од.\n][]$?PC154840[\n|cnIQ1:- Базова наживка|R\nЗвичайні виловлювані істоти\n][]$?PC154839[\n|cnIQ2:- Наживка з фіннова|R\nНезвичайні виловлювані істоти\n][]$?PC154838[\n|cnIQ3:- Наживка з плекоплавця|R\nРідкісні виловлювані істоти\n][]$?PC154837[\n|cnIQ4:- Наживка з м'яса мулосковзача|R\nЕпічні виловлювані істоти\n][]$?PC159072[\n|cnIQ2:- Сітка для мілководдя|R\nКолючі повзуни та колючі морські коники\n][]$?PC152527[\n|cnIQ3:- Триниткова сіть|R\nУсі дрібні істоти\n][]$?PC155370[\n|cnIQ4:- Герметична лупа|R\nМожна знаходити стародавні реліквії][]" },
    { en = "Inflicting $1249065s1 Arcane damage every $1249065t1 sec.", ua = "Завдає $1249065s1 арканної шкоди кожні $1249065t1 с." },
    { en = "$1225210s1  Shadow damage inflicted to all players every $t1.", ua = "Завдає $1225210s1  шкоди від тіні всім гравцям кожні $t1." },
    { en = "Inflicting $1225796s1 Arcane damage to players within $1225796A2 yards every $t2 sec.", ua = "Завдає $1225796s1 арканної шкоди гравцям у межах $1225796A2 м кожні $t2 с." },
    { en = "Prepared to butcher the next Midnight creature you skin, guaranteeing meat for use in cooking.", ua = "Підготовлено до розбирання наступної білуваної істоти Опівночі: гарантовано отримаєш м'ясо для кулінарії." },
    { en = "Inflicts $1238197s1 Arcane damage every $t1 sec, increasing in strength.\n\nEffect ends once far enough from the caster.", ua = "Завдає $1238197s1 арканної шкоди кожні $t1 с., дедалі сильнішої.\n\nЕфект завершується, щойно ти відійдеш достатньо далеко від заклинача." },
    { en = "Inflicting $1226363s1 Cosmic damage every $t1 sec for $d.", ua = "Завдає $1226363s1 космічної шкоди кожні $t1 с протягом $d." },
    { en = "Movement speed reduced by $s1%.\nInflicts $s2 Nature damage every sec.", ua = "Швидкість пересування знижена на $s1%.\nЗавдає $s2 шкоди від сил природи щосекунди." },
    { en = "Reshanor's presence manifests a voidstorm.", ua = "Присутність Решанора породжує «Войдшторм»." },
    { en = "Increases damage taken from $@spellname1222337 by $s2%.", ua = "Збільшує отримувану шкоду від $@spellname1222337 на $s2%." },
    { en = "Selfies are much more dangerous within the Slayer's Rise.", ua = "На Височині Вбивць селфі значно небезпечніші." },
    { en = "Your next Crusading Strikes will generate Holy Power.", ua = "Твої наступні «Хрестоносні удари» породять Святу силу." },
    { en = "$?diff16[Inflicting $s4 Arcane damage every $t4 sec, reducing movement speed by $s2% and haste by $s1%.][Inflicting $1225629s1 Arcane damage every $t2 sec for $d, and reducing movement speed by $s1%.]", ua = "$?diff16[Завдає $s4 арканної шкоди кожні $t4 с, знижує швидкість пересування на $s2%, а Поспіх — на $s1%.][Завдає $1225629s1 арканної шкоди кожні $t2 с протягом $d і знижує швидкість пересування на $s1%.]" },
    { en = "You live here!\n\nThis allows you to receive credit for endeavor tasks inside the neighborhood.", ua = "Ти живеш тут!\n\nЦе дозволяє тобі отримувати залік за завдання ініціатив у межах Сусідства." },
    { en = "$s3 Shadow damage every $t3 sec.", ua = "$s3 шкоди від тіні кожні $t3 с." },
    { en = "Targeted by Soulfray Annihilation", ua = "Обрано ціллю: «Анігіляція Зношеної Душі»" },
    { en = "Knocks back the current enemy target, dealing $s3 Arcane damage. Knockback is more effective against players.", ua = "Відкидає поточну ворожу ціль, завдаючи $s3 арканної шкоди. Відкидання дієвіше проти гравців." },
    { en = "$s1 Shadow damage is inflicted every $t1 sec.\n$@spellname1227378 is applied upon expiration.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля завершення накладає $@spellname1227378." },
    { en = "A Hungering Presence seeks to end you. Fly!", ua = "«Голодна Присутність» прагне тебе знищити. Лети геть!" },
    { en = "Swipes at the target with its claws, inflicting $s1 Physical damage.", ua = "Б'є ціль пазурами, завдаючи $s1 фізичної шкоди." },
    { en = "Let out a shriek, causing $i enemies within $A1 yds to flee in fear for $d. Damage may cancel the effect.", ua = "Здіймає пронизливий вереск, що змушує $i ворогів у радіусі $A1 яр. тікати в жаху на $d. Шкода може скасувати ефект." },
    { en = "Melee attacks inflict $1227665s1 additional Shadow damage to players near the target and knock them away.", ua = "Атаки ближнього бою завдають додатково $1227665s1 шкоди від тіні гравцям поруч із ціллю та відкидають їх." },
    { en = "Apply the dragonhawk ash oil coating to preserve the Light in the lightwood.", ua = "Нанеси шар олії з попелу драконояструба, щоб зберегти Світло у світлодереві." },
    { en = "Tearing itself apart.", ua = "Роздирає себе на шматки." },
    { en = "Arcane erupts at your location every $t1 sec.", ua = "У місці, де ти стоїш, кожні $t1 с вибухає арканна енергія." },
    { en = "Carrying Excess Mass.", ua = "Несе Надлишкову масу." },
    { en = "Increased resistance to being Devoured.\n\nMovement speed reduced by $s2%.", ua = "Підвищений опір до «Пожирання».\n\nШвидкість пересування знижена на $s2%." },
    { en = "Inflicts $1244998s1 Arcane damage every $t1 sec.\nOn expiration, summons an $@spellname1228211.", ua = "Завдає $1244998s1 арканної шкоди кожні $t1 с.\nПісля завершення дії прикликає $@spellname1228211." },
    { en = "Unable to reduce the damage of the next $@spellname1228218.", ua = "Не може зменшити шкоду від наступного застосування $@spellname1228218." },
    { en = "Inflicting $1228368s1 Cosmic damage to all players every $t1 sec.", ua = "Завдає $1228368s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "|CFF20FF20Tier 1|R\n\nHarvest materials to increase stats.\nDeposit materials to upgrade this Blessing.\n\n+$w1% Movement Speed\n+$w2% $pri\n+$w3 Pickup Yard Radius\n\n|CFF9d9d9dContribute more Abundance at an Altar to reach the next tier (Current: $@cdataelem78/1000)|R", ua = "|CFF20FF20Рівень 1|R\n\nЗбирай матеріали, щоб збільшити характеристики.\nЗдавай матеріали, щоб покращити це Благословення.\n\n+$w1% до швидкості пересування\n+$w2% $pri\n+$w3 м до радіусу підбирання\n\n|CFF9d9d9dВнеси більше Рясності біля Вівтаря, щоб досягти наступного рівня (Зараз: $@cdataelem78/1000)|R" },
    { en = "Dimensius instantly devours any player who enters his body.", ua = "Діменсіус миттєво пожирає будь-якого гравця, що потрапляє в його тіло." },
    { en = "Devour kills players with less than $w1 $@spellname1228207.", ua = "«Пожирання» вбиває гравців, у яких менше ніж $w1 «$@spellname1228207»." },
    { en = "Increases your &pri by $w1.", ua = "Збільшує твій &pri на $w1." },
    { en = "Infused with Fel magic, turning hostile to players while above $s1% health.", ua = "Насичений магією Скверни: ворожий до гравців, поки здоров'я вище $s1%." },
    { en = "Spaghettified by a Black Hole.", ua = "Спагетифіковано Чорною Дірою." },
    { en = "Absorbs $w1 damage. Your spells and abilities have a chance to deal $1230813s1 additional Holy damage to nearby targets.", ua = "Поглинає $w1 шкоди. Твої закляття та здібності мають шанс завдати $1230813s1 додаткової шкоди від Світла цілям поблизу." },
    { en = "$s1 Cosmic damage inflicted every $t1 sec.\nDamage taken increased by $s2%.\nMovement speed reduced by $s3%.", ua = "Завдає $s1 космічної шкоди кожні $t1 с.\nОтримувана шкода збільшена на $s2%.\nШвидкість пересування знижена на $s3%." },
