    { en = "Absorbs $w1 healing and inflicts $w2 Holy damage every $t2 sec until the burn is fully healed.", ua = "Поглинає $w1 зцілення та завдає $w2 шкоди від Світла кожні $t2 с, доки опік не буде повністю зцілено." },
    { en = "$1244672s1 Shadow damage every $1244672T1 sec.", ua = "$1244672s1 шкоди від тіні кожні $1244672T1 с." },
    { en = "Swing the hammer around yourself, inflicting massive damage in an area around you, stunning and knocking back enemies.", ua = "Розмахніться молотом навколо себе, завдаючи величезної шкоди по площі довкола вас, приголомшуючи та відкидаючи ворогів." },
    { en = "Inflicts $1245302s1 Shadow damage to players within $1245302A1 yards.", ua = "Завдає $1245302s1 шкоди від тіні гравцям у радіусі $1245302A1 м." },
    { en = "Lowest secondary stat increased by $w5.", ua = "Найнижча другорядна характеристика збільшена на $w5." },
    { en = "Throw the Improvised Arcane Device.", ua = "Кидає імпровізований арканний пристрій." },
    { en = "Taking $1s Shadow Damage every $1p sec.\nSlowed $2s%.", ua = "Отримує $1s тіньової шкоди кожні $1p с.\nСповільнено на $2s%." },
    { en = "Inflicting $1273112s1 Nature damage every $t1 sec to all players.", ua = "Завдає $1273112s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "$1245421s1 Shadow damage every $1245421T1 sec.\nMovement speed reduced by $1245421s2%.", ua = "$1245421s1 шкоди від тіні кожні $1245421T1 с.\nШвидкість пересування знижена на $1245421s2%." },
    { en = "Damage taken increased by $1245522s1%.\n\nThis effect stacks every $t1 sec, except while in rested areas.", ua = "Отримувана шкода збільшена на $1245522s1%.\n\nЦей ефект накопичується кожні $t1 с, окрім перебування в зонах відпочинку." },
    { en = "$1283712s1 Shadow damage every $1245554T1 sec.", ua = "$1283712s1 шкоди від тіні кожні $1245554T1 с." },
    { en = "Melee attacks additionally absorb $1280355s1 healing.", ua = "Атаки ближнього бою додатково поглинають $1280355s1 зцілення." },
    { en = "Able to see Manifestations in the Aln.", ua = "Можеш бачити Прояви в Альні." },
    { en = "Absorbing $w1 damage.\nUpon removal, enters Reality.", ua = "Поглинає $w1 шкоди.\nПісля зняття входить у Реальність." },
    { en = "Taking $s2 Shadow damage every $t2 sec.", ua = "Отримує $s2 тіньової шкоди кожні $t2 с." },
    { en = "Melee attacks apply $@spellname1246145.", ua = "Атаки ближнього бою накладають $@spellname1246145." },
    { en = "$s3 Shadow damage inflicted every $t3 sec.\n\nConsigned to Oblivion upon reaching $s2 applications.", ua = "Завдає $s3 шкоди від тіні кожні $t3 с.\n\nЗа $s2 зарядів відправляє в Забуття." },
    { en = "Reduces all damage taken by allies within $s1 yds by $1246165s2%.", ua = "Зменшує всю шкоду, отримувану союзниками в радіусі $s1 м, на $1246165s2%." },
    { en = "Inflicting $1254018s1 Shadow damage every $1254019t1 sec.\nDamage taken increased by $s5%.", ua = "Завдає $1254018s1 тіньової шкоди кожні $1254019t1 с.\nОтримувана шкода збільшена на $s5%." },
    { en = "Rooted.\nImmune to player effects.", ua = "Знерухомлено.\nІмунітет до ефектів гравців." },
    { en = "Immune to all damage and harmful effects.", ua = "Несприйнятливість до будь-якої шкоди та шкідливих ефектів." },
    { en = "All damage done increased by $s1%.\nAll damage taken increased by $s3%.", ua = "Уся завдавана шкода збільшена на $s1%.\nУся отримувана шкода збільшена на $s3%." },
    { en = "Cannot be affected by Avenging Wrath or Divine Shield.", ua = "Не підпадає під дію «Гніву месника» чи «Божественного щита»." },
    { en = "$@spellname1251812 damage taken increased by $s2%.", ua = "Шкода від $@spellname1251812 збільшена на $s2%." },
    { en = "Inflicting $1245122s1 Chaos damage to players within $1245122a1 yards every $1245116t1 sec.", ua = "Завдає $1245122s1 шкоди Хаосу гравцям у межах $1245122a1 м кожні $1245116t1 с." },
    { en = "$w1 damage absorbed.\nInflicting $1246925s1 Shadow damage to all players every $t2 sec.", ua = "Поглинає $w1 шкоди.\nЗавдає $1246925s1 шкоди від тіні всім гравцям кожні $t2 с." },
    { en = "Ready to fire a Shooting Star.", ua = "Готово випустити «Падучу зорю»." },
    { en = "Increases the damage taken by $@spellname1247672 by $s1%.", ua = "Збільшує шкоду, отримувану від $@spellname1247672, на $s1%." },
    { en = "Absorbing $w1 damage.\nDamage done increased by $s2%.", ua = "Поглинає $w1 шкоди.\nЗавдавана шкода збільшена на $s2%." },
    { en = "Damage done increased by $s1%.\nHealing done increased by $s2%.\n$s3 Holy damage inflicted every $t3 sec.", ua = "Завдавана шкода збільшена на $s1%.\nЗцілення збільшене на $s2%.\n$s3 священної шкоди кожні $t3 с." },
    { en = "Inflicting $1247644s1 Holy damage to all players every $t1 sec.", ua = "Завдає $1247644s1 святої шкоди всім гравцям кожні $t1 с." },
    { en = "Increases damage taken from standing in the path of $@spellname1227846 by $s1%.", ua = "Збільшує отримувану шкоду від перебування на шляху $@spellname1227846 на $s1%." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec.\n$@spellname1247495 is triggered upon expiration.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля завершення дії спрацьовує $@spellname1247495." },
    { en = "Inflicts $s2 Nature damage every $t2 sec. for $d.", ua = "Завдає $s2 шкоди від сил природи кожні $t2 с. протягом $d." },
    { en = "Survival is still possible.", ua = "Вижити ще можливо." },
    { en = "Increases Holy damage of allies within $s2 yds by $1248450s1%.", ua = "Збільшує святу шкоду союзників у межах $s2 м на $1248450s1%." },
    { en = "Protects all allies within $s2 yds with a calming aura. Players who directly attack a protected ally are pacified for $1250812d.", ua = "Захищає всіх союзників у радіусі $s2 м заспокійливою аурою. Гравців, які безпосередньо атакують захищеного союзника, утихомирено на $1250812d." },
    { en = "Holding wine. Bring it to an Irritated Noble to appease them.", ua = "Тримаєш вино. Віднеси його Роздратованому вельможі, щоб його вгамувати." },
    { en = "Grinding herbs.", ua = "Перетирає трави." },
    { en = "Pouring.", ua = "Вливає." },
    { en = "Attack speed increased by $s1%.\nAuto attacks inflict an additional $1271317s1 Arcane damage.", ua = "Швидкість атаки збільшена на $s1%.\nАвтоатаки завдають додатково $1271317s1 арканної шкоди." },
    { en = "Inflicting $1260835s1 Shadow damage to players within $1260835a1 yd every $t1 sec.", ua = "Завдає $1260835s1 тіньової шкоди гравцям у межах $1260835a1 м кожні $t1 с." },
    { en = "Absorbs $w1 Healing received.", ua = "Поглинає $w1 отримуваного зцілення." },
    { en = "Radiating $1249595s1s1 absorb every $1248847T2 sec, divided amongst nearby players.", ua = "Випромінює $1249595s1s1 поглинання кожні $1248847T2 с, розподіляючи його між гравцями поблизу." },
    { en = "When any party member's health falls below $w1% during combat, the mantle grants them an absorb shield equal to $w2% of their maximum health.\n\nEnemies near the shielded ally and active companion are knocked up and take $w3% more damage for $w4 sec.\n\nCan only occur every $1255774d.", ua = "Коли здоров'я будь-якого члена групи в бою падає нижче $w1%, мантія дає йому поглинальний щит, що дорівнює $w2% його максимального здоров'я.\n\nВорогів поруч із захищеним союзником та активним супутником підкидає в повітря, і вони отримують на $w3% більше шкоди протягом $w4 с.\n\nМоже спрацьовувати лише раз на $1255774d." },
    { en = "Your companion has a chance to gain Sanctum's Blessings through combat, as well as by slaying foes. Elite enemies grant $w4, while normal foes yield $w3.\n\nEach blessing grants $w1% increased healing and damage. Upon reaching $w6, your companion converts $w2% of their current health into an absorb shield that increases blessing bonuses while active.", ua = "Твій супутник може отримувати Благословення Святилища в бою, а також убиваючи ворогів. Елітні вороги дають $w4, звичайні — $w3.\n\nКожне благословення збільшує зцілення та шкоду на $w1%. Досягнувши $w6, твій супутник перетворює $w2% свого поточного здоров'я на поглинальний щит, який збільшує бонуси благословень, поки діє." },
    { en = "Your companion has a chance during combat to afflict an enemy with Nether Entropy causing them to take moderate Void damage over $w3 sec.\n\nEach time Nether Entropy deals damage it has a $w5% chance to propagate to $w1 nearby enemies, stacking up to $w2 times.", ua = "Твій супутник у бою має шанс уразити ворога «Ентропією Нижнього Світу», через що той зазнає помірної шкоди від Порожнечі протягом $w3 с.\n\nЩоразу, коли «Ентропія Нижнього Світу» завдає шкоди, вона має $w5% шансу поширитися на $w1 ворогів поблизу, накопичуючись до $w2 разів." },
    { en = "Standing still during combat gain stacks of Cosmic Momentum every $t5 sec up to $w2. Each stack increases your movement speed by $w1%.\n\nJumping while at $w2 stacks consumes them to grant you $w3% Haste per stack for $w4 sec and knocks up surrounding enemies.\n\nCan only occur every $1256628d.", ua = "Стоячи нерухомо в бою, ти отримуєш заряди «Космічного імпульсу» кожні $t5 с, щонайбільше $w2. Кожен заряд збільшує твою швидкість пересування на $w1%.\n\nСтрибок за $w2 зарядів витрачає їх, даючи тобі $w3% Поспіху за заряд на $w4 с і підкидаючи ворогів довкола.\n\nМоже відбуватися не частіше ніж раз на $1256628d." },
    { en = "When your delve companion casts $@spellname1251603, a Sacred Mandate is bestowed upon party members granting their harmful spells and abilities a ${($w5/1000)*100}.1% chance to deal $w3% of the target's maximum health as additional Holy damage per Mandate.\n\nCan only occur once per target every $1261324proccooldown sec.\n\n$@spellicon1251603 $@spellname1251603\n$@spelldesc1251603", ua = "Коли твій супутник у Глибинах творить $@spellname1251603, члени групи отримують Священний Мандат, що дає їхнім шкідливим закляттям і здібностям ${($w5/1000)*100}.1% шансу завдати $w3% максимального здоров'я цілі як додаткову священну шкоду за кожен Мандат.\n\nМоже спрацьовувати лише раз на ціль кожні $1261324proccooldown с.\n\n$@spellicon1251603 $@spellname1251603\n$@spelldesc1251603" },
    { en = "Opening a Mislaid Curiosity summons a Subjugated Burden that worships you during combat, increasing your $pri by $w3%.\n\nYou may have up to $w4 Subjugated Burdens at a time.\nAfter gathering at least $w5 worshipers the amount of granted $pri per Burden is increased.", ua = "Відкриття Загубленої Дивовижі прикликає Підкорену Ношу, яка поклоняється тобі під час бою, збільшуючи $pri на $w3%.\n\nОдночасно можна мати до $w4 Підкорених Нош.\nЗібравши щонайменше $w5 шанувальників, ти збільшуєш приріст $pri від кожної Ноші." },
    { en = "Increases damage done by $@spellname1249207 by $s2%.", ua = "Збільшує шкоду, завдавану $@spellname1249207, на $s2%." },
    { en = "You're marked for $@spellname1249265.", ua = "Тебе позначено: $@spellname1249265." },
    { en = "Assists finding additional gold, ore, herbs, fish, leathers, and treasures.", ua = "Допомагає знаходити більше золота, руди, трав, риби, шкур і скарбів." },
    { en = "Marked with a musical note, inflicting $1249594s1 Cosmic damage every $t1 sec.\n\nUpon activation, triggers either $@spellname1249582 or $@spellname1249584.", ua = "Позначено музичною нотою, що завдає $1249594s1 космічної шкоди кожні $t1 с.\n\nПри активації спричиняє $@spellname1249582 або $@spellname1249584." },
    { en = "Chi costs are reduced by $w7 and Blackout Kick reduces the cooldown of affected abilities by an additional ${$w3/1000} sec.$?$w1>0[\n\nCritical strike chance increased by $w1%.][]", ua = "Вартість у Ці знижена на $w7, а «Удар затемнення» скорочує перезарядження відповідних здібностей ще на ${$w3/1000} с.$?$w1>0[\n\nШанс критичного удару збільшений на $w1%.][]" },
    { en = "Radiates $1250071s1 Shadow damage every $1249748T1 sec.", ua = "Випромінює $1250071s1 тіньової шкоди кожні $1249748T1 с." },
    { en = "Inflicting $1249797s1 Shadow damage to all players every $t1 sec.", ua = "Завдає $1249797s1 тіньової шкоди всім гравцям кожні $t1 с." },
    { en = "Searching for nearby High-Value Beasts.", ua = "Шукає Цінних Звірів поблизу." },
    { en = "You are embraced by the Light, increasing Mastery by $s2.", ua = "Тебе огортає Світло, збільшуючи Майстерність на $s2." },
    { en = "Bleeding for $1250529w1 every $t sec.", ua = "Кровотеча: $1250529w1 шкоди кожні $t с." },
    { en = "A mandate of execution has been placed upon your target, granting you $w3 Haste. Your strikes against your victim grant you stacking Critical Strike.", ua = "На твою ціль накладено мандат страти, що дає тобі $w3 Поспіху. Твої удари по жертві дають тобі Критичний удар, що накопичується." },
    { en = "Absorbing $s2% of incoming damage, up to $w1 total damage.", ua = "Поглинає $s2% вхідної шкоди, загалом до $w1 шкоди." },
    { en = "Airborne players are more difficult to pull down.", ua = "Гравців у повітрі важче стягнути донизу." },
    { en = "Damage dealt by you and your pet is increased by $s1%$?a1256938[ and your attack speed is increased by $s4%][].", ua = "Шкода, яку завдаєте ти і твій улюбленець, збільшена на $s1%$?a1256938[, а твоя швидкість атаки збільшена на $s4%][]." },
    { en = "Taking $s3 Shadow damage every $t3 sec.", ua = "Отримує $s3 тіньової шкоди кожні $t3 с." },
    { en = "Inflicting $1285504s1 Shadow damage every $t sec.", ua = "Завдає $1285504s1 тіньової шкоди кожні $t с." },
    { en = "Damage done is increased by $W1%.", ua = "Завдавана шкода збільшена на $W1%." },
    { en = "Your weapon is poisoned.", ua = "Твою зброю отруєно." },
    { en = "Damage done decreased by $s1%.\nHaste is reduced by $s2%.", ua = "Завдавана шкода зменшена на $s1%.\nПоспіх зменшений на $s2%." },
    { en = "Absorbing $w1 damage.\nImmune to silence and interrupt effects.", ua = "Поглинає $w1 шкоди.\nІмунітет до ефектів безмовності та переривання." },
    { en = "Increases attack speed by $s2%.\nMinimum movement speed increased to $s3%.\nIncreases stacks every $1251686T1 sec.", ua = "Збільшує швидкість атаки на $s2%.\nМінімальну швидкість пересування підвищено до $s3%.\nЗаряди зростають кожні $1251686T1 с." },
    { en = "Shield of the Righteous damage taken increased by $s2%.", ua = "Шкода від «Щита праведника» збільшена на $s2%." },
    { en = "$1285954s1 Shadow damage every $1252157T1 sec.", ua = "$1285954s1 шкоди від тіні кожні $1252157T1 с." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nBeing pulled towards the caster.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nТебе притягує до заклинача." },
    { en = "Chimaerus feasts on any Manifestations in Reality within its reach.", ua = "Хімерус пожирає будь-які Прояви в Реальності, до яких дотягнеться." },
    { en = "Rak'tul inflicts $1248879s1 Shadow damage to all players every $1248863t1 sec and ejects $@spellname1248980s.", ua = "Рак'тул завдає $1248879s1 тіньової шкоди всім гравцям кожні $1248863t1 с і викидає $@spellname1248980." },
    { en = "$@spellname154135's damage increased by $s1%.", ua = "Шкода $@spellname154135 збільшена на $s1%." },
    { en = "Meittik, Kezkitt, and Lekshi are bonded, causing them to share all damage taken.", ua = "Мейттік, Кезкітт і Лекші пов'язані між собою, тому вся отримувана шкода розподіляється між ними." },
    { en = "A creature cannot be captured until all of their Scales have been removed.", ua = "Істоту не можна впіймати, доки з неї не знято всю луску." },
    { en = "Your attacks and abilities have a low chance to beckon a random Loa spirit to your side, increasing your combat capabilities for $1266182d.", ua = "Ваші атаки та здібності мають низький шанс прикликати випадковий дух Лоа до вашого боку, підвищуючи ваші бойові можливості на $1266182d." },
    { en = "Movement speed decreased by $w2%. Haste increased by $w3.", ua = "Швидкість пересування знижена на $w2%. Поспіх збільшений на $w3." },
    { en = "During combat you have a chance to become consumed by Fanatical Inspiration, increasing your highest secondary by $w1 for $1266299d.\n\nParty members also equipped with the keepsake have their lowest secondary increased by $w2 for $1266300d.", ua = "У бою ти маєш шанс піддатися «Фанатичному натхненню», що збільшує твою найвищу другорядну характеристику на $w1 на $1266299d.\n\nЧленам групи, які теж споряджені пам'яткою, найнижчу другорядну характеристику збільшено на $w2 на $1266300d." },
    { en = "Haste and damage done increased by $s1%.\nImmune to interrupts and crowd controlling effects.", ua = "Поспіх і завдавану шкоду збільшено на $s1%.\nНесприйнятливість до переривань та ефектів контролю." },
    { en = "Fixated by a Sunwing.", ua = "На тебе зосередився сонцекрил." },
    { en = "Your next $?c2[Aimed Shot][Wildfire Bomb] deals $?c2[$s1][$s2]% increased direct damage to the marked target.", ua = "Твоє наступне застосування $?c2[«Прицільного пострілу»][«Бомби дикого вогню»] завдає позначеній цілі на $?c2[$s1][$s2]% більше прямої шкоди." },
    { en = "Damage taken from $@spellname1262289 increased by $s1%.", ua = "Шкода від «$@spellname1262289» збільшена на $s1%." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nDamage taken increased by $s3%.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nОтримувана шкода збільшена на $s3%." },
    { en = "Thrash may stack up to $s1 additional times.", ua = "«Молотіння» може накладатися ще до $s1 разів." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nThis effect can be removed by returning to the realm of the living.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nЦей ефект можна зняти, повернувшись до світу живих." },
    { en = "Reducing movement speed of players within $A1 yards by $1254043s1%.\n\nEmpowers players with $@spellname1255629 and fades away upon expiration.", ua = "Знижує швидкість пересування гравців у радіусі $A1 м на $1254043s1%.\n\nПісля завершення підсилює гравців ефектом $@spellname1255629 і зникає." },
    { en = "$@auracaster's healing spells and abilities also heal you for $1255804s2.", ua = "Зцілювальні закляття та здібності $@auracaster також зцілюють тебе на $1255804s2." },
    { en = "You'll find a Hidden Trove at the end of the next Tier 4+ Delve you complete.\n\nHidden Trove's contents depend on the completed Delve Tier.\n\nYou are able to unlock a Hidden Trove.", ua = "Наприкінці наступної пройденої Глибини Складності 4+ ти знайдеш Прихований Скарб.\n\nВміст Прихованого Скарбу залежить від Складності пройденої Глибини.\n\nТи можеш відкрити Прихований Скарб." },
    { en = "Absorb $w1 damage for $d.", ua = "Поглинає $w1 шкоди протягом $d." },
    { en = "Inflicting $1254644s1 Cosmic damage to all players every $t1 sec.", ua = "Завдає $1254644s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "Hidden! Cannot be seen by the Bound Loa and will not take damage.", ua = "Сховано! Зв'язаний лоа тебе не бачить, і ти не отримуєш шкоди." },
    { en = "Possessing the eye marks suspicious teachers and students. Activate the eye to reveal the true identities of any teachers or students who are disguised.", ua = "Володіння оком позначає підозрілих викладачів і студентів. Активуйте око, щоб розкрити справжню сутність будь-яких перевдягнених викладачів чи студентів." },
    { en = "Query the Tome as to where to go next or for more information.", ua = "Запитай у Фоліанта, куди вирушати далі, або попроси більше відомостей." },
    { en = "You perceive the enemies in a less threatening shape. Damage done increased by $s2%.", ua = "Ти бачиш ворогів у менш загрозливій подобі. Завдавана шкода збільшена на $s2%." },
    { en = "Movement speed increased by $s1%.\nDamage done increased by $s2%.\nHealing and absorption effects increased by $s3%.", ua = "Швидкість пересування збільшена на $s1%.\nЗавдавана шкода збільшена на $s2%.\nЕфекти зцілення й поглинання збільшені на $s3%." },
    { en = "Overcharged with Holy Light, inflicting $1255739s1 Holy damage to all players every $1255739t1 sec.", ua = "Перенасичення Святим Світлом завдає $1255739s1 священної шкоди всім гравцям кожні $1255739t1 с." },
    { en = "$1259275s1 Shadow damage every $1255763T1 sec.", ua = "$1259275s1 шкоди від тіні кожні $1255763T1 с." },
    { en = "Your healing spells and abilities also heal the imbued ally for $w2.", ua = "Твої зцілювальні закляття та здібності також зцілюють наснаженого союзника на $w2." },
    { en = "|cFF00AA99Bonus Event: Shadowlands Timewalking|r\n\nShadowlands reputation gains from combat and quests increased by $s1%.", ua = "|cFF00AA99Бонусна подія: Мандри в часі Тіньокраю|r\n\nПриріст репутації Тіньокраю від боїв і завдань збільшено на $s1%." },
    { en = "Slowly disintegrating. Timer pauses while in combat.", ua = "Повільно розпадається. У бою таймер зупиняється." },
    { en = "Deliver supplies!", ua = "Доставте припаси!" },
    { en = "Consuming the life force of each target afflicted by your damaging periodic effects, dealing ${$1257065s1*(1+ $d/$t1)} Shadowflame damage over $d.\n\nDamage dealt by Dark Harvest heals you for ${$1257065e1*100}% of damage done.", ua = "Поглинає життєву силу кожної цілі під дією твоїх періодичних ефектів шкоди, завдаючи ${$1257065s1*(1+ $d/$t1)} шкоди тіньовим полум'ям протягом $d.\n\nШкода від «Темних жнив» зцілює тебе на ${$1257065e1*100}% завданої шкоди." },
    { en = "Deliver supplies to Runestones!", ua = "Достав припаси до рунічних каменів!" },
    { en = "Damage taken from $@spellname1240210 increased by $s1%.", ua = "Шкода від «$@spellname1240210» збільшена на $s1%." },
    { en = "$w2 Arcane damage inflicted every $t2 sec.", ua = "Завдає $w2 арканної шкоди кожні $t2 с." },
    { en = "You were warned.", ua = "Тебе попереджали." },
    { en = "Tracking timewarped herbs and ores. Right-click to cancel.", ua = "Вистежування викривлених часом трав і руд. Клацни правою кнопкою, щоб скасувати." },
    { en = "A replica of the Exodar travels alongside you.", ua = "Поряд із тобою мандрує репліка Екзодара." },
    { en = "Interrupt the caster to force them to leave the Illicit Rain!", ua = "Перерви заклинача, щоб змусити його покинути «Заборонений Дощ»!" },
    { en = "Spread the quicksilver according to Talandra's pattern. Take care -- the reagent is toxic.", ua = "Розсип ртуть за візерунком Таландри. Стережися — реагент отруйний." },
    { en = "Remove the Curse of Transformation from nearby frogs.", ua = "Знімає Прокляття Перетворення з жаб поблизу." },
    { en = "$@auracaster's harmful spells cause additional Holy damage and shield 5 injured allies.", ua = "Шкідливі закляття $@auracaster завдають додаткової священної шкоди та захищають щитом 5 поранених союзників." },
    { en = "Absorbing $w2 healing.\n\nInflicts $s1 Shadow damage every $t1 sec.", ua = "Поглинає $w2 зцілення.\n\nЗавдає $s1 шкоди від тіні кожні $t1 с." },
    { en = "$1258781s1 Nature damage inflicted every $s1 sec.", ua = "Завдає $1258781s1 шкоди від сил природи кожні $s1 с." },
    { en = "Radiating Holy energy inflicting $1258661s1 Holy damage every $1258659t1 sec.", ua = "Випромінює священну енергію, завдаючи $1258661s1 священної шкоди кожні $1258659t1 с." },
    { en = "Inflicting $1271380s1 Frost damage every $1258894t1 sec to all players.", ua = "Завдає $1271380s1 морозної шкоди всім гравцям кожні $1258894t1 с." },
    { en = "Dealing Cosmic damage to your target every ${$t1}.2 sec. Slowed by $w2%.", ua = "Завдає космічної шкоди твоїй цілі кожні ${$t1}.2 с. Сповільнено на $w2%." },
    { en = "Suffering $w2 Shadow damage every $t2 sec. \n\nIf dispelled, causes ${(($w2*$s1/100)*(1+($w3-$w4)/100))*$w4/$w3} damage to the dispeller and silence them for $196364d.", ua = "Зазнає $w2 тіньової шкоди кожні $t2 с. \n\nЯкщо розвіяти, завдає ${(($w2*$s1/100)*(1+($w3-$w4)/100))*$w4/$w3} шкоди тому, хто розвіяв, і змушує його замовкнути на $196364d." },
    { en = "Mastery increased by $w1. You can see invisible and stealthed enemies.", ua = "Майстерність збільшена на $w1. Ти бачиш невидимих і прихованих ворогів." },
    { en = "A significant amount of damage is being Staggered", ua = "Значну частину шкоди відстрочено" },
    { en = "Targeted by $@spellname1260643.", ua = "Обрано ціллю: $@spellname1260643." },
    { en = "Haste is increased by $s1%.", ua = "Поспіх збільшено на $s1%." },
    { en = "Empowering Alleria within $s2 yards every $t1 sec.", ua = "Підсилює Аллерію в радіусі $s2 м кожні $t1 с." },
    { en = "Your harmful spells and abilities have a $?a1248927[${($1248927w5/1000)*100}.1%]?a1262365[${($1262365w5/1000)*100}.1%]?a1262364[${($1262364w5/1000)*100}.1%]?a1262359[${($1262359w5/1000)*100}.1%][] chance to deal $w1% of your target's maximum health as additional Holy damage.\n\n$?a1262364[Mandate of Sacred Death has a very small chance to execute non-boss enemies.]?a1262359[Mandate of Sacred Death has a very small chance to execute non-boss enemies.][]", ua = "Твої шкідливі закляття та здібності мають $?a1248927[${($1248927w5/1000)*100}.1%]?a1262365[${($1262365w5/1000)*100}.1%]?a1262364[${($1262364w5/1000)*100}.1%]?a1262359[${($1262359w5/1000)*100}.1%][] шансу завдати $w1% максимального здоров'я твоєї цілі як додаткову священну шкоду.\n\n$?a1262364[«Наказ священної смерті» має дуже малий шанс стратити ворогів, що не є босами.]?a1262359[«Наказ священної смерті» має дуже малий шанс стратити ворогів, що не є босами.][]" },
    { en = "Reducing damage taken from $@spellname1243585 by $1261781s1% to allies behind Zul'jarra.", ua = "Зменшує шкоду від $@spellname1243585 для союзників позаду Зул'джарри на $1261781s1%." },
    { en = "Your companion's spells and abilities have a chance to weaken enemies, increasing the chance to critically strike affected targets by $w1% for $1261796d.", ua = "Закляття та здібності твого супутника мають шанс ослабити ворогів, збільшуючи шанс критичного удару по уражених цілях на $w1% на $1261796d." },
    { en = "Inflicts $1261808s1 Frost damage to all players every $t1 sec.", ua = "Завдає $1261808s1 шкоди від морозу всім гравцям кожні $t1 с." },
    { en = "Your companion has a chance during combat to toss a grenade at an enemy target dealing moderate Holy damage with a $w1% chance to stun for $1262080d. This has a $w2% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members.", ua = "Твій супутник має шанс у бою кинути гранату у ворожу ціль, завдаючи помірної священної шкоди з $w1% шансом приголомшити на $1262080d. Граната з $w2% шансом відскакує до нової цілі.\n\nГраната може безпечно відскакувати від членів групи." },
    { en = "Your companion has a chance during combat to create a sanctified area at a party members' location, warping the flow of time and combat for all inside. Allies within gain $w1% increased movement speed, cooldown recharge rate, and cast speed while enemies suffer the opposite effects. Lasts $1262233d.", ua = "Твій супутник у бою має шанс створити освячену зону в місці розташування члена групи, викривлюючи плин часу та бою для всіх усередині. Союзники в ній отримують на $w1% більшу швидкість пересування, швидкість перезарядження та швидкість творення заклять, а вороги зазнають протилежних ефектів. Триває $1262233d." },
    { en = "Become one with a powerful being of Zul'Aman's past.", ua = "Злийтеся воєдино з могутньою істотою з минулого Зул'Аману." },
    { en = "After $w3 sec of combat, party members and Valeera deal $w1% more damage and healing for $w2 sec. ($1262284d cooldown)", ua = "Через $w3 с бою члени групи та Валіра завдають на $w1% більше шкоди й зцілення протягом $w2 с. (Перезарядження: $1262284d)" },
    { en = "Overflowed, increasing damage and healing done by $w2%.", ua = "Переповнення: завдана шкода та зцілення збільшені на $w2%." },
    { en = "Reducing all healing done on players by $s2%.", ua = "Зменшує все зцілення гравців на $s2%." },
    { en = "$1262688s1 Shadow damage every $1262676T1 sec.", ua = "$1262688s1 шкоди від тіні кожні $1262676T1 с." },
    { en = "You can feed the hydra budlings.", ua = "Ти можеш годувати паростків гідри." },
    { en = "This creature reduces the maximum health of its target by $<reduction>% with each melee strike.", ua = "Ця істота зменшує максимальне здоров'я своєї цілі на $<reduction>% кожним ударом ближнього бою." },
    { en = "This creature inflicts $1263000s1 Nature damage to all players every $t1 sec.", ua = "Ця істота завдає $1263000s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "Inflicts $1265030s1 Shadow damage every $t1 sec.", ua = "Завдає $1265030s1 шкоди від тіні кожні $t1 с." },
    { en = "Pulling enemies to your location every $t1 sec.", ua = "Притягує ворогів до тебе кожні $t1 с." },
    { en = "Under the effects of a powerful spell.", ua = "Під дією могутнього закляття." },
    { en = "Upon reaching $s1 applications, L'ura prepares to strike her current target with $@spellname1263970.", ua = "Сягнувши $s1 накладань, Л'ура готується вразити свою поточну ціль здібністю $@spellname1263970." },
    { en = "Movement speed slowed by $s2%.\n\nInflicts $s1 Shadow damage every $t1 sec.", ua = "Швидкість пересування сповільнена на $s2%.\n\nЗавдає $s1 тіньової шкоди кожні $t1 с." },
    { en = "Sharing all damage taken with Krick.", ua = "Ділить усю отримувану шкоду з Кріком." },
    { en = "Inflicts $1264159s1 Shadow damage to players struck.", ua = "Завдає $1264159s1 шкоди від тіні влученим гравцям." },
    { en = "Fixated upon by Ick!", ua = "На тебе зосередився Ік!" },
    { en = "Infused with vengeful Light. $s1 Holy damage inflicted to melee attackers.", ua = "Наповнений мстивим Світлом. Завдає $s1 священної шкоди тим, хто атакує в ближньому бою." },
    { en = "Critical strikes deal double damage and may knock your target into the air.", ua = "Критичні удари завдають подвійної шкоди й можуть підкинути вашу ціль у повітря." },
    { en = "Clever saptors occasionally ambush your foes during combat.", ua = "Кмітливі смолораптори час від часу нападають на ваших ворогів із засідки під час бою." },
    { en = "Upon expiration, inflicts $1264782s1 Nature damage to nearby players and horrifies them.", ua = "Після завершення завдає $1264782s1 шкоди від сил природи гравцям поблизу й сповнює їх жахом." },
    { en = "$?|diff23[Damage taken reduced by $s1%.][Damage taken reduced by $s1%.\n$s2% health lost every $t2 sec.]", ua = "$?|diff23[Отримувана шкода знижена на $s1%.][Отримувана шкода знижена на $s1%.\nВтрачає $s2% здоров'я кожні $t2 с.]" },
    { en = "Inflicts $1264989s1 Shadow damage to all players every $t1 sec.", ua = "Завдає $1264989s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "Melee attacks additionally inflict $1280434s1 Shadow damage.", ua = "Атаки ближнього бою додатково завдають $1280434s1 шкоди від тіні." },
    { en = "Upon taking damage, automatically consume a refreshing drink to heal for $1265145o1 over $1265145d.", ua = "Отримавши шкоду, автоматично випиває освіжний напій, що зцілює на $1265145o1 протягом $1265145d." },
    { en = "Healing for $w1 per $t sec.", ua = "Зцілює $w1 здоров'я кожні $t с." },
    { en = "Stunned.\nBleeding for $s2 Physical damage every $T2 sec.", ua = "Приголомшено.\nКровотеча завдає $s2 фізичної шкоди кожні $T2 с." },
    { en = "Protecting you from the next $w1 damage.", ua = "Захищає тебе від наступних $w1 шкоди." },
    { en = "Taking $s1% increased damage.\n\nStunned.", ua = "Отримувана шкода збільшена на $s1%.\n\nПриголомшено." },
    { en = "Inflicts $1265420s1 Shadow damage every $t1 sec and summons a $@spellname1265420.", ua = "Завдає $1265420s1 шкоди від тіні кожні $t1 с. і прикликає $@spellname1265420." },
    { en = "Increased Shadow damage taken by $s1%.", ua = "Отримувана тіньова шкода збільшена на $s1%." },
    { en = "Increased damage taken from $@spellname1265424 by $s1%.", ua = "Отримувана шкода від $@spellname1265424 збільшена на $s1%." },
    { en = "Inflicting $1253879s1 Cosmic damage every $t1 sec. Damage taken from $@spellname1263970 increased by $s2%.", ua = "Завдає $1253879s1 космічної шкоди кожні $t1 с. Отримувана шкода від $@spellname1263970 збільшена на $s2%." },
    { en = "Absorbs $w1 healing and inflicts $w2 Shadow damage every $t2 sec until the burn is fully healed.", ua = "Поглинає $w1 зцілення та завдає $w2 шкоди від тіні кожні $t2 с, доки опік не буде повністю зцілено." },
    { en = "Melee attacks inflicts additional $1266450s1 Shadow damage.", ua = "Атаки ближнього бою завдають додатково $1266450s1 шкоди від тіні." },
    { en = "Damage taken from $@spellname1251811 increased by $s1%.", ua = "Шкода від «$@spellname1251811» збільшена на $s1%." },
    { en = "Tears open a void rift every $t1 sec.", ua = "Розриває розлом Порожнечі кожні $t1 с." },
    { en = "Leech increased by $s1%.\nDamage taken from area of effect attacks reduced by $s2%.\nThis aura persists through death.", ua = "Висмоктування збільшене на $s1%.\nОтримувана шкода від атак по області зменшена на $s2%.\nЦя аура зберігається після смерті." },
    { en = "Damage and healing increased by ${$w1}%. $?WE50329[This power increases every week, up to $w6%.][]", ua = "Шкода та зцілення збільшені на ${$w1}%. $?WE50329[Ця сила зростає щотижня, аж до $w6%.][]" },
    { en = "Midnight Fishing Skill increased by $w1.\n\nMidnight Fishing Perception increased by $w2.\n\nWhen fishing up a treasure in Midnight zones, gain another.", ua = "Навичка риболовлі Опівночі збільшена на $w1.\n\nСприйнятливість у риболовлі Опівночі збільшена на $w2.\n\nВиловивши скарб у зонах Опівночі, ти отримуєш ще один." },
    { en = "Experience gained from killing monsters and completing quests increased by $s1%.\n\nCompleting Timewalking dungeons increases the effect and extends its duration.\n\nUpon reaching $u applications, transforms to $@spellname1229050, increasing that effect to $1229050s1%.", ua = "Досвід за вбивство монстрів і виконання завдань збільшений на $s1%.\n\nПроходження підземель Мандрів у часі посилює ефект і подовжує його тривалість.\n\nПісля $u накладань перетворюється на «$@spellname1229050», збільшуючи цей ефект до $1229050s1%." },
    { en = "Experience gained from killing monsters and completing quests increased by $s1%.\n\nCompleting Timewalking dungeons  refreshes the duration.", ua = "Досвід за вбивство монстрів і виконання завдань збільшений на $s1%.\n\nПроходження підземель Мандрів у часі оновлює тривалість." },
    { en = "Wild Guardian is available to cast.", ua = "«Дикий страж» доступний для творення." },
    { en = "Demonic eyes float overhead, analyzing nearby enemies.\n\nConsuming Demonic Art commands the eye to fly at your current target and explode, dealing Fire damage.", ua = "Демонічні очі ширяють над головою, аналізуючи ворогів поблизу.\n\nВитрачання «Демонічного мистецтва» наказує оку полетіти до твоєї поточної цілі й вибухнути, завдавши вогняної шкоди." },
    { en = "Restoring $w1% mana every sec.", ua = "Відновлює $w1% мани щосекунди." },
    { en = "$1270513s1 Shadow damage every $1270497T1 sec.\nDetonates for Shadow damage to nearby players upon expiration.", ua = "$1270513s1 шкоди від тіні кожні $1270497T1 с.\nПісля завершення вибухає, завдаючи шкоди від тіні гравцям поблизу." },
    { en = "Increases Gloomtouched damage taken by $s1%.", ua = "Збільшує отримувану шкоду від «Торкнутого мороком» на $s1%." },
    { en = "Salhadaar's melee attacks destabilize his current target, inflicting $1284963s1 Shadow damage every $1271579t1 sec for $1271579d. This effect stacks.", ua = "Атаки ближнього бою Салгадаара дестабілізують його поточну ціль, завдаючи $1284963s1 шкоди від тіні кожні $1271579t1 сек. протягом $1271579d. Цей ефект накопичується." },
    { en = "Upon expiration, this creature explodes, inflicting significant damage to all players.", ua = "Після завершення ця істота вибухає, завдаючи значної шкоди всім гравцям." },
    { en = "Invisible. Attacking will catch an enemy off guard, inflicting additional damage.", ua = "Невидимість. Атака застане ворога зненацька й завдасть додаткової шкоди." },
    { en = "In Delves, until you complete your next one, all of your stats are increased by $w1%.", ua = "У Глибинах усі твої характеристики збільшено на $w1%, доки ти не завершиш наступну Глибину." },
    { en = "Inflicts $s1 Holy damage every $t1 sec.\nMovement speed reduced by $s2%.", ua = "Завдає $s1 священної шкоди кожні $t1 с.\nШвидкість пересування знижена на $s2%." },
    { en = "In Delves, until you complete your next one, you are granted an additonal life.", ua = "У Глибинах тобі надається додаткове життя, доки ти не завершиш наступну Глибину." },
    { en = "In Delves, until you complete your next one, gain $w2% of your maximum health as an absorb shield for $1267063d whenever your health falls below $w1% during combat. Can only occur every $1268672d.", ua = "У Глибинах, доки ти не завершиш наступну Глибину, щоразу, коли твоє здоров'я в бою падає нижче $w1%, ти отримуєш щит поглинання на $w2% максимального здоров'я на $1267063d. Може спрацьовувати не частіше ніж раз на $1268672d." },
    { en = "The presence of the Lightbound Vanguard weakens this enemy's vitality, reducing their maximum health by $w1% and damage done by $w2%.\n\nThis effect stacks for each present member of the Vanguard.", ua = "Присутність Скутого Світлом авангарду послаблює життєву силу цього ворога, зменшуючи його максимальне здоров'я на $w1%, а завдавану шкоду — на $w2%.\n\nЦей ефект накопичується за кожного присутнього члена Авангарду." },
    { en = "Inflicting $s1 Shadow damage every $1272937t sec.", ua = "Завдає $s1 шкоди від тіні кожні $1272937t с." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1246934 Kulzi, Loa of Medicine|r\n\nThe loas of Fire and Medicine increase your Spell Power by $m1% while your health is above 90%.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1246934 Кулзі, лоа медицини|r\n\nЛоа вогню й медицини збільшують вашу силу закляттів на $m1%, поки ваше здоров'я вище 90%.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Akil'zon, Loa of Victory\n$@spellicon1246935 Filo, Loa of Children|r\n\nThe loas of Victory and Children bestow $m1% additional movement speed while in a hub.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Акіл'зон, лоа звитяги\n$@spellicon1246935 Філо, лоа дітей|r\n\nЛоа звитяги й дітей дарують +$m1% до швидкості пересування, поки ви в осередку.\n\nАктивне лише в Зул'Амані." },
    { en = "Carrying a Twilight's Blade incantation.", ua = "Несе заклинання Клинка Сутінків." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1246935 Filo, Loa of Children|r\n\nWhen Health is below $m1%, the loas of War and Children summon a Grand Kapara Guard to fight with you for $1273345d.\n\nOnly usable in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа війни\n$@spellicon1246935 Філо, лоа дітей|r\n\nКоли здоров'я нижче $m1%, лоа війни й дітей прикликають величну вартову капару, що б'ється поруч із вами протягом $1273345d.\n\nВикористовується лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Akil'zon, Loa of Victory\n$@spellicon1246936 Pahk, Loa of the Depths|r\n\nThe loas of Victory and the Depths grant you $m1% swim speed in water.\n\nOnly usable in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Акіл'зон, лоа звитяги\n$@spellicon1246936 Пак, лоа глибин|r\n\nЛоа звитяги й глибин дарують вам +$m1% швидкості плавання у воді.\n\nВикористовується лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1246936 Pahk, Loa of the Depths|r\n\nThe loas of Fire and the Depths bless you with Waterwalking.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1246936 Пак, лоа глибин|r\n\nЛоа вогню й глибин благословляють вас ходінням по воді.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1246936 Pahk, Loa of the Depths|r\n\nThe loas of War and the Depths grant you the ability to walk upon any body of water's floor.\n\nOnly usable in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа війни\n$@spellicon1246936 Пак, лоа глибин|r\n\nЛоа війни й глибин дарують вам здатність ходити по дну будь-якої водойми.\n\nВикористовується лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Akil'zon, Loa of Victory\n$@spellicon1253437 Wila'ma, Loa of Travelers|r\n\nThe loas of Victory and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Акіл'зон, лоа звитяги\n$@spellicon1253437 Віла'ма, лоа мандрівників|r\n\nЛоа звитяги й мандрівників розмістили мандрівних крамарів по всьому краю вам на користь.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Halazzi, Loa of the Hunt\n$@spellicon1253437 Wila'ma, Loa of Travelers|r\n\nThe loas of the Hunt and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Галаззі, лоа полювання\n$@spellicon1253437 Віла'ма, лоа мандрівників|r\n\nЛоа полювання й мандрівників розмістили мандрівних крамарів по всьому краю вам на користь.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1253437 Wila'ma, Loa of Travelers|r\n\nThe loas of Fire and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1253437 Віла'ма, лоа мандрівників|r\n\nЛоа вогню й мандрівників розмістили мандрівних крамарів по всьому краю вам на користь.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1253437 Wila'ma, Loa of Travelers|r\n\nThe loas of War and Travelers have stationed Packpeddlers throughout the land for your use.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа війни\n$@spellicon1253437 Віла'ма, лоа мандрівників|r\n\nЛоа війни й мандрівників розмістили мандрівних крамарів по всьому краю вам на користь.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Akil'zon, Loa of Victory\n$@spellicon1253438 Shadra, Loa of Subterfuge|r\n\nWhile in combat, the loas of Victory and Subterfuge increase your Haste by $m1% every 1 second up to 15%. Decreases while out of combat.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Акіл'зон, лоа звитяги\n$@spellicon1253438 Шадра, лоа підступу|r\n\nУ бою лоа звитяги й підступу щосекунди збільшують ваш поспіх на $m1% (до 15%). Поза боєм — зменшується.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1253439 Dundun, Loa of Abundance|r\n\nThe loas of the Hunt and Abundance increase your Movement Speed by $m1% for $d whenever you gather reagents via Mining, Herbalism, Skinning, or Fishing.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1253439 Дундун, лоа рясності|r\n\nЛоа полювання й рясності збільшують вашу швидкість пересування на $m1% на $d щоразу, коли ви збираєте складники через Гірничу справу, Травництво, Білування чи Риболовлю.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1253439 Dundun, Loa of Abundance|r\n\nWhenever you gather reagents via Mining, Herbalism, Skinning, or Fishing, the loas of War and Abundance heal you by $1273519m1% and reduce damage taken by $1273481m1% until you're damaged next.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа Війни\n$@spellicon1253439 Дундун, лоа Рясності|r\n\nЩоразу, коли ти збираєш реагенти гірництвом, травництвом, білуванням або рибальством, лоа Війни та Рясності зцілюють тебе на $1273519m1% і зменшують отримувану шкоду на $1273481m1%, доки ти знову не зазнаєш шкоди.\n\nДіє лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1253440 Puul, Loa of Peril|r\n\nThrough the loas of War and Peril, you gain 25% Leech.\n\nBut you also take 25% more damage from all sources.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа війни\n$@spellicon1253440 Пуул, лоа небезпеки|r\n\nЧерез лоа війни й небезпеки ви отримуєте +25% висмоктування.\n\nАле також дістаєте на 25% більше шкоди від усіх джерел.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Akil'zon, Loa of Victory\n$@spellicon1253441 Oe, Loa of Growth|r\n\nThrough the loas of Victory and Forests, you gain 25% Weapon Attack Speed.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246869 Акіл'зон, лоа звитяги\n$@spellicon1253441 Ое, лоа буяння|r\n\nЧерез лоа звитяги й лісів ви отримуєте +25% до швидкості атаки зброєю.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Halazzi, Loa of the Hunt\n$@spellicon1253441 Oe, Loa of Growth|r\n\nThrough the loas of the Hunt and Forests, you gain a 5% chance for your attack to deal 500% damage.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Галаззі, лоа Полювання\n$@spellicon1253441 Ое, лоа Зросту|r\n\nЗавдяки лоа Полювання й Лісів ваша атака має 5% шансу завдати 500% шкоди.\n\nДіє лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1253441 Oe, Loa of Growth|r\n\nThrough the loas of Fire and Growth, you gain a 15% increase to Intelligence.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1253441 Ое, лоа буяння|r\n\nЧерез лоа вогню й буяння ви отримуєте +15% до інтелекту.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Nalorakk, Loa of War\n$@spellicon1253441 Oe, Loa of Growth|r\n\nThrough the loas of War and Growth, you gain 10% more Strength and Stamina.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246933 Налоракк, лоа війни\n$@spellicon1253441 Ое, лоа буяння|r\n\nЧерез лоа війни й буяння ви отримуєте на 10% більше сили та витривалості.\n\nАктивне лише в Зул'Амані." },
    { en = "Immune to crowd control and interrupt effects.", ua = "Несприйнятливість до ефектів контролю та переривання." },
    { en = "Inflicting $s1% of damage taken to L'ura's alternate being.", ua = "Завдає $s1% отриманої шкоди іншій іпостасі Л'ури." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Halazzi, Loa of the Hunt\n$@spellicon1246944 Mot'amra, Loa of Pestilence|r\n\nThe loas of Victory and Pestilence bless you with a $h% chance to poison your enemy, inflicting $1276087s Nature damage every $1276087t sec for $1276087d.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Галаззі, лоа полювання\n$@spellicon1246944 Мот'амра, лоа пошесті|r\n\nЛоа звитяги й пошесті благословляють вас на $h% шанс отруїти ворога, завдаючи $1276087s шкоди від сил природи кожні $1276087t с протягом $1276087d.\n\nАктивне лише в Зул'Амані." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1246944 Mot'amra, Loa of Pestilence|r\n\nThe loas of Fire and Pestilence bless you with a $h% chance to Charm your enemy for $1276097d, forcing them to fight other hostile foes on your behalf.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1246944 Мот'амра, лоа пошесті|r\n\nЛоа вогню й пошесті благословляють вас на $h% шанс зачарувати ворога на $1276097d, змушуючи його битися замість вас з іншими ворожими супротивниками.\n\nАктивне лише в Зул'Амані." },
    { en = "Combine the Reinforced Amani Haft, Tempered Amani Spearhead, and Toughened Amani Leather Wrap to reform the Amani Warrior's Spear.", ua = "Поєднайте Укріплений держак амані, Загартований наконечник списа амані та Зміцнену шкіряну обмотку амані, щоб відновити Спис воїна амані." },
    { en = "$1276220s2 Nature damage every $1276220T2 sec.", ua = "$1276220s2 шкоди від сил природи кожні $1276220T2 с." },
    { en = "Absorbs $w healing.\n$s2 Arcane damage every $T2 sec.", ua = "Поглинає $w зцілення.\n$s2 арканної шкоди кожні $T2 с." },
    { en = "Filo, Loa of Children, becomes available for worship at the Altar of Blessings in Amani'Zar Village.", ua = "Філо, лоа дітей, стає доступним для вшанування біля Вівтаря благословень у селищі Амані'Зар." },
    { en = "Shadra, Loa of Subterfuge, becomes available for worship at the Altar of Blessings in Amani'Zar Village.", ua = "Шадра, лоа хитрощів, стає доступною для вшанування біля Вівтаря благословень у селищі Амані'Зар." },
    { en = "Melee attacks against $@auracaster will grant a Physical absorb shield.", ua = "Атаки ближнього бою проти $@auracaster дають щит, що поглинає фізичну шкоду." },
    { en = "$1277045s1 Nature damage every $1277045T1 sec.\nMovement speed reduced by $1277045s2%.", ua = "$1277045s1 шкоди від сил природи кожні $1277045T1 с.\nШвидкість пересування знижена на $1277045s2%." },
    { en = "Void energy courses through you.\n\nCritical Strike increased by $w1.\nLeech increased by $w2%.\nMovement Speed increased by $w3%.", ua = "Енергія Порожнечі тече крізь тебе.\n\nКритичний удар збільшено на $w1.\nВисмоктування збільшено на $w2%.\nШвидкість пересування збільшено на $w3%." },
    { en = "$1277045s1 Nature damage every $1277045T1 sec.\nMovement speed reduced by $1277045s1%.", ua = "$1277045s1 шкоди від сил природи кожні $1277045T1 с.\nШвидкість пересування знижена на $1277045s1%." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Jan'alai, Loa of Fire\n$@spellicon1246935 Filo, Loa of Children|r\n\nThe loas of Fire and Childhood bless you with a $1277706m% increase to Intelligence with every successful spell cast for $1277706d. Stacks up to $1277706u times.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246932 Джан'алай, лоа вогню\n$@spellicon1246935 Філо, лоа дітей|r\n\nЛоа вогню й дитинства благословляють вас збільшенням інтелекту на $1277706m% за кожне успішне творення закляття протягом $1277706d. Накопичується до $1277706u раз.\n\nАктивне лише в Зул'Амані." },
    { en = "Toss this ethereal battery at the target area, dealing heavy damage to machinery and enemies.", ua = "Кидає цю батарею ефіріалів у цільову область, завдаючи великої шкоди механізмам і ворогам." },
    { en = "Protected from $@spellname1249265.", ua = "Захист від $@spellname1249265." },
    { en = "Dashed from Echo Isles to Silvermoon. Outdoor movement speed increased by $1280079s1%.", ua = "Дистанцію від Островів Відлуння до Сільвермуна подолано. Швидкість пересування просто неба збільшена на $1280079s1%." },
    { en = "$?a1279750[Maximum Health: $1279750w1%.][Maximum Health: 0%]\n$?a1279752[Movement Speed: $1279752w1%.][Movement Speed: 0%]\n$?a1279753[$pri: $1279753w1%.][$pri: 0%]\n$?a1266966[Haste: $1266966w1%.][Haste: 0%]\n$?a1266965[Critical Strike: $1266965w1%.][Critical Strike: 0%]\n$?a1266967[Mastery: $1266967w1%.][Mastery: 0%]\n$?a1266969[Versatility: $1266969w1%.][Versatility: 0%]\n$?a1279751[Damage Reduction: $1279751w1%.][Damage Reduction: 0%]", ua = "$?a1279750[Максимальне здоров'я: $1279750w1%.][Максимальне здоров'я: 0%]\n$?a1279752[Швидкість пересування: $1279752w1%.][Швидкість пересування: 0%]\n$?a1279753[$pri: $1279753w1%.][$pri: 0%]\n$?a1266966[Поспіх: $1266966w1%.][Поспіх: 0%]\n$?a1266965[Критичний удар: $1266965w1%.][Критичний удар: 0%]\n$?a1266967[Майстерність: $1266967w1%.][Майстерність: 0%]\n$?a1266969[Універсальність: $1266969w1%.][Універсальність: 0%]\n$?a1279751[Зниження шкоди: $1279751w1%.][Зниження шкоди: 0%]" },
    { en = "You're a racing rainbow!", ua = "Ти — веселка, що мчить!" },
    { en = "Inflicting $s2 Nature damage every $t1 sec.", ua = "Завдає $s2 шкоди від сил природи кожні $t1 с." },
    { en = "Fighting in the Grudge Pit as the Rotstalk's villainous partner.", ua = "Б'єшся в Ямі Злоби як лиходійський напарник Гнилостебла." },
    { en = "Upon expiration, inflicts $1281178s2 Cosmic damage within $1281178A2 yards.", ua = "Після завершення завдає $1281178s2 космічної шкоди в межах $1281178A2 м." },
    { en = "Increases damage done by $s1% and Fel Firebolt now jumps to $s2 additional targets.", ua = "Підвищує завдану шкоду на $s1%, і Заряд Вогню Скверни тепер перестрибує на $s2 додаткових цілей." },
    { en = "Command the nearby lynx to reveal any nearby stealthed enemies.", ua = "Наказує рисі поблизу викрити всіх ворогів у скрадливості довкола." },
    { en = "Vaporized.", ua = "Випарувано." },
    { en = "|cFF00AA99\"Beloved Menace\"|r", ua = "|cFF00AA99«Улюблена Напасть»|r" },
    { en = "Inflicting $1282372s1 Cosmic damage to all players every $t1 sec.", ua = "Завдає $1282372s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "Absorbing $@spellname1282269, each inflicting $1282425s1 Cosmic damage to all players and regenerating energy.", ua = "Поглинає $@spellname1282269, щоразу завдаючи $1282425s1 космічної шкоди всім гравцям і відновлюючи енергію." },
    { en = "While in combat, gore occasionally appears beneath you, inflicting Shadow damage after a short delay.", ua = "У бою під вами час від часу проступає кров, що після короткої затримки завдає шкоди Тінню." },
    { en = "Melee attacks strike all enemies in a cone in front of the caster, inflicting Shadow damage.", ua = "Атаки ближнього бою вражають усіх ворогів у конусі перед заклиначем, завдаючи шкоди від тіні." },
    { en = "Your companion has a chance during combat, via casting spells, abilities, or from slaying enemies to gain a Sanctum's Blessing. Each blessing grants $w1% increased healing and damage.\n\nUpon reaching $w6 blessings, your companion becomes a Sanctum's Champion, converting $w2% of their current health into an absorb shield that lasts for $1265780d, or until depleted. While the shield holds, increase the damage and healing conferred by Sanctum's Blessings. Upon expiration, blessings are removed.\n\nSlaying an Elite enemy grants $w4 Sanctum's Blessings, while normal foes yield $w3.", ua = "Твій супутник у бою має шанс отримати Благословення Санктуму, творячи закляття, використовуючи здібності або вбиваючи ворогів. Кожне благословення збільшує зцілення та шкоду на $w1%.\n\nСягнувши $w6 благословень, твій супутник стає Чемпіоном Санктуму, перетворюючи $w2% свого поточного здоров'я на поглинальний щит, що триває $1265780d або доки не вичерпається. Поки щит тримається, шкода та зцілення від Благословень Санктуму збільшені. Після завершення благословення знімаються.\n\nУбивство елітного ворога дає $w4 Благословення Санктуму, а звичайні вороги дають $w3." },
    { en = "Inflicting $1264650s1 Fire damage to all players every $t1 sec.", ua = "Завдає $1264650s1 вогняної шкоди всім гравцям кожні $t1 с." },
    { en = "The voidspawn sense weakness and rush to attack you.", ua = "Поріддя Порожнечі відчувають слабкість і кидаються на тебе." },
    { en = "Running with the rainbows.", ua = "Біжить із веселками." },
    { en = "Dealing damage to nearby enemies and consuming nearby patches of Lightbloom growths.", ua = "Завдає шкоди ворогам поблизу та поглинає прилеглі зарості Світлоцвіту." },
    { en = "Inflicting $s3 Shadow damage every $t3 sec. Healing and absorption effects reduced by $s1%.", ua = "Завдає $s3 шкоди від тіні кожні $t3 с. Ефекти зцілення й поглинання зменшені на $s1%." },
    { en = "Nek'zali's melee attacks cause the target to become $@spellname1284109.", ua = "Атаки ближнього бою Нек'залі накладають на ціль $@spellname1284109." },
    { en = "Venom slime ejected by this Sentinel fires back toward its source.", ua = "Отруйний слиз, який випускає цей Вартовий, летить назад до свого джерела." },
    { en = "Blood venom from this Sentinel creates a toxic pool upon expiration.", ua = "Кров'яна отрута цього вартового після завершення утворює токсичну калюжу." },
    { en = "Inflicting $1284258s1 Nature damage to all players every $t1 sec.", ua = "Завдає $1284258s1 шкоди від сил природи всім гравцям кожні $t1 с." },
    { en = "$1284813s1 Plague damage inflicted every $t1 sec.\n\nColliding with another player merges applications. Reaching $s1 stacks neutralizes the toxin, removing it harmlessly.", ua = "Завдає $1284813s1 шкоди від чуми кожні $t1 с.\n\nЗіткнення з іншим гравцем об'єднує накладання. Досягнення $s1 зарядів нейтралізує токсин і безпечно знімає його." },
    { en = "$s1 Shadow damage inflicted every $t1 sec.\nUpon removal, leaves behind $@spellname1284628.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с.\nПісля зняття лишає по собі $@spellname1284628." },
    { en = "It's time to face the music.", ua = "Час зустріти музику лицем до лиця." },
    { en = "Inflicts $1285509s1 Fire damage every $t1 sec.", ua = "Завдає $1285509s1 шкоди вогнем кожні $t1 с." },
    { en = "Your primary stats have been increased by $w11 and stamina increased by $w10. This aura persists through death.", ua = "Твої основні характеристики збільшено на $w11, а витривалість — на $w10. Ця аура зберігається після смерті." },
    { en = "Absorbing $w1 damage.\n\nApplying Suffocating Darkness to all players every $t3 sec.", ua = "Поглинає $w1 шкоди.\n\nНакладає «Задушливу темряву» на всіх гравців кожні $t3 с." },
    { en = "$1287032s1 Nature damage inflicted every $t1 sec.", ua = "Завдає $1287032s1 шкоди від сил природи кожні $t1 с." },
    { en = "Dealing damage or healing will send $?$w1=1[the Orb][all $w1 Orbs] towards your target, inflicting Cosmic damage or restoring health depending on the target.", ua = "Завдання шкоди або зцілення посилає $?$w1=1[Сферу][усі $w1 Сфер] до твоєї цілі, завдаючи космічної шкоди або відновлюючи здоров'я залежно від цілі." },
    { en = "Fixated on the $@spellname1284032! Absorbing $w1 Magic damage and immune to death.", ua = "Зосереджено на «$@spellname1284032»! Поглинає $w1 магічної шкоди, імунітет до смерті." },
    { en = "Inflicting increasing Cosmic damage to all players every $1275057t3 sec.", ua = "Завдає дедалі більшу космічну шкоду всім гравцям кожні $1275057t3 с." },
    { en = "Locked in a $@spellname1287798.", ua = "Затиснуто в $@spellname1287798." },
    { en = "Targeted by $@spellname1288864", ua = "Обрано ціллю: $@spellname1288864" },
    { en = "Fungal spores float thick in the air! Although unhealthy for flying mounts, the spores will slow your fall.", ua = "У повітрі витає густа хмара грибних спор! Хоч вони й шкідливі для летючих їздових тварин, спори сповільнять твоє падіння." },
    { en = "Petrified.\nAbsorbs $w3 healing and inflicts $s2 Nature damage every $t2 sec until fully healed.", ua = "Скам'яніло.\nПоглинає $w3 зцілення та завдає $s2 шкоди від сил природи кожні $t2 с до повного зцілення." },
    { en = "$1289237s1 Nature damage inflicted every $t1 sec.", ua = "Завдає $1289237s1 шкоди від сил природи кожні $t1 с." },
    { en = "Immune to damage. $s3 tethers remain.", ua = "Несприйнятливість до шкоди. Лишилося прив'язей: $s3." },
    { en = "$1290480s1 Nature damage inflicted every $t1 sec.\n\n$?DIFF15|DIFF16 [Instantly kills the target upon reaching $s2 applications.][Upon reaching $s2 applications, the target suffers $1303196s1% of their maximum health as Nature damage and is stunned for $1303196d.]", ua = "Завдає $1290480s1 шкоди від сил природи кожні $t1 с.\n\n$?DIFF15|DIFF16 [Миттєво вбиває ціль після досягнення $s2 накладань.][Після досягнення $s2 накладань ціль зазнає шкоди від сил природи в розмірі $1303196s1% свого максимального здоров'я та приголомшується на $1303196d.]" },
    { en = "Cloaked by Y'mera's Invisibility Spell.", ua = "Приховано закляттям невидимості Й'мери." },
    { en = "Restoring $s1% health and $1291831w1% mana every second.", ua = "Відновлює $s1% здоров'я та $1291831w1% мани щосекунди." },
    { en = "Restoring $s1% health and $1291791w1% mana every second.", ua = "Відновлює $s1% здоров'я та $1291791w1% мани щосекунди." },
    { en = "Serpents within the $@spellname1289962 prepare to hatch.", ua = "Змії всередині $@spellname1289962 готуються вилупитися." },
    { en = "Using the Cynosure of Twilight to reach out into the Great Dark Beyond and tear open a rift.", ua = "Використовує Світоч Сутінків, щоб сягнути Великої Темної Безодні й розірвати розлом." },
    { en = "Restoring $s1% health and $1290929w1% mana every second.", ua = "Відновлює $s1% здоров'я та $1290929w1% мани щосекунди." },
    { en = "Occasionally emitting spores of sleeping gas.", ua = "Час від часу випускає спори зі снодійним газом." },
    { en = "Periodically releases a lethal ice spear towards a player, inflicting $1294152s1 Frost damage. $@spellname1292270 impacts the first player or creature hit.", ua = "Періодично випускає в гравця смертоносний крижаний спис, що завдає $1294152s1 морозної шкоди. $@spellname1292270 вражає першого гравця чи істоту на своєму шляху." },
    { en = "Periodically releases thorny vines that bind and slow players, inflicting $1297710s1 Nature damage every $1297710t1 sec and reducing movement speed by $1297710s2% to players within.", ua = "Періодично випускає колючі лози, що сковують і сповільнюють гравців, завдаючи $1297710s1 шкоди від сил природи кожні $1297710t1 с і знижуючи швидкість пересування гравців усередині на $1297710s2%." },
    { en = "Periodically sprouts patches of springcap mushrooms underneath random targets that last $1297756d. \n\nUpon contact with a player, inflicts $1297757s1 Nature damage to the triggering player and knocks them away.", ua = "Періодично вирощує під випадковими цілями латки грибів-веснянок, що тримаються $1297756d. \n\nПри контакті з гравцем завдає йому $1297757s1 шкоди від сил природи та відкидає його." },
    { en = "The caster expels energy with attacks and spells, inflicting $1297960s1 Arcane damage to players within $1297960a1 yds of impact locations.", ua = "Заклинач вивільняє енергію атаками й закляттями, завдаючи $1297960s1 арканної шкоди гравцям у радіусі $1297960a1 ярдів від місць влучання." },
    { en = "You are being hunted. Be wary of an ambush.", ua = "На тебе полюють. Стережися засідки." },
    { en = "You feel as if something is watching you.", ua = "Тобі здається, що хтось за тобою стежить." },
    { en = "Armed with a Spellbreaker's Ward-Lance.", ua = "Озброєно «Оберегом-списом руйнівника чарів»." },
    { en = "Targeted for $@spellname1292270.", ua = "Обрано ціллю: $@spellname1292270." },
    { en = "Spore Spewing Shrooms in the area are creating a Spore Storm.", ua = "Гриби-спороплюї поблизу створюють «Спорову бурю»." },
    { en = "Taking periodic damage while in combat.\n\nLeave the Spore Storm or destroy enough Spore Spewing Shrooms in the area to counteract this.", ua = "Отримує періодичну шкоду, перебуваючи в бою.\n\nЩоб цьому зарадити, покинь Споровий шторм або знищ достатньо Спорометних грибів у цій місцевості." },
    { en = "$@spellaura440513\n\nSurfing the stars never looked so easy.", ua = "$@spellaura440513\n\nСерфінг зірками ще ніколи не був таким легким." },
    { en = "Primary stat increased by $w11.", ua = "Основна характеристика збільшена на $w11." },
    { en = "Under the control of Mor'zahi.", ua = "Під контролем Мор'загі." },
    { en = "Incoming Magic damage from Shredding Shards increased by $1295858s2%.", ua = "Отримувана магічна шкода від «Шматувальних скалок» збільшена на $1295858s2%." },
    { en = "Defeating all highlighted enemies will complete the enemy forces requirement.", ua = "Перемога над усіма підсвіченими ворогами виконає вимогу щодо ворожих сил." },
    { en = "Movement speed reduced by $s2%. Damage done reduced by $s3%.", ua = "Швидкість пересування знижена на $s2%. Завдана шкода зменшена на $s3%." },
    { en = "Targeted by Mighty Thud.", ua = "Обрано ціллю: «Могутній гупіт»." },
    { en = "$1299947s1 Fire damage inflicted every $1299947t1 sec.", ua = "Завдає $1299947s1 шкоди вогнем кожні $1299947t1 с." },
    { en = "Damage taken is reduced by $s1% when the tortollans are within 30 yds of each other.", ua = "Отримувана шкода зменшена на $s1%, коли тортоллани перебувають у межах 30 м один від одного." },
    { en = "Taking $1307573s1 Nature damage every $t2 sec.", ua = "Отримує $1307573s1 шкоди від сил природи кожні $t2 с." },
    { en = "Absorbing $w1 damage and applying $@spellname1307700 to all enemies every $1298223t1 sec.", ua = "Поглинає $w1 шкоди та накладає $@spellname1307700 на всіх ворогів кожні $1298223t1 с." },
    { en = "Each of Rav'i's three heads strike her current target, inflicting Physical damage.", ua = "Кожна з трьох голів Рав'ї вражає її поточну ціль, завдаючи фізичної шкоди." },
    { en = "Inflicting $1299080s1 Physical damage every $t1 sec until pulled apart.", ua = "Завдає $1299080s1 фізичної шкоди кожні $t1 с, доки вас не роз'єднають." },
    { en = "Increases Versatility by $?a1276718[$1276718s1]?a1277389[$1277389s1][$1276718s1] while fighting for the Rotmire.", ua = "Збільшує Універсальність на $?a1276718[$1276718s1]?a1277389[$1277389s1][$1276718s1] у бою проти Гнилобагна." },
    { en = "Damage taken shared with the Writhing Coil.\nSusceptible to crowd control effects.", ua = "Отримувана шкода розділяється зі Звивистим Звоєм.\nВразливість до ефектів контролю." },
    { en = "Touching $@spellname1300869 transfers an application of $@spellname1300877.", ua = "Дотик до $@spellname1300869 передає одне накладання $@spellname1300877." },
    { en = "Wielding the Fang of Ula'tek.", ua = "Тримає Ікло Ула'тек." },
    { en = "Upon expiration, the venom bursts inflicting $1300901s1 Nature damage.", ua = "Після завершення отрута вибухає, завдаючи $1300901s1 шкоди від сил природи." },
    { en = "Inflicts $1308275s1 Nature damage every $t1 sec.", ua = "Завдає $1308275s1 шкоди від сил природи кожні $t1 с." },
    { en = "Can see Aerospores.", ua = "Дозволяє бачити аероспори." },
    { en = "This creature's attacks apply an affliction that causes $@spellname373593 at $1305234U applications.", ua = "Атаки цієї істоти накладають недугу, що за $1305234U накладань спричиняє $@spellname373593." },
    { en = "|cFF00AA99Bonus Event: Dragonflight Timewalking|r\n\nDragonflight reputation gains from combat and quests increased by $s1%.", ua = "|cFF00AA99Бонусна подія: Мандри в часі Польоту Драконів|r\n\nПриріст репутації Польоту Драконів від боїв і завдань збільшено на $s1%." },
    { en = "Inflicts $1307617s1 Nature damage every $t1 sec.\nMoving within 3 yards of another egg carrier causes a $@spellname1307635.", ua = "Завдає $1307617s1 шкоди від сил природи кожні $t1 с.\nНаближення на 3 м до іншого носія яйця спричиняє $@spellname1307635." },
    { en = "Absorbing $w1 damage and applying $@spellname1307700 to all enemies every $1307768t1 sec.", ua = "Поглинає $w1 шкоди та накладає $@spellname1307700 на всіх ворогів кожні $1307768t1 с." },
}
